import React, { useState, useRef, MouseEvent } from 'react';
import { Byte } from '../types';

interface NewsSlideProps {
  byte: Byte;
  onLike: (id: string) => void;
  onSave: (id: string) => void;
}

const NewsSlide: React.FC<NewsSlideProps> = ({ byte, onLike, onSave }) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const slideRef = useRef<HTMLDivElement>(null);
  const contentCardRef = useRef<HTMLDivElement>(null);
  const metaRef = useRef<HTMLDivElement>(null);
  const bgImageRef = useRef<HTMLImageElement>(null);

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (navigator.share) {
      try {
        await navigator.share({
          title: byte.title,
          text: byte.abstract.substring(0, 100) + '...',
          url: window.location.href,
        });
      } catch (err) {
        console.log('Error sharing:', err);
      }
    } else {
      navigator.clipboard.writeText(window.location.href);
      alert('Link copied to clipboard!');
    }
  };

  const openSource = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (byte.sourceUrl) {
      window.open(byte.sourceUrl, '_blank');
    }
  };

  const toggleAudio = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsPlaying(!isPlaying);
    if (!isPlaying) {
      const msg = new SpeechSynthesisUtterance(byte.abstract);
      msg.onend = () => setIsPlaying(false);
      window.speechSynthesis.speak(msg);
    } else {
      window.speechSynthesis.cancel();
    }
  };

  const handleMouseMove = (e: MouseEvent<HTMLDivElement>) => {
    if (!slideRef.current) return;

    const { clientX, clientY } = e;
    const { innerWidth, innerHeight } = window;

    // Calculate percentage from center (-1 to 1)
    const xPct = (clientX / innerWidth - 0.5) * 2;
    const yPct = (clientY / innerHeight - 0.5) * 2;

    // Parallax intensities
    const cardTilt = 15; // degrees
    const imageMove = 20; // pixels
    const metaMove = 40; // pixels

    if (contentCardRef.current) {
      contentCardRef.current.style.transform = `
        translate(-50%, 0) 
        perspective(1000px) 
        rotateX(${-yPct * cardTilt * 0.5}deg) 
        rotateY(${xPct * cardTilt}deg)
        translateZ(20px)
      `;
    }

    if (bgImageRef.current) {
      bgImageRef.current.style.transform = `scale(1.1) translate(${-xPct * imageMove}px, ${-yPct * imageMove}px)`;
    }

    if (metaRef.current) {
      metaRef.current.style.transform = `translate(${xPct * metaMove}px, ${yPct * metaMove}px)`;
    }
  };

  const handleMouseLeave = () => {
    if (contentCardRef.current) {
      contentCardRef.current.style.transform = `translate(-50%, 0) perspective(1000px) rotateX(0) rotateY(0) translateZ(0)`;
    }
    if (bgImageRef.current) {
      bgImageRef.current.style.transform = `scale(1.1) translate(0, 0)`;
    }
    if (metaRef.current) {
      metaRef.current.style.transform = `translate(0, 0)`;
    }
  };

  return (
    <div 
      ref={slideRef}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      className="snap-slide w-full h-full bg-black relative overflow-hidden perspective-container"
      style={{ perspective: '1200px' }}
    >
      {/* Background Image with Parallax */}
      <div className="absolute inset-0 z-0">
        <img 
          ref={bgImageRef}
          src={byte.fileUrl} 
          className="w-full h-full object-cover transition-transform duration-300 ease-out will-change-transform scale-110" 
          alt={byte.title}
          loading="lazy"
        />
        <div className="absolute inset-0 bg-gradient-to-b from-black/30 via-black/10 to-black/80 pointer-events-none" />
        <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20 mix-blend-overlay pointer-events-none" />
      </div>

      {/* Side Actions Bar - 3D Floating */}
      <div className="absolute right-4 bottom-52 flex flex-col gap-6 items-center z-20">
        {[
          { icon: (
            <svg className="w-6 h-6" fill="none" stroke="currentColor" strokeWidth="2.5" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" />
            </svg>
          ), action: handleShare },
          { icon: (
            <svg className="w-6 h-6" fill="none" stroke="currentColor" strokeWidth="2.5" viewBox="0 0 24 24">
               <path strokeLinecap="round" strokeLinejoin="round" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" />
            </svg>
          ), action: () => {} },
          { icon: (
            <svg className="w-7 h-7" fill={byte.isLiked ? "currentColor" : "none"} stroke="currentColor" strokeWidth="2.5" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" />
            </svg>
          ), action: (e: any) => { e.stopPropagation(); onLike(byte.id); }, active: byte.isLiked, subText: `${(byte.likes / 1000).toFixed(1)}K` },
          { icon: (
            <svg className="w-6 h-6" fill={byte.isSaved ? "currentColor" : "none"} stroke="currentColor" strokeWidth="2.5" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" />
            </svg>
          ), action: (e: any) => { e.stopPropagation(); onSave(byte.id); }, active: byte.isSaved }
        ].map((btn, idx) => (
          <button 
            key={idx}
            onClick={btn.action}
            className={`
              w-12 h-12 rounded-full flex flex-col items-center justify-center 
              bg-black/20 backdrop-blur-md border border-white/10 
              shadow-[0_8px_16px_rgba(0,0,0,0.3)]
              transition-all duration-300 hover:scale-110 hover:bg-black/40 hover:border-white/30
              ${btn.active ? 'text-[#D9B77E] border-[#D9B77E]/50' : 'text-white'}
            `}
          >
            {btn.icon}
            {btn.subText && <span className="absolute -bottom-4 text-[9px] font-bold tracking-wide drop-shadow-md">{btn.subText}</span>}
          </button>
        ))}
      </div>

      {/* Floating Meta Overlay */}
      <div 
        ref={metaRef}
        className="absolute left-6 bottom-[360px] flex items-center gap-4 z-20 transition-transform duration-100 ease-out will-change-transform"
      >
        <div className="w-12 h-12 rounded-full bg-white/10 backdrop-blur-md flex items-center justify-center overflow-hidden border border-white/20 shadow-[0_0_20px_rgba(255,255,255,0.1)]">
          <span className="text-[12px] font-black tracking-tighter text-white">BY</span>
        </div>
        <div className="flex flex-col">
          <span className="text-white font-bold text-base tracking-tight drop-shadow-[0_2px_4px_rgba(0,0,0,0.5)]">Bytes Bits</span>
          <span className="text-[#D9B77E] text-[10px] uppercase font-bold tracking-[0.2em] drop-shadow-lg glow-text">{byte.publicationDate}</span>
        </div>
      </div>

      {/* 3D Glass Content Card */}
      <div 
        ref={contentCardRef}
        className="absolute bottom-8 left-1/2 w-[calc(100%-40px)] max-w-[480px] z-30 transition-transform duration-100 ease-out will-change-transform"
        style={{ transformStyle: 'preserve-3d', transform: 'translate(-50%, 0)' }}
      >
        <div className="
          relative bg-white/80 backdrop-blur-2xl 
          rounded-[2.5rem] p-8 
          shadow-[0_30px_60px_-12px_rgba(0,0,0,0.5),inset_0_0_0_1px_rgba(255,255,255,0.4)]
          border-t border-white/50
        ">
          {/* Shine effect */}
          <div className="absolute inset-0 rounded-[2.5rem] bg-gradient-to-tr from-white/40 via-transparent to-transparent opacity-50 pointer-events-none" />

          <div className="relative z-10">
            <h2 className="font-display text-3xl font-bold leading-[1.1] mb-4 text-[#1c1c1c] tracking-tight drop-shadow-sm">
              {byte.title}
            </h2>
            <p className="text-[16px] leading-[1.6] text-[#4a4a4a] font-medium line-clamp-5 mb-6 mix-blend-multiply">
              {byte.abstract}
            </p>

            <div className="flex items-center justify-between pt-6 border-t border-[#1c1c1c]/10">
              <div className="flex items-center gap-4">
                <button 
                  onClick={toggleAudio}
                  className={`
                    w-12 h-12 rounded-full flex items-center justify-center transition-all duration-300
                    ${isPlaying 
                      ? 'bg-[#1c1c1c] text-white scale-110 shadow-lg' 
                      : 'bg-[#1c1c1c]/5 text-[#1c1c1c] hover:bg-[#1c1c1c] hover:text-white'
                    }
                  `}
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="2.5" viewBox="0 0 24 24">
                    {isPlaying ? (
                       <path strokeLinecap="round" strokeLinejoin="round" d="M10 9v6m4-6v6m7-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                    ) : (
                       <path strokeLinecap="round" strokeLinejoin="round" d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z" />
                    )}
                  </svg>
                </button>
                <button 
                  onClick={openSource}
                  className="w-12 h-12 rounded-full bg-[#1c1c1c]/5 flex items-center justify-center text-[#1c1c1c] hover:bg-[#1c1c1c] hover:text-white transition-all duration-300"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="2.5" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M13.5 6H5.25A2.25 2.25 0 003 8.25v10.5A2.25 2.25 0 005.25 21h10.5A2.25 2.25 0 0018 18.75V10.5m-10.5 6L21 3m0 0h-5.25M21 3v5.25" />
                  </svg>
                </button>
              </div>
              <div className="flex items-center gap-2 px-3 py-1 rounded-full bg-[#D9B77E]/10 border border-[#D9B77E]/20">
                 <div className="w-1.5 h-1.5 rounded-full bg-[#D9B77E] animate-pulse" />
                 <span className="text-[10px] font-black text-[#8c744c] uppercase tracking-[0.2em]">{byte.readTime}</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default NewsSlide;

import React, { useEffect, useRef } from 'react';

const InteractiveBackground: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let width = window.innerWidth;
    let height = window.innerHeight;
    canvas.width = width;
    canvas.height = height;

    const particles: Particle[] = [];
    const particleCount = 60;

    class Particle {
      x: number;
      y: number;
      size: number;
      speedX: number;
      speedY: number;
      opacity: number;

      constructor() {
        this.x = Math.random() * width;
        this.y = Math.random() * height;
        this.size = Math.random() * 2 + 0.5;
        this.speedX = Math.random() * 0.5 - 0.25;
        this.speedY = Math.random() * 0.5 - 0.25;
        this.opacity = Math.random() * 0.5 + 0.1;
      }

      update() {
        this.x += this.speedX;
        this.y += this.speedY;

        if (this.x < 0) this.x = width;
        if (this.x > width) this.x = 0;
        if (this.y < 0) this.y = height;
        if (this.y > height) this.y = 0;
      }

      draw() {
        if (!ctx) return;
        ctx.fillStyle = `rgba(217, 183, 126, ${this.opacity})`; // #D9B77E gold color
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    for (let i = 0; i < particleCount; i++) {
      particles.push(new Particle());
    }

    const animate = () => {
      ctx.clearRect(0, 0, width, height);

      // Draw connecting lines
      ctx.lineWidth = 0.5;
      for (let i = 0; i < particleCount; i++) {
        for (let j = i; j < particleCount; j++) {
          const dx = particles[i].x - particles[j].x;
          const dy = particles[i].y - particles[j].y;
          const distance = Math.sqrt(dx * dx + dy * dy);

          if (distance < 150) {
             ctx.beginPath();
             ctx.strokeStyle = `rgba(217, 183, 126, ${0.15 * (1 - distance/150)})`;
             ctx.moveTo(particles[i].x, particles[i].y);
             ctx.lineTo(particles[j].x, particles[j].y);
             ctx.stroke();
          }
        }
      }

      particles.forEach(p => {
        p.update();
        p.draw();
      });
      requestAnimationFrame(animate);
    };

    animate();

    const handleResize = () => {
      width = window.innerWidth;
      height = window.innerHeight;
      canvas.width = width;
      canvas.height = height;
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  return (
    <canvas 
      ref={canvasRef} 
      className="fixed inset-0 z-0 bg-[#0a0a0a]"
      style={{ pointerEvents: 'none' }}
    />
  );
};

