                className="px-10 py-5 rounded-full bg-white text-black font-black text-[11px] uppercase tracking-[0.2em] hover:bg-[#D9B77E] transition-all active:scale-95 shadow-[0_10px_30px_-10px_rgba(255,255,255,0.3)]"
                >
                Adjust Curation
                </button>
            </div>
            )}
        </div>
      </div>

      <CurateDrawer 
        isOpen={isDrawerOpen} 
        onClose={() => setIsDrawerOpen(false)}
        selectedTopics={selectedTopics}
        onTopicToggle={toggleTopic}
        onSearch={setSearchTerm}
      />
    </div>
  );
};

