                { key: 'safeMode', label: 'Safe mode' }
              ].map(item => (
                <div key={item.key} className="p-5 rounded-2xl flex justify-between items-center bg-white/5 border border-white/5 backdrop-blur-sm">
                  <span className="font-bold text-sm text-white/80">{item.label}</span>
                  <button 
                    onClick={() => setPrefs(p => ({...p, constraints: {...p.constraints, [item.key]: !(p.constraints as any)[item.key]}}))}
                    className={`w-12 h-6 rounded-full relative transition-colors duration-300 ${ (prefs.constraints as any)[item.key] ? 'bg-[#D9B77E]' : 'bg-white/10'}`}
                  >
                    <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all duration-300 shadow-sm ${ (prefs.constraints as any)[item.key] ? 'left-7' : 'left-1'}`} />
                  </button>
                </div>
              ))}
            </div>
            <button 
              onClick={next} 
              className="w-full py-6 bg-white text-black font-black text-xs uppercase tracking-[0.2em] rounded-full hover:bg-[#D9B77E] transition-colors mt-4"
            >
              Finalize
            </button>
          </div>
        )}

        {/* Step 6: Loading */}
        {step === 6 && (
          <div className="space-y-8 animate-fade-in-up flex flex-col items-center justify-center w-full">
            <div className="relative">
               <div className="w-16 h-16 border-4 border-[#D9B77E]/30 rounded-full"></div>
