import React, { useEffect, useRef } from 'react';

const InteractiveBackground: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let width = window.innerWidth;
    let height = window.innerHeight;
    canvas.width = width;
    canvas.height = height;

    const particles: Particle[] = [];
    const particleCount = 45; // Slightly reduced for cleaner look with gradient

    class Particle {
      x: number;
      y: number;
      size: number;
      speedX: number;
      speedY: number;
      opacity: number;

      constructor() {
        this.x = Math.random() * width;
        this.y = Math.random() * height;
        this.size = Math.random() * 1.5 + 0.2;
        this.speedX = Math.random() * 0.3 - 0.15;
        this.speedY = Math.random() * 0.3 - 0.15;
        this.opacity = Math.random() * 0.4 + 0.1;
      }

      update() {
        this.x += this.speedX;
        this.y += this.speedY;

        if (this.x < 0) this.x = width;
        if (this.x > width) this.x = 0;
        if (this.y < 0) this.y = height;
        if (this.y > height) this.y = 0;
      }

      draw() {
        if (!ctx) return;
        ctx.fillStyle = `rgba(217, 183, 126, ${this.opacity})`; // #D9B77E gold color
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    for (let i = 0; i < particleCount; i++) {
      particles.push(new Particle());
    }

    const animate = () => {
      ctx.clearRect(0, 0, width, height);

      // Draw very subtle connecting lines
      ctx.lineWidth = 0.3;
      for (let i = 0; i < particleCount; i++) {
        for (let j = i; j < particleCount; j++) {
          const dx = particles[i].x - particles[j].x;
          const dy = particles[i].y - particles[j].y;
          const distance = Math.sqrt(dx * dx + dy * dy);

          if (distance < 120) {
             ctx.beginPath();
             ctx.strokeStyle = `rgba(217, 183, 126, ${0.1 * (1 - distance/120)})`;
             ctx.moveTo(particles[i].x, particles[i].y);
             ctx.lineTo(particles[j].x, particles[j].y);
             ctx.stroke();
          }
        }
      }

      particles.forEach(p => {
        p.update();
        p.draw();
      });
      requestAnimationFrame(animate);
    };

    animate();

    const handleResize = () => {
      width = window.innerWidth;
      height = window.innerHeight;
      canvas.width = width;
      canvas.height = height;
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  return (
    <div className="fixed inset-0 z-0 overflow-hidden bg-[#050505]">
      {/* CSS Styles for the ambient animations */}
      <style>{`
        @keyframes float-slow {
          0%, 100% { transform: translate(0, 0) scale(1); }
          33% { transform: translate(30px, -50px) scale(1.1); }
          66% { transform: translate(-20px, 20px) scale(0.9); }
        }
        @keyframes float-slower {
          0%, 100% { transform: translate(0, 0) scale(1); }
          50% { transform: translate(-30px, 40px) scale(1.15); }
        }
        .animate-float-slow { animation: float-slow 15s ease-in-out infinite; }
        .animate-float-slower { animation: float-slower 20s ease-in-out infinite; }
      `}</style>

      {/* Atmospheric Gradient Mesh */}
      {/* 1. Warm Gold Glow (Top Right) */}
      <div 
        className="absolute -top-[10%] -right-[10%] w-[80vw] h-[80vw] rounded-full mix-blend-screen opacity-20 animate-float-slow pointer-events-none"
        style={{ background: 'radial-gradient(circle, rgba(217,183,126,0.3) 0%, rgba(0,0,0,0) 70%)', filter: 'blur(80px)' }}
      />

      {/* 2. Deep Slate/Blue Depth (Bottom Left) */}
      <div 
        className="absolute -bottom-[20%] -left-[10%] w-[90vw] h-[90vw] rounded-full mix-blend-screen opacity-20 animate-float-slower pointer-events-none"
        style={{ background: 'radial-gradient(circle, rgba(30,41,59,0.6) 0%, rgba(0,0,0,0) 70%)', filter: 'blur(100px)' }}
      />

      {/* 3. Central Ambient Light (Center) */}
      <div 
        className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-full h-full opacity-30 pointer-events-none"
        style={{ background: 'radial-gradient(circle, rgba(255,255,255,0.03) 0%, rgba(0,0,0,0) 100%)' }}
      />

      {/* Canvas Particles on top */}
      <canvas ref={canvasRef} className="absolute inset-0 block" />

      {/* Vignette Overlay to focus center */}
      <div className="absolute inset-0 pointer-events-none bg-[radial-gradient(circle_at_center,transparent_0%,rgba(0,0,0,0.6)_100%)]" />
    </div>
  );
};

