import React, { useState, useRef, MouseEvent } from 'react';
import { Byte } from '../types';

interface NewsSlideProps {
  byte: Byte;
  onLike: (id: string) => void;
  onSave: (id: string) => void;
}

const NewsSlide: React.FC<NewsSlideProps> = ({ byte, onLike, onSave }) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const cardRef = useRef<HTMLDivElement>(null);

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (navigator.share) {
      try {
        await navigator.share({
          title: byte.title,
          text: byte.abstract.substring(0, 100) + '...',
          url: window.location.href,
        });
      } catch (err) {
        console.log('Error sharing:', err);
      }
    } else {
      navigator.clipboard.writeText(window.location.href);
      alert('Link copied!');
    }
  };

  const toggleAudio = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsPlaying(!isPlaying);
    if (!isPlaying) {
      const msg = new SpeechSynthesisUtterance(byte.abstract);
      msg.onend = () => setIsPlaying(false);
      window.speechSynthesis.speak(msg);
    } else {
      window.speechSynthesis.cancel();
    }
  };

  // Soft 3D Tilt Effect
  const handleMouseMove = (e: MouseEvent<HTMLDivElement>) => {
    if (!containerRef.current || !cardRef.current) return;

    const { clientX, clientY } = e;
    const { innerWidth, innerHeight } = window;

    const xPct = (clientX / innerWidth - 0.5) * 2; // -1 to 1
    const yPct = (clientY / innerHeight - 0.5) * 2; // -1 to 1

    const tiltX = -yPct * 5; // Slight tilt
    const tiltY = xPct * 5; 

    cardRef.current.style.transform = `perspective(1000px) rotateX(${tiltX}deg) rotateY(${tiltY}deg) scale(1.02)`;
  };

  const handleMouseLeave = () => {
    if (cardRef.current) {
      cardRef.current.style.transform = `perspective(1000px) rotateX(0) rotateY(0) scale(1)`;
    }
  };

  return (
    <div 
      ref={containerRef}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      className="snap-slide w-full h-full flex items-center justify-center p-4"
    >
      {/* Main Glass Card */}
      <div 
        ref={cardRef}
        className="glass-card w-full max-w-[420px] rounded-[3rem] overflow-hidden flex flex-col relative transition-transform duration-200 ease-out"
        style={{ maxHeight: '80vh' }}
      >

        {/* Image Header with soft gradient overlay */}
        <div className="relative h-[45%] w-full flex-shrink-0">
           <img 
             src={byte.fileUrl} 
             alt={byte.title}
             className="w-full h-full object-cover"
           />
           {/* Soft gradient fade into content */}
           <div className="absolute inset-0 bg-gradient-to-b from-transparent to-white/90" />

           {/* Floating Tag */}
           <div className="absolute top-6 left-6 px-4 py-2 bg-white/80 backdrop-blur-md rounded-full shadow-sm border border-white">
              <span className="text-xs font-bold text-[#FF7043] tracking-wider uppercase">{byte.category}</span>
           </div>
        </div>

        {/* Content Body */}
        <div className="flex-1 px-8 pb-8 pt-2 flex flex-col bg-white/80 backdrop-blur-xl relative">

            {/* Meta */}
            <div className="flex items-center gap-2 mb-3 opacity-60">
               <span className="text-[10px] font-bold uppercase tracking-widest text-[#3E2723]">{byte.publisher}</span>
               <span className="w-1 h-1 rounded-full bg-[#3E2723]" />
               <span className="text-[10px] font-bold uppercase tracking-widest text-[#3E2723]">{byte.readTime}</span>
            </div>

            {/* Title */}
            <h2 className="font-display text-2xl font-bold leading-tight text-[#3E2723] mb-4 drop-shadow-sm">
              {byte.title}
            </h2>

            {/* Abstract */}
            <div className="flex-1 overflow-y-auto no-scrollbar mask-fade-bottom">
               <p className="text-[#5D4037] text-base leading-relaxed font-medium">
                 {byte.abstract}
               </p>
            </div>

            {/* Action Row - Floating Pill Style */}
            <div className="mt-6 flex items-center justify-between">
               <div className="flex gap-3">
                  <button 
                    onClick={toggleAudio}
                    className={`w-12 h-12 rounded-full flex items-center justify-center transition-all shadow-sm ${isPlaying ? 'bg-[#FF7043] text-white' : 'bg-white text-[#5D4037] hover:bg-gray-50'}`}
                  >
                     <svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 14.142m-5.598-9.598a3 3 0 013.064 5.856m-8.914.544l-2.122 2.121-1.414-1.414 2.122-2.121a3 3 0 014.242 0l2.122 2.121-1.414 1.414-2.122-2.121a1 1 0 00-1.414 0z" /></svg>
                  </button>
                  <button 
                    onClick={handleShare}
                    className="w-12 h-12 rounded-full bg-white flex items-center justify-center text-[#5D4037] shadow-sm hover:bg-gray-50 transition-all"
                  >
                     <svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" /></svg>
                  </button>
               </div>

               <div className="flex gap-3">
                  <button 
                     onClick={(e) => { e.stopPropagation(); onLike(byte.id); }}
                     className={`px-5 h-12 rounded-full flex items-center gap-2 font-bold text-sm shadow-sm transition-all ${byte.isLiked ? 'bg-[#FBC02D] text-[#3E2723]' : 'bg-white text-[#5D4037] hover:bg-gray-50'}`}
                  >
                     <svg className="w-5 h-5" fill={byte.isLiked ? "currentColor" : "none"} stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" /></svg>
                     {byte.isLiked && <span>{byte.likes}</span>}
                  </button>
                  <button 
                     onClick={(e) => { e.stopPropagation(); onSave(byte.id); }}
                     className={`w-12 h-12 rounded-full flex items-center justify-center transition-all shadow-sm ${byte.isSaved ? 'bg-[#3E2723] text-white' : 'bg-white text-[#5D4037] hover:bg-gray-50'}`}
                  >
                     <svg className="w-5 h-5" fill={byte.isSaved ? "currentColor" : "none"} stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" /></svg>
                  </button>
               </div>
            </div>

        </div>
      </div>
    </div>
  );
};

