import React, { useState } from 'react';
import { UserPreferences } from '../types';

interface OnboardingProps {
  onComplete: (prefs: UserPreferences) => void;
}

const Onboarding: React.FC<OnboardingProps> = ({ onComplete }) => {
  const [step, setStep] = useState(1);
  const [prefs, setPrefs] = useState<UserPreferences>({
    topics: [],
    readingStyle: 'Brief summaries',
    tone: 'Straight facts',
    constraints: {
      noClickbait: true,
      fewerCelebrity: false,
      expertSources: true,
      safeMode: false
    }
  });

  const topicsList = ['AI & Tech', 'Startups', 'Global Markets', 'Policy', 'Geopolitics', 'Climate', 'Culture', 'Science', 'Finance', 'Health'];

  const toggleTopic = (topic: string) => {
    setPrefs(p => ({
      ...p,
      topics: p.topics.includes(topic) ? p.topics.filter(t => t !== topic) : [...p.topics, topic]
    }));
  };

  const next = () => setStep(s => s + 1);

  return (
    <div className="fixed inset-0 z-[100] flex flex-col items-center justify-center p-8 text-center animate-fade-in bg-gradient-to-br from-[#FADBC6] to-[#F1B6A2]">
      {/* Glass Container */}
      <div className="max-w-md w-full glass-card p-10 rounded-[3rem] shadow-2xl relative z-20 flex flex-col items-center">

        {/* Step 1: Welcome */}
        {step === 1 && (
          <div className="space-y-10 animate-fade-in-up flex flex-col items-center">

            <div className="w-24 h-24 bg-[#FF7043] rounded-3xl flex items-center justify-center text-white font-display text-5xl shadow-xl shadow-orange-200/50 rotate-6">
               <span className="font-black">B</span>
            </div>

            <div className="space-y-4">
              <h1 className="text-4xl font-display font-bold text-[#3E2723] tracking-tight">Focus.</h1>
              <p className="text-lg text-[#5D4037] font-medium leading-relaxed">
                The internet's noise, decoded into <span className="text-[#FF7043] font-bold">signals</span>.
              </p>
            </div>

            <button 
              onClick={next} 
              className="w-full py-5 bg-[#3E2723] text-white font-bold text-sm uppercase tracking-widest rounded-full hover:scale-105 transition-all shadow-lg"
            >
              Start Curation
            </button>
          </div>
        )}

        {/* Step 2: Topics */}
        {step === 2 && (
          <div className="space-y-8 animate-fade-in-up w-full">
            <div className="space-y-2 text-left">
              <h2 className="text-3xl font-display font-bold text-[#3E2723]">Your Sphere</h2>
              <p className="text-xs text-[#FF7043] font-bold uppercase tracking-widest">Select 3+ topics</p>
            </div>

            <div className="flex flex-wrap gap-2 justify-center">
              {topicsList.map(t => (
                <button 
                  key={t}
                  onClick={() => toggleTopic(t)}
                  className={`
                    px-5 py-3 rounded-full text-xs font-bold uppercase tracking-wide border transition-all duration-200
                    ${prefs.topics.includes(t) 
                      ? 'bg-[#FF7043] text-white border-[#FF7043] shadow-md' 
                      : 'bg-white text-[#5D4037] border-white/50 hover:bg-white/80'}
                  `}
                >
                  {t}
                </button>
              ))}
            </div>

            <button 
              disabled={prefs.topics.length < 3} 
              onClick={next} 
              className="w-full py-5 bg-[#3E2723] text-white font-bold text-sm uppercase tracking-widest rounded-full disabled:opacity-50 disabled:scale-100 hover:scale-105 transition-all shadow-lg"
            >
              Continue
            </button>
          </div>
        )}

        {/* Step 3: Style */}
        {step === 3 && (
          <div className="space-y-8 animate-fade-in-up w-full">
            <div className="space-y-2 text-left">
              <h2 className="text-3xl font-display font-bold text-[#3E2723]">Velocity</h2>
              <p className="text-sm text-[#795548]">How deep do you want to go?</p>
            </div>

            <div className="space-y-3">
              {['Ultra quick (10s)', 'Brief summaries', 'Deep dives'].map(style => (
                <button 
                  key={style}
                  onClick={() => { setPrefs(p => ({...p, readingStyle: style.split(' (')[0] as any})); next(); }}
                  className={`
                    w-full p-5 rounded-2xl flex justify-between items-center group transition-all border
                    ${prefs.readingStyle === style.split(' (')[0] 
                      ? 'bg-[#FF7043] border-[#FF7043] text-white shadow-md' 
                      : 'bg-white border-white/60 text-[#5D4037] hover:bg-white/80'}
                  `}
                >
                  <span className="font-bold text-sm">{style}</span>
                </button>
              ))}
            </div>
          </div>
        )}

        {/* Step 4: Constraints */}
        {step === 4 && (
          <div className="space-y-8 animate-fade-in-up w-full">
            <div className="space-y-2 text-left">
              <h2 className="text-3xl font-display font-bold text-[#3E2723]">Filters</h2>
            </div>

            <div className="space-y-3">
              {[
                { key: 'noClickbait', label: 'Block clickbait' },
                { key: 'fewerCelebrity', label: 'Limit celebrity' },
                { key: 'expertSources', label: 'Expert sources' },
              ].map(item => (
                <div key={item.key} className="p-4 rounded-2xl flex justify-between items-center bg-white border border-white/50 shadow-sm">
                  <span className="font-bold text-sm text-[#5D4037]">{item.label}</span>
                  <button 
                    onClick={() => setPrefs(p => ({...p, constraints: {...p.constraints, [item.key]: !(p.constraints as any)[item.key]}}))}
                    className={`w-12 h-7 rounded-full relative transition-colors duration-300 ${ (prefs.constraints as any)[item.key] ? 'bg-[#FF7043]' : 'bg-gray-200'}`}
                  >
                    <div className={`absolute top-1 w-5 h-5 bg-white rounded-full transition-all duration-300 shadow-sm ${ (prefs.constraints as any)[item.key] ? 'left-6' : 'left-1'}`} />
                  </button>
                </div>
              ))}
            </div>
            <button 
              onClick={next} 
              className="w-full py-5 bg-[#3E2723] text-white font-bold text-sm uppercase tracking-widest rounded-full hover:scale-105 transition-all shadow-lg mt-4"
            >
              Finish
            </button>
          </div>
        )}

        {/* Step 5: Loading */}
        {step === 5 && (
          <div className="space-y-8 animate-fade-in-up flex flex-col items-center justify-center w-full py-10">
            <div className="relative">
               <div className="w-16 h-16 border-4 border-[#FF7043]/20 rounded-full"></div>
               <div className="absolute top-0 left-0 w-16 h-16 border-4 border-[#FF7043] border-t-transparent rounded-full animate-spin"></div>
            </div>
            <div className="text-center">
                <h2 className="text-2xl font-display font-bold text-[#3E2723] mb-2">Building Feed</h2>
                <p className="text-xs text-[#FF7043] font-bold uppercase tracking-widest">
                  Focusing content...
                </p>
            </div>
            {setTimeout(() => onComplete(prefs), 2000) && null}
          </div>
        )}

      </div>
    </div>
  );
};

export default Onboarding;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import Navbar from './components/Navbar';
import NewsSlide from './components/NewsSlide';
import CurateDrawer from './components/CurateDrawer';
import Onboarding from './components/Onboarding';
import InteractiveBackground from './components/InteractiveBackground';
import { PAPERS } from './constants';
import { Byte, UserPreferences } from './types';

const App: React.FC = () => {
  const [news, setNews] = useState<Byte[]>([]);
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [showOnboarding, setShowOnboarding] = useState<boolean>(true);
  const [selectedTopics, setSelectedTopics] = useState<string[]>(['US News', 'World', 'AI & Tech', 'Business', 'Science', 'Finance', 'Culture']);
  const [searchTerm, setSearchTerm] = useState('');
  const feedRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const hasSeenOnboarding = localStorage.getItem('bytes_onboarded') === 'true';
    if (hasSeenOnboarding) {
      setShowOnboarding(false);
    }
    const storedPrefs = localStorage.getItem('bytes_prefs');
    if (storedPrefs) {
      const prefs = JSON.parse(storedPrefs) as UserPreferences;
      if (prefs.topics && prefs.topics.length > 0) {
        setSelectedTopics(prefs.topics);
      }
    }

    setNews(PAPERS.map(p => ({ ...p, isLiked: false, isSaved: false })));
  }, []);

  const handleOnboardingComplete = (prefs: UserPreferences) => {
    setShowOnboarding(false);
    setSelectedTopics(prefs.topics);
    localStorage.setItem('bytes_onboarded', 'true');
    localStorage.setItem('bytes_prefs', JSON.stringify(prefs));
  };

  const handleLike = (id: string) => {
    setNews(prev => prev.map(item => 
      item.id === id ? { ...item, isLiked: !item.isLiked, likes: item.isLiked ? item.likes - 1 : item.likes + 1 } : item
    ));
  };

  const handleSave = (id: string) => {
    setNews(prev => prev.map(item => 
      item.id === id ? { ...item, isSaved: !item.isSaved } : item
    ));
  };

  const toggleTopic = (topic: string) => {
    setSelectedTopics(prev => 
      prev.includes(topic) ? prev.filter(t => t !== topic) : [...prev, topic]
    );
  };

  const filteredNews = useMemo(() => {
    return news.filter(byte => {
      const matchesTopic = selectedTopics.includes(byte.category);
      const matchesSearch = searchTerm === '' || 
        byte.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
        byte.abstract.toLowerCase().includes(searchTerm.toLowerCase());
      return matchesTopic && matchesSearch;
    });
  }, [news, selectedTopics, searchTerm]);

  return (
    <div className="relative h-screen overflow-hidden flex flex-col items-center">
      {/* Dynamic Background */}
      <InteractiveBackground />

      {showOnboarding ? (
        <Onboarding onComplete={handleOnboardingComplete} />
      ) : (
        <>
          {/* Main Content Area - Scales down when drawer is open */}
          <div 
            className={`
              relative z-10 w-full h-full flex flex-col items-center transition-all duration-500 ease-[cubic-bezier(0.32,0.72,0,1)]
              ${isDrawerOpen ? 'scale-95 opacity-50 blur-[2px] translate-x-[-20px] pointer-events-none' : 'scale-100 opacity-100 translate-x-0'}
            `}
            style={{ transformOrigin: 'center center' }}
          >
            <Navbar 
                onProfileClick={() => setIsDrawerOpen(true)}
                onSearchClick={() => setIsDrawerOpen(true)}
                onNotifyClick={() => alert('No new notifications')}
            />

            <div 
                ref={feedRef}
                className="feed-container w-full h-full pt-20"
            >
                {filteredNews.length > 0 ? (
                filteredNews.map(byte => (
                    <NewsSlide 
                    key={byte.id} 
                    byte={byte} 
                    onLike={handleLike} 
                    onSave={handleSave} 
                    />
                ))
                ) : (
                <div className="h-full flex flex-col items-center justify-center text-center p-8">
                    <div className="w-20 h-20 rounded-full bg-white/50 flex items-center justify-center mb-6 shadow-sm">
                      <svg className="w-10 h-10 text-[#FF7043]" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
                      </svg>
                    </div>
                    <h3 className="text-2xl font-display font-bold text-[#3E2723] mb-2">It's quiet here.</h3>
                    <p className="text-sm text-[#795548] mb-8 leading-relaxed max-w-xs mx-auto">Try expanding your curation settings to see more stories.</p>
                    <button 
                    onClick={() => setIsDrawerOpen(true)}
                    className="px-8 py-4 rounded-full bg-[#3E2723] text-white font-bold text-xs uppercase tracking-widest hover:scale-105 transition-all shadow-lg"
                    >
                    Adjust Curation
                    </button>
                </div>
                )}
            </div>
          </div>

          <CurateDrawer 
            isOpen={isDrawerOpen} 
            onClose={() => setIsDrawerOpen(false)}
            selectedTopics={selectedTopics}
            onTopicToggle={toggleTopic}
            onSearch={setSearchTerm}
          />
        </>
      )}
    </div>
  );
};

