import React, { useState, useRef, MouseEvent } from 'react';
import { Byte } from '../types';

interface NewsSlideProps {
  byte: Byte;
  onLike: (id: string) => void;
  onSave: (id: string) => void;
}

const NewsSlide: React.FC<NewsSlideProps> = ({ byte, onLike, onSave }) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const cardRef = useRef<HTMLDivElement>(null);
  const imageRef = useRef<HTMLImageElement>(null);

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (navigator.share) {
      try {
        await navigator.share({
          title: byte.title,
          text: byte.abstract.substring(0, 100) + '...',
          url: window.location.href,
        });
      } catch (err) {
        console.log('Error sharing:', err);
      }
    } else {
      navigator.clipboard.writeText(window.location.href);
      alert('Link copied!');
    }
  };

  const toggleAudio = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsPlaying(!isPlaying);
    if (!isPlaying) {
      const msg = new SpeechSynthesisUtterance(byte.abstract);
      msg.onend = () => setIsPlaying(false);
      window.speechSynthesis.speak(msg);
    } else {
      window.speechSynthesis.cancel();
    }
  };

  const handleMouseMove = (e: MouseEvent<HTMLDivElement>) => {
    if (!containerRef.current || !cardRef.current) return;

    const { clientX, clientY } = e;
    const { innerWidth, innerHeight } = window;

    // Calculate percentage from center (-1 to 1)
    const xPct = (clientX / innerWidth - 0.5) * 2; 
    const yPct = (clientY / innerHeight - 0.5) * 2;

    const tiltX = -yPct * 8; // Max tilt degrees X
    const tiltY = xPct * 8;  // Max tilt degrees Y

    cardRef.current.style.transform = `perspective(1200px) rotateX(${tiltX}deg) rotateY(${tiltY}deg) scale(1.02)`;

    // Parallax the image slightly
    if (imageRef.current) {
        imageRef.current.style.transform = `scale(1.1) translate(${xPct * 10}px, ${yPct * 10}px)`;
    }
  };

  const handleMouseLeave = () => {
    if (cardRef.current) {
      cardRef.current.style.transform = `perspective(1200px) rotateX(0) rotateY(0) scale(1)`;
    }
    if (imageRef.current) {
        imageRef.current.style.transform = `scale(1.1) translate(0, 0)`;
    }
  };

  return (
    <div 
      ref={containerRef}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      className="snap-slide w-full flex items-center justify-center p-4 md:p-8"
    >
      <div className="relative w-full max-w-[400px]">

          {/* Floating Actions - Left Side */}
          <div className="absolute -left-16 bottom-20 flex flex-col gap-4 z-10 hidden md:flex">
             <button 
                onClick={(e) => { e.stopPropagation(); onLike(byte.id); }}
                className={`w-12 h-12 rounded-full flex items-center justify-center shadow-lg transition-all hover:scale-110 ${byte.isLiked ? 'bg-[#FF6B6B] text-white' : 'bg-white/80 backdrop-blur-md text-[#5D5450] hover:bg-white'}`}
             >
                <svg className="w-5 h-5" fill={byte.isLiked ? "currentColor" : "none"} stroke="currentColor" strokeWidth="2.5" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" /></svg>
             </button>
             <button 
                onClick={handleShare}
                className="w-12 h-12 rounded-full bg-white/80 backdrop-blur-md flex items-center justify-center text-[#5D5450] shadow-lg transition-all hover:scale-110 hover:bg-white"
             >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="2.5" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" /></svg>
             </button>
          </div>

          {/* Floating Actions - Right Side */}
           <div className="absolute -right-16 bottom-20 flex flex-col gap-4 z-10 hidden md:flex">
             <button 
                onClick={toggleAudio}
                className={`w-12 h-12 rounded-full flex items-center justify-center shadow-lg transition-all hover:scale-110 ${isPlaying ? 'bg-[#2D2420] text-white' : 'bg-white/80 backdrop-blur-md text-[#5D5450] hover:bg-white'}`}
             >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="2.5" viewBox="0 0 24 24">
                    {isPlaying ? (
                       <path strokeLinecap="round" strokeLinejoin="round" d="M10 9v6m4-6v6m7-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                    ) : (
                       <path strokeLinecap="round" strokeLinejoin="round" d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z" />
                    )}
                  </svg>
             </button>
             <button 
                onClick={(e) => { e.stopPropagation(); onSave(byte.id); }}
                className={`w-12 h-12 rounded-full flex items-center justify-center shadow-lg transition-all hover:scale-110 ${byte.isSaved ? 'bg-[#2D2420] text-white' : 'bg-white/80 backdrop-blur-md text-[#5D5450] hover:bg-white'}`}
             >
                <svg className="w-5 h-5" fill={byte.isSaved ? "currentColor" : "none"} stroke="currentColor" strokeWidth="2.5" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" /></svg>
             </button>
          </div>

          {/* THE CARD */}
          <div 
            ref={cardRef}
            className="frosted-slab rounded-[3rem] overflow-hidden flex flex-col transition-transform duration-150 ease-out"
            style={{ transformStyle: 'preserve-3d' }}
          >
             {/* 1. Top Section - Image & Tag */}
             <div className="relative h-[280px] w-full p-3">
                 <div className="w-full h-full rounded-[2.5rem] overflow-hidden relative shadow-inner">
                    <img 
                        ref={imageRef}
                        src={byte.fileUrl} 
                        className="w-full h-full object-cover transition-transform duration-300 ease-out will-change-transform scale-110" 
                        alt={byte.title}
                    />
                    <div className="absolute inset-0 bg-black/10 mix-blend-multiply" />

                    {/* Category Tag Pill */}
                    <div className="absolute top-4 left-4 px-4 py-1.5 bg-white/90 backdrop-blur rounded-full shadow-md z-10">
                        <span className="text-[10px] font-bold text-[#FF6B6B] uppercase tracking-widest">{byte.category}</span>
                    </div>

                    {/* Read Time Pill */}
                    <div className="absolute bottom-4 right-4 px-3 py-1 bg-black/40 backdrop-blur-md rounded-full border border-white/20">
                         <span className="text-[10px] font-bold text-white uppercase tracking-widest">{byte.readTime}</span>
                    </div>
                 </div>
             </div>

             {/* 2. Bottom Section - Content */}
             <div className="p-8 pt-2 flex flex-col gap-4 relative">
                 <div className="flex items-center gap-2 mb-1">
                    <div className="w-2 h-2 rounded-full bg-[#2D2420]" />
                    <span className="text-xs font-bold text-[#8C8881] uppercase tracking-widest">{byte.publisher}</span>
                 </div>

                 <h2 className="font-serif-display text-3xl text-[#2D2420] leading-[1.05] tracking-tight">
                    {byte.title}
                 </h2>

                 <p className="text-[#5D5450] text-[15px] leading-relaxed font-medium line-clamp-6">
                    {byte.abstract}
                 </p>

                 {/* Mobile Actions (Visible only on small screens) */}
                 <div className="flex md:hidden items-center justify-between mt-4 pt-4 border-t border-[#2D2420]/5">
                     <div className="flex gap-4">
                        <button onClick={(e) => { e.stopPropagation(); onLike(byte.id); }} className={`${byte.isLiked ? 'text-[#FF6B6B]' : 'text-[#8C8881]'}`}>
                            <svg className="w-6 h-6" fill={byte.isLiked ? "currentColor" : "none"} stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" /></svg>
                        </button>
                        <button onClick={handleShare} className="text-[#8C8881]">
                            <svg className="w-6 h-6" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" /></svg>
                        </button>
                     </div>
                     <button onClick={toggleAudio} className={`p-2 rounded-full ${isPlaying ? 'bg-[#2D2420] text-white' : 'bg-[#EAE5E0] text-[#2D2420]'}`}>
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
                           {isPlaying ? <path strokeLinecap="round" strokeLinejoin="round" d="M10 9v6m4-6v6m7-3a9 9 0 11-18 0 9 9 0 0118 0z" /> : <path strokeLinecap="round" strokeLinejoin="round" d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z" />}
                        </svg>
                     </button>
                 </div>
             </div>

             {/* Decorative shine on glass */}
             <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-br from-white/30 to-transparent opacity-50 pointer-events-none rounded-[3rem]" />
          </div>
      </div>
    </div>
  );
};

