import React, { useState, useRef, MouseEvent } from 'react';
import { Byte } from '../types';

interface NewsSlideProps {
  byte: Byte;
  onLike: (id: string) => void;
  onSave: (id: string) => void;
}

const NewsSlide: React.FC<NewsSlideProps> = ({ byte, onLike, onSave }) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const windowRef = useRef<HTMLDivElement>(null);

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (navigator.share) {
      try {
        await navigator.share({
          title: byte.title,
          text: byte.abstract.substring(0, 100) + '...',
          url: window.location.href,
        });
      } catch (err) {
        console.log('Error sharing:', err);
      }
    } else {
      navigator.clipboard.writeText(window.location.href);
      alert('Link copied!');
    }
  };

  const toggleAudio = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsPlaying(!isPlaying);
    if (!isPlaying) {
      const msg = new SpeechSynthesisUtterance(byte.abstract);
      msg.onend = () => setIsPlaying(false);
      window.speechSynthesis.speak(msg);
    } else {
      window.speechSynthesis.cancel();
    }
  };

  // Spatial Tilt Effect
  const handleMouseMove = (e: MouseEvent<HTMLDivElement>) => {
    if (!containerRef.current || !windowRef.current) return;

    const { clientX, clientY } = e;
    const { innerWidth, innerHeight } = window;

    const xPct = (clientX / innerWidth - 0.5) * 2; 
    const yPct = (clientY / innerHeight - 0.5) * 2;

    const tiltX = -yPct * 4; 
    const tiltY = xPct * 4; 

    // Subtle movement and rotation
    windowRef.current.style.transform = `perspective(1000px) rotateX(${tiltX}deg) rotateY(${tiltY}deg) translateZ(10px)`;
  };

  const handleMouseLeave = () => {
    if (windowRef.current) {
      windowRef.current.style.transform = `perspective(1000px) rotateX(0) rotateY(0) translateZ(0)`;
    }
  };

  return (
    <div 
      ref={containerRef}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      className="snap-slide w-full flex items-center justify-center p-6 md:p-8"
    >
      {/* The Spatial Window */}
      <div 
        ref={windowRef}
        className="vision-window w-full max-w-[550px] rounded-[32px] overflow-hidden flex flex-col relative transition-transform duration-200 ease-out"
        style={{ height: 'auto', minHeight: '600px', transformStyle: 'preserve-3d' }}
      >

        {/* Glass Header Bar (Like window controls) */}
        <div className="absolute top-0 left-0 right-0 h-14 flex items-center justify-between px-6 z-20 bg-gradient-to-b from-white/5 to-transparent pointer-events-none">
           <div className="flex items-center gap-2">
             <div className="w-1.5 h-1.5 rounded-full bg-white/40" />
             <span className="text-[11px] font-medium tracking-wide text-white/60 uppercase">{byte.publisher}</span>
           </div>
           <div className="px-3 py-1 rounded-full bg-white/10 backdrop-blur-md border border-white/5 shadow-sm">
             <span className="text-[10px] font-bold text-white/90 tracking-wider uppercase">{byte.category}</span>
           </div>
        </div>

        {/* Hero Image Area */}
        <div className="relative w-full h-64 md:h-72 shrink-0 group overflow-hidden">
           <img 
             src={byte.fileUrl} 
             alt={byte.title}
             className="w-full h-full object-cover transition-transform duration-700 ease-out group-hover:scale-105 opacity-90"
           />
           {/* Inner Shadow Gradient */}
           <div className="absolute inset-0 bg-gradient-to-t from-[#1E1E1E] via-transparent to-transparent opacity-80" />
        </div>

        {/* Content Area */}
        <div className="flex-1 p-8 pt-4 flex flex-col">
            <div className="mb-6">
              <h2 className="text-3xl font-bold leading-tight tracking-tight text-white mb-3 drop-shadow-lg">
                {byte.title}
              </h2>
              <div className="flex items-center gap-2 text-white/40 text-xs font-medium">
                 <span>{byte.publicationDate}</span>
                 <span>•</span>
                 <span>{byte.readTime}</span>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto no-scrollbar mask-fade-bottom pr-2">
               <p className="text-[17px] leading-relaxed text-white/80 font-light">
                 {byte.abstract}
               </p>
            </div>

            {/* Action Bar (Integrated into window) */}
            <div className="mt-8 pt-6 border-t border-white/10 flex items-center justify-between">
                <div className="flex gap-4">
                  <button 
                    onClick={toggleAudio} 
                    className={`vision-btn flex items-center gap-2 px-4 py-2.5 rounded-full transition-all ${isPlaying ? 'bg-white text-black' : 'bg-white/5 text-white/70 hover:text-white'}`}
                  >
                     <svg className="w-4 h-4" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
                       {isPlaying ? <path strokeLinecap="round" strokeLinejoin="round" d="M10 9v6m4-6v6m7-3a9 9 0 11-18 0 9 9 0 0118 0z" /> : <path strokeLinecap="round" strokeLinejoin="round" d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z" />}
                     </svg>
                     <span className="text-xs font-medium">Listen</span>
                  </button>
                  <button onClick={handleShare} className="vision-btn p-2.5 rounded-full bg-white/5 text-white/70 hover:text-white">
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" /></svg>
                  </button>
                </div>

                <div className="flex gap-3">
                   <button 
                      onClick={(e) => { e.stopPropagation(); onLike(byte.id); }}
                      className={`vision-btn flex items-center gap-2 px-4 py-2.5 rounded-full transition-all ${byte.isLiked ? 'bg-pink-500/20 text-pink-400 ring-1 ring-pink-500/50' : 'bg-white/5 text-white/70 hover:text-white'}`}
                   >
                      <svg className="w-4 h-4" fill={byte.isLiked ? "currentColor" : "none"} stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" /></svg>
                      {byte.isLiked && <span className="text-xs font-medium">{byte.likes}</span>}
                   </button>
                   <button 
                      onClick={(e) => { e.stopPropagation(); onSave(byte.id); }}
                      className={`vision-btn p-2.5 rounded-full transition-all ${byte.isSaved ? 'bg-white text-black' : 'bg-white/5 text-white/70 hover:text-white'}`}
                   >
                      <svg className="w-4 h-4" fill={byte.isSaved ? "currentColor" : "none"} stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" /></svg>
                   </button>
                </div>
            </div>

        </div>
      </div>
    </div>
  );
};

export default NewsSlide;

