import React, { useState } from 'react';
import { UserPreferences } from '../types';

interface OnboardingProps {
  onComplete: (prefs: UserPreferences) => void;
}

const Onboarding: React.FC<OnboardingProps> = ({ onComplete }) => {
  const [step, setStep] = useState(1);
  const [prefs, setPrefs] = useState<UserPreferences>({
    topics: [],
    readingStyle: 'Brief summaries',
    tone: 'Straight facts',
    constraints: {
      noClickbait: true,
      fewerCelebrity: false,
      expertSources: true,
      safeMode: false
    }
  });

  const topicsList = ['AI & Tech', 'Startups', 'Global Markets', 'Policy', 'Geopolitics', 'Climate', 'Culture', 'Science', 'Finance', 'Health'];

  const toggleTopic = (topic: string) => {
    setPrefs(p => ({
      ...p,
      topics: p.topics.includes(topic) ? p.topics.filter(t => t !== topic) : [...p.topics, topic]
    }));
  };

  const next = () => setStep(s => s + 1);

  return (
    <div className="fixed inset-0 z-[100] flex flex-col items-center justify-center p-6 bg-black/50 backdrop-blur-md animate-enter">

      {/* Vision Window Modal */}
      <div className="vision-window max-w-[500px] w-full p-10 rounded-[40px] flex flex-col items-center text-center shadow-[0_0_100px_rgba(0,0,0,0.5)]">

        {/* Step 1: Intro */}
        {step === 1 && (
          <div className="flex flex-col items-center space-y-8 w-full animate-enter">
            <div className="w-20 h-20 rounded-[24px] bg-gradient-to-tr from-blue-500 to-indigo-600 shadow-[0_0_40px_rgba(79,70,229,0.4)] flex items-center justify-center text-3xl font-bold text-white mb-2">
              B
            </div>

            <div className="space-y-3">
              <h1 className="text-3xl font-bold text-white tracking-tight">Welcome to Bytes</h1>
              <p className="text-white/60 text-lg leading-relaxed">
                A spatial news experience designed for clarity.
              </p>
            </div>

            <button 
              onClick={next} 
              className="w-full py-4 rounded-full bg-white text-black font-semibold text-base hover:bg-white/90 transition-all shadow-[0_0_20px_rgba(255,255,255,0.1)]"
            >
              Get Started
            </button>
          </div>
        )}

        {/* Step 2: Topics */}
        {step === 2 && (
          <div className="w-full animate-enter">
            <h2 className="text-2xl font-bold text-white mb-2">Your Interests</h2>
            <p className="text-white/50 text-sm mb-8">Select at least 3 topics to begin.</p>

            <div className="flex flex-wrap gap-3 justify-center mb-8">
              {topicsList.map(t => (
                <button 
                  key={t}
                  onClick={() => toggleTopic(t)}
                  className={`
                    px-5 py-3 rounded-full text-sm font-medium transition-all duration-200 border
                    ${prefs.topics.includes(t) 
                      ? 'bg-white text-black border-white shadow-[0_0_15px_rgba(255,255,255,0.2)]' 
                      : 'bg-white/5 text-white/70 border-white/5 hover:bg-white/10'}
                  `}
                >
                  {t}
                </button>
              ))}
            </div>

            <button 
              disabled={prefs.topics.length < 3} 
              onClick={next} 
              className="w-full py-4 rounded-full bg-white text-black font-semibold disabled:opacity-50 disabled:cursor-not-allowed hover:bg-white/90 transition-all"
            >
              Continue
            </button>
          </div>
        )}

        {/* Step 3: Density */}
        {step === 3 && (
          <div className="w-full animate-enter">
            <h2 className="text-2xl font-bold text-white mb-2">Depth</h2>
            <p className="text-white/50 text-sm mb-8">How much detail do you need?</p>

            <div className="space-y-3 mb-8">
              {['Ultra quick (10s)', 'Brief summaries', 'Deep dives'].map(style => (
                <button 
                  key={style}
                  onClick={() => { setPrefs(p => ({...p, readingStyle: style.split(' (')[0] as any})); next(); }}
                  className={`
                    w-full p-5 rounded-2xl flex justify-between items-center text-left transition-all border
                    ${prefs.readingStyle === style.split(' (')[0] 
                      ? 'bg-white/10 border-white/30 text-white' 
                      : 'bg-white/5 border-transparent text-white/60 hover:bg-white/10'}
                  `}
                >
                  <span className="font-medium text-base">{style}</span>
                  {prefs.readingStyle === style.split(' (')[0] && <div className="w-2 h-2 rounded-full bg-white shadow-[0_0_8px_white]" />}
                </button>
              ))}
            </div>
          </div>
        )}

        {/* Step 4: Loading */}
        {step === 4 && (
          <div className="flex flex-col items-center justify-center py-10 animate-enter">
             <div className="relative w-16 h-16 mb-6">
                <div className="absolute inset-0 border-4 border-white/20 rounded-full"></div>
                <div className="absolute inset-0 border-4 border-white border-t-transparent rounded-full animate-spin"></div>
             </div>
             <h2 className="text-xl font-semibold text-white">Curating Feed</h2>
             {setTimeout(() => onComplete(prefs), 1500) && null}
          </div>
        )}

      </div>
    </div>
  );
};

export default Onboarding;

