import React, { useState, useRef, MouseEvent } from 'react';
import { Byte } from '../types';

interface NewsSlideProps {
  byte: Byte;
  onLike: (id: string) => void;
  onSave: (id: string) => void;
}

const NewsSlide: React.FC<NewsSlideProps> = ({ byte, onLike, onSave }) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const cardRef = useRef<HTMLDivElement>(null);

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (navigator.share) {
      try {
        await navigator.share({
          title: byte.title,
          text: byte.abstract.substring(0, 100) + '...',
          url: window.location.href,
        });
      } catch (err) {
        console.log('Error sharing:', err);
      }
    } else {
      navigator.clipboard.writeText(window.location.href);
      alert('Link copied!');
    }
  };

  const toggleAudio = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsPlaying(!isPlaying);
    if (!isPlaying) {
      const msg = new SpeechSynthesisUtterance(byte.abstract);
      msg.onend = () => setIsPlaying(false);
      window.speechSynthesis.speak(msg);
    } else {
      window.speechSynthesis.cancel();
    }
  };

  // Pastel Color Map based on Category
  const getCategoryStyles = (cat: string) => {
    const map: Record<string, string> = {
      'Business': 'bg-blue-50 text-blue-600 border-blue-100',
      'Finance': 'bg-emerald-50 text-emerald-600 border-emerald-100',
      'AI & Tech': 'bg-indigo-50 text-indigo-600 border-indigo-100',
      'Science': 'bg-teal-50 text-teal-600 border-teal-100',
      'Culture': 'bg-rose-50 text-rose-600 border-rose-100',
      'World': 'bg-orange-50 text-orange-600 border-orange-100',
    };
    return map[cat] || 'bg-gray-50 text-gray-600 border-gray-100';
  };

  const categoryStyle = getCategoryStyles(byte.category);

  // Subtle 3D Tilt on Hover
  const handleMouseMove = (e: MouseEvent<HTMLDivElement>) => {
    if (!cardRef.current) return;
    const { clientX, clientY } = e;
    const { innerWidth, innerHeight } = window;
    const xPct = (clientX / innerWidth - 0.5) * 2; 
    const yPct = (clientY / innerHeight - 0.5) * 2;
    // Very subtle tilt
    const tiltX = -yPct * 2; 
    const tiltY = xPct * 2; 
    cardRef.current.style.transform = `perspective(1000px) rotateX(${tiltX}deg) rotateY(${tiltY}deg)`;
  };
  const handleMouseLeave = () => {
    if (cardRef.current) {
      cardRef.current.style.transform = `perspective(1000px) rotateX(0) rotateY(0)`;
    }
  };

  return (
    <div 
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      className="snap-slide w-full flex items-center justify-center p-4"
    >
      <div 
        ref={cardRef}
        className="airy-card w-full max-w-[400px] rounded-[2.5rem] overflow-hidden flex flex-col relative h-auto min-h-[620px]"
      >

        {/* Image Section */}
        <div className="relative h-72 w-full p-3">
           <div className="w-full h-full rounded-[2rem] overflow-hidden shadow-inner relative group">
              <img 
                src={byte.fileUrl} 
                alt={byte.title}
                className="w-full h-full object-cover transition-transform duration-700 ease-out group-hover:scale-105"
              />
              <div className="absolute inset-0 ring-1 ring-inset ring-black/5 rounded-[2rem]" />
           </div>

           {/* Floating Badge */}
           <div className={`absolute top-6 left-6 px-4 py-1.5 rounded-full border shadow-sm backdrop-blur-md ${categoryStyle}`}>
              <span className="text-[11px] font-bold uppercase tracking-wider">{byte.category}</span>
           </div>
        </div>

        {/* Content Body */}
        <div className="flex-1 px-8 pb-8 pt-2 flex flex-col">

            {/* Meta */}
            <div className="flex items-center justify-between mb-4">
               <div className="flex items-center gap-2">
                 <div className="w-6 h-6 rounded-full bg-gray-100 overflow-hidden">
                    <div className="w-full h-full flex items-center justify-center bg-gray-200 text-[10px] font-bold text-gray-500">
                        {byte.publisher[0]}
                    </div>
                 </div>
                 <span className="text-xs font-semibold text-gray-500">{byte.publisher}</span>
               </div>
               <span className="text-xs font-medium text-gray-400">{byte.readTime}</span>
            </div>

            {/* Typography */}
            <h2 className="font-display text-2xl font-bold leading-[1.2] text-[#18181B] mb-4 tracking-tight">
              {byte.title}
            </h2>

            <div className="flex-1 overflow-y-auto no-scrollbar mask-fade-bottom">
               <p className="text-[16px] leading-relaxed text-[#52525B] font-normal">
                 {byte.abstract}
               </p>
            </div>

            {/* Minimal Action Bar */}
            <div className="mt-8 pt-6 border-t border-gray-100 flex items-center justify-between">

                {/* Left Actions */}
                <div className="flex gap-3">
                   <button 
                      onClick={(e) => { e.stopPropagation(); onLike(byte.id); }}
                      className={`airy-btn w-12 h-12 rounded-full flex items-center justify-center transition-colors ${byte.isLiked ? 'text-rose-500 bg-rose-50 border-rose-100' : 'text-gray-400 hover:text-gray-900'}`}
                   >
                      <svg className="w-6 h-6" fill={byte.isLiked ? "currentColor" : "none"} stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" /></svg>
                   </button>
                   <button 
                      onClick={handleShare}
                      className="airy-btn w-12 h-12 rounded-full flex items-center justify-center text-gray-400 hover:text-gray-900"
                   >
                      <svg className="w-6 h-6" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" /></svg>
                   </button>
                </div>

                {/* Right Actions */}
                <div className="flex gap-3">
                   <button 
                      onClick={toggleAudio}
                      className={`airy-btn h-12 px-6 rounded-full flex items-center gap-2 transition-all ${isPlaying ? 'bg-indigo-50 text-indigo-600 border-indigo-100' : 'text-gray-500 hover:text-gray-900'}`}
                   >
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
