                </div>

                <div className="space-y-4">
                <h1 className="text-4xl font-bold text-gray-900 tracking-tight">Focus.</h1>
                <p className="text-gray-500 text-lg leading-relaxed font-medium">
                    The noise, filtered. <br/> The signal, amplified.
                </p>
                </div>

                <button 
                onClick={next} 
                className="w-full py-4 rounded-full bg-black text-white font-bold text-sm uppercase tracking-widest hover:scale-105 transition-all shadow-lg"
                >
                Begin
                </button>
            </div>
            )}

            {/* Step 2: Topics */}
            {step === 2 && (
            <div className="w-full animate-enter">
                <h2 className="text-3xl font-bold text-gray-900 mb-2">Sphere</h2>
                <p className="text-gray-400 text-sm font-bold uppercase tracking-widest mb-8">Select 3+ interests</p>

                <div className="flex flex-wrap gap-3 justify-center mb-10">
                {topicsList.map(t => (
                    <button 
                    key={t}
                    onClick={() => toggleTopic(t)}
                    className={`
                        px-5 py-3 rounded-full text-sm font-bold transition-all duration-200 border shadow-sm
                        ${prefs.topics.includes(t) 
                        ? 'bg-black text-white border-black transform -translate-y-1' 
                        : 'bg-white text-gray-600 border-gray-100 hover:border-gray-300'}
                    `}
                    >
                    {t}
