                <button 
                disabled={prefs.topics.length < 3} 
                onClick={next} 
                className="w-full py-4 rounded-full bg-black text-white font-bold text-sm uppercase tracking-widest disabled:opacity-50 disabled:transform-none hover:scale-105 transition-all shadow-lg"
                >
                Continue
                </button>
            </div>
            )}

            {/* Step 3: Density */}
            {step === 3 && (
            <div className="w-full animate-enter">
                <h2 className="text-3xl font-bold text-gray-900 mb-2">Depth</h2>
                <p className="text-gray-400 text-sm font-bold uppercase tracking-widest mb-8">Reading style</p>

