             <circle cx="80" cy="20" r="40" fill="black" />
             <rect x="0" y="50" width="30" height="30" fill="black" />
           </svg>
        </div>

        {/* Image Section - Rectangular with 2D Badge */}
        <div className="relative h-64 w-full p-4">
           <div className="w-full h-full rounded-2xl overflow-hidden relative border border-slate-100">
              <img 
                src={byte.fileUrl} 
                alt={byte.title}
                className="w-full h-full object-cover"
              />
           </div>

           {/* Geometric Badge */}
           <div className="absolute top-8 left-8 bg-black text-white px-3 py-1 text-xs font-bold uppercase tracking-wider rounded-md border border-white">
              {byte.category}
           </div>
        </div>

        {/* Content Body */}
        <div className="flex-1 px-8 pb-8 flex flex-col">

            {/* Meta */}
            <div className="flex items-center justify-between mb-5 border-b border-slate-100 pb-3">
               <div className="flex items-center gap-2">
