import React, { useState } from 'react';
import { UserPreferences } from '../types';

interface OnboardingProps {
  onComplete: (prefs: UserPreferences) => void;
}

const Onboarding: React.FC<OnboardingProps> = ({ onComplete }) => {
  const [step, setStep] = useState(1);
  const [prefs, setPrefs] = useState<UserPreferences>({
    topics: [],
    readingStyle: 'Brief summaries',
    tone: 'Straight facts',
    constraints: {
      noClickbait: true,
      fewerCelebrity: false,
      expertSources: true,
      safeMode: false
    }
  });

  const topicsList = ['AI & Tech', 'Startups', 'Global Markets', 'Policy', 'Geopolitics', 'Climate', 'Culture', 'Science', 'Finance', 'Health'];

  const toggleTopic = (topic: string) => {
    setPrefs(p => ({
      ...p,
      topics: p.topics.includes(topic) ? p.topics.filter(t => t !== topic) : [...p.topics, topic]
    }));
  };

  const next = () => setStep(s => s + 1);

  return (
    <div className="fixed inset-0 z-[100] flex flex-col items-center justify-center p-6 bg-[#0f172a] animate-enter">

      {/* Background Shapes for Context */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none opacity-20">
         <svg width="100%" height="100%">
            <circle cx="10%" cy="10%" r="50" fill="white" />
            <rect x="80%" y="60%" width="100" height="100" fill="white" />
            <path d="M50 50 L100 150 L0 150 Z" fill="white" transform="translate(200, 500)" />
         </svg>
      </div>

      {/* Flat White Card */}
      <div className="relative z-10 bg-white w-full max-w-[480px] p-10 rounded-2xl border-4 border-slate-100 shadow-[8px_8px_0px_rgba(255,255,255,0.1)]">

        {/* Step 1: Intro */}
        {step === 1 && (
        <div className="flex flex-col items-center text-center space-y-8 animate-enter">
            <div className="w-20 h-20 bg-slate-900 flex items-center justify-center text-4xl font-geo font-bold text-white mb-2">
               B
            </div>

            <div className="space-y-4">
            <h1 className="font-geo text-4xl font-bold text-slate-900">Bytes.</h1>
            <p className="text-slate-500 text-lg font-medium">
                News filtered through<br/>geometric precision.
            </p>
            </div>

            <button 
            onClick={next} 
            className="w-full py-4 bg-slate-900 text-white font-bold text-sm uppercase tracking-widest hover:bg-slate-800 transition-all border-2 border-transparent"
            >
            Start Reading
            </button>
        </div>
        )}

        {/* Step 2: Topics */}
        {step === 2 && (
        <div className="w-full animate-enter">
            <h2 className="font-geo text-3xl font-bold text-slate-900 mb-2">Inputs</h2>
            <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mb-8">Select 3+ Variables</p>

            <div className="flex flex-wrap gap-3 justify-center mb-10">
            {topicsList.map(t => (
                <button 
                key={t}
                onClick={() => toggleTopic(t)}
                className={`
                    px-4 py-3 rounded-sm text-sm font-bold transition-all border-2
                    ${prefs.topics.includes(t) 
                    ? 'bg-slate-900 text-white border-slate-900' 
                    : 'bg-white text-slate-600 border-slate-200 hover:border-slate-400'}
                `}
                >
                {t}
                </button>
            ))}
            </div>

            <button 
            disabled={prefs.topics.length < 3} 
            onClick={next} 
            className="w-full py-4 bg-slate-900 text-white font-bold text-sm uppercase tracking-widest disabled:opacity-50 disabled:cursor-not-allowed hover:bg-slate-800 transition-all"
            >
            Next Step
            </button>
        </div>
        )}

        {/* Step 3: Density */}
        {step === 3 && (
        <div className="w-full animate-enter">
            <h2 className="font-geo text-3xl font-bold text-slate-900 mb-2">Resolution</h2>
            <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mb-8">Data Density</p>

            <div className="space-y-4 mb-10">
            {['Ultra quick (10s)', 'Brief summaries', 'Deep dives'].map(style => (
                <button 
                key={style}
                onClick={() => { setPrefs(p => ({...p, readingStyle: style.split(' (')[0] as any})); next(); }}
                className={`
                    w-full p-5 flex justify-between items-center text-left transition-all border-2 rounded-lg
                    ${prefs.readingStyle === style.split(' (')[0] 
                    ? 'bg-slate-50 border-slate-900 text-slate-900' 
                    : 'bg-white border-slate-200 text-slate-500 hover:border-slate-400'}
                `}
                >
                <span className="font-bold text-base">{style}</span>
                {prefs.readingStyle === style.split(' (')[0] && <div className="w-3 h-3 bg-slate-900 rounded-sm" />}
                </button>
            ))}
            </div>
        </div>
        )}

        {/* Step 4: Loading */}
        {step === 4 && (
        <div className="flex flex-col items-center justify-center py-10 animate-enter">
            <div className="relative w-16 h-16 mb-8">
                <div className="absolute inset-0 border-4 border-slate-200 rounded-full"></div>
                <div className="absolute inset-0 border-4 border-slate-900 border-t-transparent rounded-full animate-spin"></div>
            </div>
            <h2 className="font-geo text-xl font-bold text-slate-900">Processing</h2>
            <p className="text-xs font-mono text-slate-400 mt-2">BUILDING FEED...</p>
            {setTimeout(() => onComplete(prefs), 1500) && null}
        </div>
        )}

      </div>
    </div>
  );
};

export default Onboarding;

import React from 'react';

const InteractiveBackground: React.FC = () => {
  // Generate random shapes
  const shapes = Array.from({ length: 15 }).map((_, i) => ({
    id: i,
    type: ['circle', 'rect', 'triangle', 'donut'][Math.floor(Math.random() * 4)],
    left: `${Math.random() * 100}%`,
    top: `${Math.random() * 100}%`,
    size: Math.random() * 150 + 50,
    duration: Math.random() * 20 + 20,
    delay: Math.random() * -20,
    opacity: Math.random() * 0.05 + 0.02, // Low opacity for subtle background
    rotation: Math.random() * 360,
  }));

  return (
    <div className="fixed inset-0 z-0 overflow-hidden bg-[#0f172a] pointer-events-none">
      {/* SVG Container for crisp shapes */}
      <svg className="absolute inset-0 w-full h-full">
        <defs>
          <pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse">
            <circle cx="2" cy="2" r="1" fill="rgba(255,255,255,0.05)" />
          </pattern>
        </defs>

        {/* Subtle Grid Background */}
        <rect width="100%" height="100%" fill="url(#grid)" />

        {shapes.map((shape) => {
          const style: React.CSSProperties = {
            transformBox: 'fill-box',
            transformOrigin: 'center',
            animation: `float-shape ${shape.duration}s infinite linear alternate, rotate-shape ${shape.duration * 1.5}s infinite linear`,
            animationDelay: `${shape.delay}s`,
            opacity: shape.opacity,
            fill: 'white',
          };

          // Render different SVG shapes
          if (shape.type === 'circle') {
            return (
              <circle
                key={shape.id}
                cx={shape.left}
                cy={shape.top}
                r={shape.size / 2}
                style={style}
              />
            );
          }
          if (shape.type === 'rect') {
            return (
              <rect
                key={shape.id}
                x={shape.left}
                y={shape.top}
                width={shape.size}
                height={shape.size}
                rx="10"
                style={style}
              />
            );
          }
          if (shape.type === 'donut') {
            return (
               <circle
                key={shape.id}
                cx={shape.left}
                cy={shape.top}
                r={shape.size / 2}
                stroke="white"
                strokeWidth={shape.size / 4}
                fill="none"
                style={style}
              />
            );
          }
           if (shape.type === 'triangle') {
            const s = shape.size;
            // Simple triangle path
            return (
              <path
                key={shape.id}
                d={`M${shape.left} ${shape.top} l${s/2} ${s} l-${s} 0 z`} // Simplified positioning logic for demo
                transform={`translate(-${s/2}, -${s/2})`} // Centering fix roughly
                style={style}
              />
            );
          }
          return null;
        })}
      </svg>

      <style>{`
        @keyframes float-shape {
          0% { transform: translate(0, 0) rotate(0deg); }
          100% { transform: translate(50px, -50px) rotate(10deg); }
        }
        @keyframes rotate-shape {
          0% { transform: rotate(0deg); }
          100% { transform: rotate(360deg); }
        }
      `}</style>
    </div>
  );
};

export default InteractiveBackground;

