      {/* 1. Cinematic Noise Layer */}
      <div className="film-grain"></div>

      {/* 2. Deep Atmosphere Gradients */}
      <div className="absolute top-[-20%] left-[-10%] w-[50%] h-[50%] bg-blue-900/20 blur-[120px] rounded-full animate-pulse" style={{animationDuration: '8s'}}></div>
      <div className="absolute bottom-[-10%] right-[-10%] w-[60%] h-[60%] bg-indigo-900/10 blur-[120px] rounded-full animate-pulse" style={{animationDuration: '10s', animationDelay: '1s'}}></div>

      {/* 3. Vector Shapes */}
      <svg className="absolute inset-0 w-full h-full opacity-60 mix-blend-screen">
        <defs>
          <filter id="glow">
             <feGaussianBlur stdDeviation="2.5" result="coloredBlur"/>
             <feMerge>
                 <feMergeNode in="coloredBlur"/>
                 <feMergeNode in="SourceGraphic"/>
             </feMerge>
          </filter>
        </defs>

        {shapes.map((shape) => {
          const style: React.CSSProperties = {
            transformBox: 'fill-box',
            transformOrigin: 'center',
            animation: `float-slow ${shape.duration}s infinite linear alternate, rotate-slow ${shape.duration * 1.5}s infinite linear`,
            animationDelay: `${shape.delay}s`,
            opacity: shape.opacity,
          };

          if (shape.type === 'circle') {
            return (
              <circle
                key={shape.id}
                cx={shape.left}
                cy={shape.top}
                r={shape.size / 3}
                fill="none"
                stroke={shape.color}
                strokeWidth="1.5"
                style={style}
              />
            );
          }
          if (shape.type === 'triangle') {
             const s = shape.size / 2;
             return (
              <path 
                key={shape.id}
                d={`M0,${s} L${s},0 L${s*2},${s} Z`}
                transform={`translate(${parseFloat(shape.left) * 10}, ${parseFloat(shape.top) * 10})`} // Rough positioning fix for demo
                fill="none"
                stroke={shape.color}
                strokeWidth="1"
                style={style}
              />
             );
          }
          if (shape.type === 'cross') {
             const s = 20;
             return (
               <g key={shape.id} style={style} transform={`translate(${parseFloat(shape.left) * 10}, ${parseFloat(shape.top) * 10})`}>
                  <rect x={shape.left} y={shape.top} width={s} height="2" fill={shape.color} />
                  <rect x={parseFloat(shape.left) + s/2 - 1} y={parseFloat(shape.top) - s/2 + 1} width="2" height={s} fill={shape.color} />
               </g>
             );
          }
          // Default Line
          return (
            <line
                key={shape.id}
                x1={shape.left}
                y1={shape.top}
                x2={`calc(${shape.left} + 100px)`}
                y2={`calc(${shape.top} + 100px)`}
                stroke={shape.color}
                strokeWidth="1"
                strokeDasharray="5,5"
                style={style}
            />
          );
        })}
      </svg>

      <style>{`
        @keyframes float-slow {
          0% { transform: translate(0, 0) rotate(0deg); }
          100% { transform: translate(40px, -60px) rotate(5deg); }
        }
        @keyframes rotate-slow {
          from { transform: rotate(0deg); }
          to { transform: rotate(360deg); }
        }
      `}</style>
    </div>
  );
};

export default InteractiveBackground;

import React, { useState, MouseEvent } from 'react';
import { Byte } from '../types';

interface NewsSlideProps {
  byte: Byte;
  onLike: (id: string) => void;
  onSave: (id: string) => void;
}

const NewsSlide: React.FC<NewsSlideProps> = ({ byte, onLike, onSave }) => {
  const [isPlaying, setIsPlaying] = useState(false);

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (navigator.share) {
      try {
        await navigator.share({
          title: byte.title,
          text: byte.abstract.substring(0, 100) + '...',
          url: window.location.href,
        });
      } catch (err) {
        console.log('Error sharing:', err);
      }
    } else {
      navigator.clipboard.writeText(window.location.href);
      alert('Link copied!');
    }
  };

  const toggleAudio = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsPlaying(!isPlaying);
    if (!isPlaying) {
      const msg = new SpeechSynthesisUtterance(byte.abstract);
      msg.onend = () => setIsPlaying(false);
      window.speechSynthesis.speak(msg);
    } else {
      window.speechSynthesis.cancel();
    }
  };

  return (
    <div className="snap-slide w-full flex items-center justify-center p-4">
      {/* Prism Card */}
      <div 
        className="prism-card w-full max-w-[420px] h-auto min-h-[640px] flex flex-col group"
