      {/* 2. Floating 3D Elements */}
      {elements.map((el) => {
        // Dynamic CSS variables for size and color
        const style = {
          '--s': `${el.size}px`,
          '--c': el.color,
          left: el.left,
          top: el.top,
          animationDuration: `${el.duration}s`,
          animationDelay: `${el.delay}s`,
        } as React.CSSProperties;

        if (el.type === 'symbol') {
          return (
            <div 
              key={el.id} 
