const InteractiveBackground: React.FC = () => {
  // Generate random 3D shapes and Information Symbols
  const elements = Array.from({ length: 18 }).map((_, i) => ({
    id: i,
    // Mix of 3D cubes and Text Symbols
    type: i % 2 === 0 ? 'cube' : 'symbol',
