        {step === 1 && (
        <div className="flex flex-col items-center space-y-8 w-full">
            <div className="w-16 h-16 bg-[#FF3B00] flex items-center justify-center text-3xl font-serif font-bold text-white mb-4">
               B
            </div>

            <div className="space-y-6">
            <h1 className="font-display text-6xl font-normal text-black tracking-tight leading-none">
                Future <br/><span className="italic text-[#FF3B00]">Editorial</span>
            </h1>
            <p className="text-gray-500 text-lg font-light leading-relaxed max-w-sm mx-auto">
                Decoded intelligence for the modern visionary. Fast, clear, essential.
            </p>
            </div>

            <button 
            onClick={next} 
            className="group relative inline-flex items-center justify-center px-8 py-4 mt-8 bg-black text-white font-sans font-bold text-xs uppercase tracking-[0.2em] overflow-hidden transition-all hover:bg-[#FF3B00]"
            >
              <span className="relative z-10">Get Started</span>
            </button>
        </div>
        )}

        {/* Step 2: Topics */}
        {step === 2 && (
        <div className="w-full">
            <h2 className="font-display text-4xl text-black mb-3">Your Portfolio</h2>
            <p className="text-[#FF3B00] text-xs font-bold uppercase tracking-widest mb-10">Select Interest Vectors</p>

            <div className="flex flex-wrap gap-3 justify-center mb-12">
            {topicsList.map(t => (
                <button 
                key={t}
                onClick={() => toggleTopic(t)}
                className={`
                    px-5 py-3 text-sm font-medium transition-all border
                    ${prefs.topics.includes(t) 
                    ? 'bg-black text-white border-black' 
                    : 'bg-white text-gray-500 border-gray-200 hover:border-black hover:text-black'}
                `}
                >
                {t}
                </button>
            ))}
            </div>

            <button 
            disabled={prefs.topics.length < 3} 
            onClick={next} 
            className="w-full py-5 bg-black text-white font-bold text-xs uppercase tracking-[0.2em] disabled:opacity-30 disabled:cursor-not-allowed hover:bg-[#FF3B00] transition-colors"
            >
            Confirm Selection
            </button>
        </div>
        )}

        {/* Step 3: Density */}
        {step === 3 && (
        <div className="w-full">
            <h2 className="font-display text-4xl text-black mb-3">Depth of Field</h2>
            <p className="text-[#FF3B00] text-xs font-bold uppercase tracking-widest mb-10">Set Content Density</p>

            <div className="space-y-4 mb-12">
            {['Ultra quick (10s)', 'Brief summaries', 'Deep dives'].map(style => (
                <button 
                key={style}
                onClick={() => { setPrefs(p => ({...p, readingStyle: style.split(' (')[0] as any})); next(); }}
                className={`
                    w-full p-6 flex justify-between items-center text-left transition-all border
                    ${prefs.readingStyle === style.split(' (')[0] 
                    ? 'border-black bg-gray-50' 
                    : 'bg-white border-gray-200 hover:border-gray-400'}
                `}
                >
                <span className={`font-serif text-xl ${prefs.readingStyle === style.split(' (')[0] ? 'text-black font-bold' : 'text-gray-500'}`}>
                    {style}
                </span>
                {prefs.readingStyle === style.split(' (')[0] && <div className="w-2 h-2 bg-[#FF3B00]" />}
                </button>
            ))}
            </div>
        </div>
        )}

        {/* Step 4: Loading */}
        {step === 4 && (
        <div className="flex flex-col items-center justify-center py-16">
            <div className="relative w-16 h-16 mb-8">
                <div className="absolute inset-0 border-2 border-gray-100 rounded-full"></div>
                <div className="absolute inset-0 border-2 border-[#FF3B00] border-t-transparent rounded-full animate-spin"></div>
            </div>
            <h2 className="font-display text-2xl text-black">Synthesizing Feed</h2>
            <p className="text-xs font-mono text-gray-400 mt-3 tracking-widest uppercase">Initializing Bytes Protocol...</p>
            {setTimeout(() => onComplete(prefs), 2000) && null}
        </div>
        )}

      </div>
    </div>
  );
};

