import React, { useState, MouseEvent } from 'react';
import { Byte } from '../types';

interface NewsSlideProps {
  byte: Byte;
  onLike: (id: string) => void;
  onSave: (id: string) => void;
}

const NewsSlide: React.FC<NewsSlideProps> = ({ byte, onLike, onSave }) => {
  const [isPlaying, setIsPlaying] = useState(false);

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (navigator.share) {
      try {
        await navigator.share({
          title: byte.title,
          text: byte.abstract.substring(0, 100) + '...',
          url: window.location.href,
        });
      } catch (err) {
        console.log('Error sharing:', err);
      }
    } else {
      navigator.clipboard.writeText(window.location.href);
      alert('Link copied!');
    }
  };

  const toggleAudio = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsPlaying(!isPlaying);
    if (!isPlaying) {
      const msg = new SpeechSynthesisUtterance(byte.abstract);
      msg.onend = () => setIsPlaying(false);
      window.speechSynthesis.speak(msg);
    } else {
      window.speechSynthesis.cancel();
    }
  };

  return (
    <div className="snap-slide w-full flex items-center justify-center p-4">
      {/* Prism Card - Editorial Vision Style */}
      <div 
        className="prism-card w-full max-w-[450px] h-auto min-h-[680px] flex flex-col group bg-white"
      >

        {/* Top Meta Bar */}
        <div className="flex justify-between items-center p-6 border-b border-gray-100 bg-white">
           <div className="flex items-center gap-2">
             <div className="w-2 h-2 bg-[#FF3B00]"></div>
             <span className="text-[10px] font-bold uppercase tracking-[0.2em] text-black">{byte.category}</span>
           </div>
           <span className="font-serif text-xs italic text-gray-400">#{byte.id.split('-')[1]}</span>
        </div>

        {/* Image Section - Strict Aspect Ratio */}
        <div className="relative h-64 w-full overflow-hidden border-b border-gray-100">
           <img 
             src={byte.fileUrl} 
             alt={byte.title}
             className="w-full h-full object-cover transition-transform duration-1000 ease-out group-hover:scale-105"
           />
           {/* Publisher Tag overlapping image */}
           <div className="absolute bottom-0 left-0 bg-black text-white px-4 py-2">
             <span className="text-[10px] font-bold uppercase tracking-widest">{byte.publisher}</span>
           </div>
        </div>

        {/* Content Body */}
        <div className="flex-1 px-8 py-8 flex flex-col bg-white relative">

            <div className="mb-4 text-xs font-mono text-gray-400 flex items-center gap-2">
               <span>{byte.publicationDate}</span>
               <span className="text-[#FF3B00]">•</span>
               <span>{byte.readTime}</span>
            </div>

            {/* Typography - Playfair Display */}
            <h2 className="font-display text-4xl leading-[1.1] text-black mb-6">
              {byte.title}
            </h2>

            <div className="w-12 h-1 bg-gray-100 mb-6"></div>

            {/* Abstract */}
            <div className="flex-1 overflow-y-auto no-scrollbar mask-fade-bottom">
               <p className="text-[17px] leading-relaxed text-gray-600 font-sans font-light">
                 {byte.abstract}
               </p>
            </div>

            {/* Action Bar - Clean & Sharp */}
            <div className="mt-8 pt-6 border-t border-gray-100 flex items-center justify-between">

                {/* Like / Share */}
                <div className="flex gap-4">
                   <button 
                      onClick={(e) => { e.stopPropagation(); onLike(byte.id); }}
                      className={`flex items-center gap-2 transition-colors ${byte.isLiked ? 'text-[#FF3B00]' : 'text-gray-400 hover:text-black'}`}
                   >
                      <svg className="w-5 h-5" fill={byte.isLiked ? "currentColor" : "none"} stroke="currentColor" strokeWidth="1.5" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" /></svg>
                      {byte.isLiked && <span className="text-xs font-bold">{byte.likes}</span>}
                   </button>
                   <button 
                      onClick={handleShare}
                      className="text-gray-400 hover:text-black transition-colors"
                   >
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="1.5" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" /></svg>
                   </button>
                </div>

                {/* Play / Save */}
                <div className="flex gap-3">
                   <button 
                      onClick={toggleAudio}
                      className={`h-10 px-6 border transition-all font-bold text-[10px] uppercase tracking-widest flex items-center gap-2
                      ${isPlaying 
                        ? 'bg-black text-white border-black' 
                        : 'bg-white text-black border-gray-200 hover:border-black'}`}
                   >
                      {isPlaying ? (
                        <>
                          <span className="w-1.5 h-1.5 bg-[#FF3B00] rounded-full animate-pulse"/>
                          <span>Stop</span>
                        </>
                      ) : (
                        <span>Listen</span>
                      )}
                   </button>
                   <button 
                      onClick={(e) => { e.stopPropagation(); onSave(byte.id); }}
                      className={`w-10 h-10 flex items-center justify-center border transition-all ${byte.isSaved ? 'bg-[#FF3B00] border-[#FF3B00] text-white' : 'bg-white border-gray-200 text-gray-400 hover:text-black hover:border-black'}`}
                   >
                      <svg className="w-5 h-5" fill={byte.isSaved ? "currentColor" : "none"} stroke="currentColor" strokeWidth="1.5" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" /></svg>
                   </button>
                </div>

            </div>

        </div>
      </div>
    </div>
  );
};

