import Onboarding from './components/Onboarding';
import { PAPERS } from './constants';
import { fetchRealTimeNews } from './services/geminiService';
import { Byte, UserPreferences } from './types';

const App: React.FC = () => {
  const [news, setNews] = useState<Byte[]>([]);
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [showOnboarding, setShowOnboarding] = useState<boolean>(true);
  const [selectedTopics, setSelectedTopics] = useState<string[]>(['US News', 'World', 'AI & Tech', 'Business', 'Science', 'Finance', 'Culture']);
  const [searchTerm, setSearchTerm] = useState('');
  const [isLiveLoading, setIsLiveLoading] = useState(false);
  const feedRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // 1. Load preferences
    const hasSeenOnboarding = localStorage.getItem('bytes_onboarded') === 'true';
    if (hasSeenOnboarding) {
      setShowOnboarding(false);
    }
    const storedPrefs = localStorage.getItem('bytes_prefs');
    if (storedPrefs) {
      const prefs = JSON.parse(storedPrefs) as UserPreferences;
      if (prefs.topics && prefs.topics.length > 0) {
        setSelectedTopics(prefs.topics);
      }
    }

    // 2. Initialize with static data for instant paint
    setNews(PAPERS.map(p => ({ ...p, isLiked: false, isSaved: false })));

    // 3. Automatically fetch REAL-TIME news
    // This ensures "news of all subjects is real time" on load.
    const initRealTimeNews = async () => {
      if (process.env.API_KEY) {
         setIsLiveLoading(true);
         // Query a broad mix to ensure "all subjects" coverage
         const broadTopics = ['Latest Global News', 'Technology', 'Business', 'Science', 'World Events'];
         const liveBytes = await fetchRealTimeNews(broadTopics);
         if (liveBytes.length > 0) {
           setNews(liveBytes);
         }
         setIsLiveLoading(false);
      }
    };

    // Trigger the fetch after a brief delay to allow UI to settle
    setTimeout(initRealTimeNews, 100);

  }, []);

  const handleOnboardingComplete = (prefs: UserPreferences) => {
    setShowOnboarding(false);
    setSelectedTopics(prefs.topics);
    localStorage.setItem('bytes_onboarded', 'true');
    localStorage.setItem('bytes_prefs', JSON.stringify(prefs));
    // Trigger fetch based on new prefs
    handleLiveUpdate(prefs.topics);
  };

  const handleLiveUpdate = async (overrideTopics?: string[]) => {
    setIsLiveLoading(true);
    // Use override topics if provided (e.g. from onboarding), else use selected or default broad mix
    const currentTopics = overrideTopics || selectedTopics;

    // If specific topics selected, use them. If none or too many, use a broad curated list.
    const queryTopics = currentTopics.length > 0 && currentTopics.length < 6 
        ? currentTopics 
        : ['Global News', 'Technology', 'Business', 'Science', 'Culture', 'Politics'];

    const liveBytes = await fetchRealTimeNews(queryTopics);

    if (liveBytes.length > 0) {
      setNews(liveBytes);
      if (feedRef.current) {
        feedRef.current.scrollTo({ top: 0, behavior: 'smooth' });
      }
    } else {
        // Silent fail or keep existing news if live fetch fails (e.g. rate limit)
        console.log("Could not fetch live news, keeping existing.");
    }
    setIsLiveLoading(false);
  };

  const handleLike = (id: string) => {
    setNews(prev => prev.map(item => 
      item.id === id ? { ...item, isLiked: !item.isLiked, likes: item.isLiked ? item.likes - 1 : item.likes + 1 } : item
    ));
  };

  const handleSave = (id: string) => {
    setNews(prev => prev.map(item => 
      item.id === id ? { ...item, isSaved: !item.isSaved } : item
    ));
  };

  const toggleTopic = (topic: string) => {
    setSelectedTopics(prev => 
      prev.includes(topic) ? prev.filter(t => t !== topic) : [...prev, topic]
    );
