/**
 * Fetches real-time news using Google Search Grounding.
 * Note: schema extraction is manual because googleSearch tool doesn't support responseSchema in the same request effectively for this specific payload structure in 2.5 flash.
 */
export const fetchRealTimeNews = async (topics: string[]): Promise<Byte[]> => {
  if (!process.env.API_KEY) {
    console.warn("No API Key found for live news");
    return [];
  }

  const topicString = topics.length > 0 ? topics.join(', ') : 'International Breaking News';

  // Prompt engineered for global coverage
  const prompt = `
    Find 10 of the absolute latest, most important breaking news stories right now regarding: ${topicString}.

    CRITICAL INSTRUCTION: Ensure the stories are DIVERSE and represent multiple countries/continents (e.g., Asia, Europe, Africa, South America, Middle East), not just the US or UK.

    Return a strictly valid JSON array of objects. Do not include markdown formatting (like \`\`\`json).
    Each object must have:
    - "title": A catchy, short headline (under 10 words).
    - "publisher": The source name (e.g., BBC, Al Jazeera, Reuters, NHK).
    - "abstract": A concise, engaging summary (approx 30-40 words).
    - "category": One word category (e.g., World, Politics, Biz, Tech).
    - "readTime": Estimated read time (e.g. "2 min read").
    - "sourceUrl": The URL of the source.

    Ensure the JSON is valid.
  `;

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
      },
    });

    let text = response.text || "";
    // Clean markdown if present
    text = text.replace(/```json/g, '').replace(/```/g, '').trim();

    const rawData = JSON.parse(text);

    if (!Array.isArray(rawData)) return [];

    // Map to Byte structure
    return rawData.map((item: any, index: number) => {
      // If grounding chunks exist, we might try to map real URLs, but the prompt asks for sourceUrl in JSON.
      // We will generate a consistent ID based on time.
      return {
        id: `live-${Date.now()}-${index}`,
        title: item.title || "Breaking News",
        publisher: item.publisher || "Global Wire",
        authors: ["AI Curator"],
        abstract: item.abstract || "No summary available.",
        category: item.category || "World",
        readTime: item.readTime || "1 min read",
