  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        // We do not set maxOutputTokens here to let the model use its default maximum (usually 8k for Flash).
      },
    });

    let text = response.text || "";
    // Clean markdown if present
    text = text.replace(/```json/g, '').replace(/```/g, '').trim();

    // Attempt to repair truncated JSON
    if (text.startsWith('[') && !text.endsWith(']')) {
       const lastClosingBrace = text.lastIndexOf('}');
       if (lastClosingBrace !== -1) {
          text = text.substring(0, lastClosingBrace + 1) + ']';
       }
    }

    const rawData = JSON.parse(text);

    if (!Array.isArray(rawData)) return [];

    // Map to Byte structure
    return rawData.map((item: any, index: number) => {
      const cat = item.category || "World";
      return {
        id: `live-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`, // Unique ID for aggressive merging
        title: item.title || "Breaking News",
        publisher: item.publisher || "Global Wire",
        authors: ["AI Curator"],
        abstract: item.abstract || "No summary available.",
        category: cat,
        readTime: "1 min read",
        fileUrl: getCategoryImageUrl(cat),
        likes: Math.floor(Math.random() * 500),
        comments: Math.floor(Math.random() * 50),
        isLiked: false,
        isSaved: false,
        publicationDate: "LIVE",
        sourceUrl: item.sourceUrl
      } as Byte;
    });

  } catch (e) {
    console.error("Failed to fetch live news for topics:", topics, e);
    return [];
  }
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import Navbar from './components/Navbar';
import NewsSlide from './components/NewsSlide';
import CurateDrawer from './components/CurateDrawer';
import Onboarding from './components/Onboarding';
import { PAPERS } from './constants';
import { fetchRealTimeNews } from './services/geminiService';
import { Byte, UserPreferences } from './types';

const App: React.FC = () => {
  const [news, setNews] = useState<Byte[]>([]);
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [showOnboarding, setShowOnboarding] = useState<boolean>(true);
  const [selectedTopics, setSelectedTopics] = useState<string[]>(['US News', 'World', 'AI & Tech', 'Business', 'Science', 'Finance', 'Culture']);
  const [searchTerm, setSearchTerm] = useState('');
  const [isLiveLoading, setIsLiveLoading] = useState(false);
  const feedRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // 1. Load preferences
    const hasSeenOnboarding = localStorage.getItem('bytes_onboarded') === 'true';
    if (hasSeenOnboarding) {
      setShowOnboarding(false);
    }
    const storedPrefs = localStorage.getItem('bytes_prefs');
    if (storedPrefs) {
      const prefs = JSON.parse(storedPrefs) as UserPreferences;
      if (prefs.topics && prefs.topics.length > 0) {
        setSelectedTopics(prefs.topics);
      }
    }

    // 2. Initialize with static data for instant paint
    setNews(PAPERS.map(p => ({ ...p, isLiked: false, isSaved: false })));

    // 3. Automatically fetch REAL-TIME news
    // Use the massive parallel fetch strategy
    setTimeout(() => handleLiveUpdate(), 100);

  }, []);

  const handleOnboardingComplete = (prefs: UserPreferences) => {
    setShowOnboarding(false);
    setSelectedTopics(prefs.topics);
    localStorage.setItem('bytes_onboarded', 'true');
    localStorage.setItem('bytes_prefs', JSON.stringify(prefs));
    handleLiveUpdate(prefs.topics);
  };

  /**
   * Massive Parallel Fetch to maximize news count.
   * We break the request into distinct regional and thematic channels to bypass single-response token limits.
   */
  const handleLiveUpdate = async (overrideTopics?: string[]) => {
    if (!process.env.API_KEY) return;

    setIsLiveLoading(true);

    // If specific topics are selected by user, prioritize them but also include global mix
    // If we want "2000 news for all topics", we need a very broad net.

    const CHANNELS = [
      'Breaking News USA',
      'Breaking News Europe',
      'Breaking News Asia',
      'Breaking News Middle East',
      'Breaking News Africa',
      'Breaking News South America',
      'Global Technology & AI',
      'Global Financial Markets',
      'Scientific Breakthroughs',
      'Global Entertainment & Culture',
      'International Sports',
      'Cryptocurrency & Web3'
    ];

    try {
      // Launch all requests in parallel
      // Note: This creates ~12 concurrent API calls. 
      const promises = CHANNELS.map(channel => fetchRealTimeNews([channel]));

      const results = await Promise.all(promises);

      // Flatten and Shuffle the results for a dynamic feed feel
      const allLiveNews = results.flat().sort(() => Math.random() - 0.5);

      if (allLiveNews.length > 0) {
        // We replace the feed with this massive intake
        setNews(allLiveNews);
        if (feedRef.current) {
          feedRef.current.scrollTo({ top: 0, behavior: 'smooth' });
        }
      } else {
        console.log("No live news fetched.");
      }
    } catch (err) {
      console.error("Error in massive fetch:", err);
    } finally {
      setIsLiveLoading(false);
    }
  };

  const handleLike = (id: string) => {
    setNews(prev => prev.map(item => 
      item.id === id ? { ...item, isLiked: !item.isLiked, likes: item.isLiked ? item.likes - 1 : item.likes + 1 } : item
    ));
  };

  const handleSave = (id: string) => {
    setNews(prev => prev.map(item => 
      item.id === id ? { ...item, isSaved: !item.isSaved } : item
    ));
  };

  const toggleTopic = (topic: string) => {
    setSelectedTopics(prev => 
      prev.includes(topic) ? prev.filter(t => t !== topic) : [...prev, topic]
    );
  };

  const filteredNews = useMemo(() => {
    return news.filter(byte => {
      // Always show live fetched items as they are most relevant
      if (byte.id.startsWith('live-')) return true;

      const matchesTopic = selectedTopics.includes(byte.category) || selectedTopics.length === 0;
      const matchesSearch = searchTerm === '' || 
        byte.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
        byte.abstract.toLowerCase().includes(searchTerm.toLowerCase());
      return matchesTopic && matchesSearch;
    });
  }, [news, selectedTopics, searchTerm]);

  return (
    <div className="relative h-screen w-screen overflow-hidden bg-black">

      {showOnboarding ? (
        <Onboarding onComplete={handleOnboardingComplete} />
      ) : (
        <>
          {/* Main Feed */}
          <div 
            className={`
              relative z-10 w-full h-full transition-all duration-500 ease-[cubic-bezier(0.32,0.72,0,1)]
              ${isDrawerOpen ? 'scale-90 opacity-80 blur-[1px]' : 'scale-100 opacity-100'}
            `}
            style={{ transformOrigin: 'center bottom' }}
          >
            <Navbar 
                onProfileClick={() => setIsDrawerOpen(true)}
                onSearchClick={() => setIsDrawerOpen(true)}
                onNotifyClick={() => {}}
                onLiveClick={() => handleLiveUpdate()}
                isLiveLoading={isLiveLoading}
            />

            <div 
                ref={feedRef}
                className="feed-container"
            >
                {filteredNews.length > 0 ? (
                filteredNews.map((byte, index) => (
                    <NewsSlide 
                      key={`${byte.id}-${index}`} 
                      byte={byte} 
                      onLike={handleLike} 
                      onSave={handleSave} 
                    />
                ))
                ) : (
                <div className="h-full w-full flex flex-col items-center justify-center text-center p-8 bg-white">
                    <h3 className="text-3xl font-serif-display font-bold text-black mb-2">No stories found.</h3>
                    <p className="text-sm text-gray-500 mb-8">Try adjusting your filters.</p>
                    <button 
                      onClick={() => setIsDrawerOpen(true)}
                      className="px-8 py-4 rounded-full bg-black text-white font-bold text-xs uppercase tracking-widest"
                    >
                      Open Settings
                    </button>
                </div>
                )}
            </div>
          </div>

          <CurateDrawer 
            isOpen={isDrawerOpen} 
            onClose={() => setIsDrawerOpen(false)}
            selectedTopics={selectedTopics}
            onTopicToggle={toggleTopic}
            onSearch={setSearchTerm}
          />
        </>
      )}
    </div>
  );
};

export default App;

