import { GoogleGenAI } from "@google/genai";
import { PAPERS } from '../constants';
import { Byte } from '../types';

const getSystemInstruction = () => {
  const paperContext = PAPERS.map(p => 
    `- "${p.title}" (${p.publicationDate}). Section: ${p.category}. Lead: ${p.abstract}`
  ).join('\n');

  return `You are the Social Impact Editor for "The Philanthropy Times". 
  Your tone is empathetic, knowledgeable, and solutions-oriented.

  Here is our current content wire:
  ${paperContext}

  Answer user questions about these stories, global development trends, impact investing, or charitable strategies.`;
};

// Helper to get an image based on category
const getCategoryImageUrl = (category: string): string => {
  const map: Record<string, string> = {
    'Business': 'photo-1611974765270-ca12586343bb',
    'Tech': 'photo-1518770660439-4636190af475',
    'Science': 'photo-1507413245164-6160d8298b31',
    'World': 'photo-1521737604893-d14cc237f11d',
    'Finance': 'photo-1611974765270-ca12586343bb',
    'Health': 'photo-1576091160399-112ba8d25d1d',
    'Culture': 'photo-1499750310107-5fef28a66643',
    'Politics': 'photo-1529101091760-61df6be5d187',
  };
  const key = Object.keys(map).find(k => category.includes(k)) || 'World';
  const imgId = map[key] || 'photo-1504711434969-e33886168f5c'; // default newsy bg
  return `https://images.unsplash.com/${imgId}?auto=format&fit=crop&q=80&w=1200`;
};

export const sendMessageToGemini = async (history: {role: string, text: string}[], newMessage: string): Promise<string> => {
  try {
    if (!process.env.API_KEY) return "Missing API Key.";

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: [
        ...history.map(h => ({
          role: h.role === 'model' ? 'model' : 'user',
          parts: [{ text: h.text }]
        })),
        { role: 'user', parts: [{ text: newMessage }] }
      ],
      config: {
        systemInstruction: getSystemInstruction(),
      }
    });

    return response.text || "No response.";

  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Service unavailable.";
  }
};

/**
 * Fetches real-time news using Google Search Grounding.
 */
export const fetchRealTimeNews = async (topics: string[]): Promise<Byte[]> => {
  if (!process.env.API_KEY) {
    console.warn("No API Key found for live news");
    return [];
  }

  const topicString = topics.length > 0 ? topics.join(', ') : 'Global Breaking News';

  // Prompt optimized for maximum quantity
  const prompt = `
    Find trending news stories about: ${topicString}.
    Return a JSON array of objects.
    Fields:
    - "title": Headline (<10 words).
    - "publisher": Source name.
    - "abstract": Summary (20-30 words).
    - "category": Topic (e.g. World, Tech).
    - "sourceUrl": Link.

    Output strictly a JSON array.
  `;

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
      },
    });

    let text = response.text || "";
    // Clean markdown if present
    text = text.replace(/```json/g, '').replace(/```/g, '').trim();

    // Attempt to repair truncated JSON
    if (text.startsWith('[') && !text.endsWith(']')) {
       const lastClosingBrace = text.lastIndexOf('}');
       if (lastClosingBrace !== -1) {
          text = text.substring(0, lastClosingBrace + 1) + ']';
       }
    }

    const rawData = JSON.parse(text);

    if (!Array.isArray(rawData)) return [];

    // Map to Byte structure
    return rawData.map((item: any, index: number) => {
      const cat = item.category || "World";
      return {
        id: `live-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
        title: item.title || "Breaking News",
        publisher: item.publisher || "Global Wire",
        authors: ["AI Curator"],
        abstract: item.abstract || "No summary available.",
        category: cat,
        readTime: "1 min read",
        fileUrl: getCategoryImageUrl(cat),
        likes: Math.floor(Math.random() * 500),
        comments: Math.floor(Math.random() * 50),
        isLiked: false,
        isSaved: false,
        publicationDate: "LIVE",
        sourceUrl: item.sourceUrl
      } as Byte;
    });

  } catch (e: any) {
    // Gracefully handle Rate Limits (429)
    if (e.message?.includes('429') || e.status === 429 || e.toString().includes('RESOURCE_EXHAUSTED')) {
        console.warn("API Rate Limit hit. Skipping this batch.");
        return [];
    }
    console.error("Failed to fetch live news:", e);
    return [];
  }
};

import React, { useState, useEffect, useMemo, useRef, useCallback } from 'react';
import Navbar from './components/Navbar';
import NewsSlide from './components/NewsSlide';
import CurateDrawer from './components/CurateDrawer';
import Onboarding from './components/Onboarding';
import { PAPERS } from './constants';
import { fetchRealTimeNews } from './services/geminiService';
import { Byte, UserPreferences } from './types';

const App: React.FC = () => {
  const [news, setNews] = useState<Byte[]>([]);
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [showOnboarding, setShowOnboarding] = useState<boolean>(true);
  const [selectedTopics, setSelectedTopics] = useState<string[]>(['US News', 'World', 'AI & Tech', 'Business', 'Science', 'Finance', 'Culture']);
  const [searchTerm, setSearchTerm] = useState('');
  const [isLiveLoading, setIsLiveLoading] = useState(false);
  const feedRef = useRef<HTMLDivElement>(null);

  /**
   * Safe Fetch Strategy:
   * Batches requests sequentially to avoid hitting Gemini 429 (Resource Exhausted) errors.
   */
  const handleLiveUpdate = useCallback(async () => {
    if (!process.env.API_KEY) return;

    setIsLiveLoading(true);

    // Group topics to reduce number of API calls (12 calls -> 4 calls)
    const BATCHES = [
      ['Breaking News USA', 'World News', 'Politics'],
      ['Technology', 'AI', 'Science'],
      ['Finance', 'Business', 'Crypto'],
      ['Entertainment', 'Culture', 'Sports']
    ];

    try {
      // Execute sequentially with delay
      for (const batch of BATCHES) {
         // Check if component is still mounted/user hasn't navigated away (simplified check)
         const newBytes = await fetchRealTimeNews(batch);

         if (newBytes.length > 0) {
           setNews(prev => {
             // Deduplicate
             const ids = new Set(prev.map(p => p.id));
             const unique = newBytes.filter(b => !ids.has(b.id));
             return [...unique, ...prev]; 
           });
         }

         // 1.5s delay between bursts to respect rate limits
         await new Promise(resolve => setTimeout(resolve, 1500));
      }
    } catch (err) {
      console.error("Error in live fetch:", err);
    } finally {
      setIsLiveLoading(false);
    }
  }, []);

  useEffect(() => {
    // 1. Load preferences
    const hasSeenOnboarding = localStorage.getItem('bytes_onboarded') === 'true';
    if (hasSeenOnboarding) {
      setShowOnboarding(false);
    }
    const storedPrefs = localStorage.getItem('bytes_prefs');
    if (storedPrefs) {
      const prefs = JSON.parse(storedPrefs) as UserPreferences;
      if (prefs.topics && prefs.topics.length > 0) {
        setSelectedTopics(prefs.topics);
      }
    }

    // 2. Initialize with static data
    setNews(PAPERS.map(p => ({ ...p, isLiked: false, isSaved: false })));

    // 3. Automatically fetch REAL-TIME news (with delay)
    const timer = setTimeout(() => handleLiveUpdate(), 1000);
    return () => clearTimeout(timer);

  }, [handleLiveUpdate]);

  const handleOnboardingComplete = (prefs: UserPreferences) => {
    setShowOnboarding(false);
    setSelectedTopics(prefs.topics);
    localStorage.setItem('bytes_onboarded', 'true');
    localStorage.setItem('bytes_prefs', JSON.stringify(prefs));
    handleLiveUpdate();
  };

  const handleLike = (id: string) => {
    setNews(prev => prev.map(item => 
      item.id === id ? { ...item, isLiked: !item.isLiked, likes: item.isLiked ? item.likes - 1 : item.likes + 1 } : item
    ));
  };

  const handleSave = (id: string) => {
    setNews(prev => prev.map(item => 
      item.id === id ? { ...item, isSaved: !item.isSaved } : item
    ));
  };

  const toggleTopic = (topic: string) => {
    setSelectedTopics(prev => 
      prev.includes(topic) ? prev.filter(t => t !== topic) : [...prev, topic]
    );
  };

  const filteredNews = useMemo(() => {
    return news.filter(byte => {
      // Always show live fetched items as they are most relevant
      if (byte.id.startsWith('live-')) return true;

      const matchesTopic = selectedTopics.includes(byte.category) || selectedTopics.length === 0;
      const matchesSearch = searchTerm === '' || 
        byte.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
        byte.abstract.toLowerCase().includes(searchTerm.toLowerCase());
      return matchesTopic && matchesSearch;
    });
  }, [news, selectedTopics, searchTerm]);

  return (
    <div className="relative h-screen w-screen overflow-hidden bg-gray-100">

      {showOnboarding ? (
        <Onboarding onComplete={handleOnboardingComplete} />
      ) : (
        <>
          {/* Main Feed */}
          <div 
            className={`
              relative z-10 w-full h-full transition-all duration-500 ease-[cubic-bezier(0.32,0.72,0,1)] bg-gray-100
              ${isDrawerOpen ? 'scale-90 opacity-80 blur-[1px]' : 'scale-100 opacity-100'}
            `}
            style={{ transformOrigin: 'center bottom' }}
          >
            <Navbar 
                onProfileClick={() => setIsDrawerOpen(true)}
                onSearchClick={() => setIsDrawerOpen(true)}
                onNotifyClick={() => {}}
                onLiveClick={() => handleLiveUpdate()}
                isLiveLoading={isLiveLoading}
            />

            <div 
                ref={feedRef}
                className="feed-container px-4 md:px-0 max-w-2xl mx-auto pt-24 pb-12"
            >
                {filteredNews.length > 0 ? (
                filteredNews.map((byte, index) => (
                    <NewsSlide 
                      key={`${byte.id}-${index}`} 
                      byte={byte} 
                      onLike={handleLike} 
                      onSave={handleSave} 
                    />
                ))
                ) : (
                <div className="h-full w-full flex flex-col items-center justify-center text-center p-8">
                    <h3 className="text-3xl font-serif-display font-bold text-black mb-2">No stories found.</h3>
                    <p className="text-sm text-gray-500 mb-8">Try adjusting your filters.</p>
                    <button 
                      onClick={() => setIsDrawerOpen(true)}
                      className="px-8 py-4 rounded-full bg-black text-white font-bold text-xs uppercase tracking-widest shadow-lg"
                    >
                      Open Settings
                    </button>
                </div>
                )}
            </div>
          </div>

          <CurateDrawer 
            isOpen={isDrawerOpen} 
            onClose={() => setIsDrawerOpen(false)}
            selectedTopics={selectedTopics}
            onTopicToggle={toggleTopic}
            onSearch={setSearchTerm}
          />
        </>
      )}
    </div>
  );
};

export default App;

