    setNews(PAPERS.map(p => ({ ...p, isLiked: false, isSaved: false })));

    // 3. Fetch ONLY the first batch automatically
    const timer = setTimeout(() => {
      loadBatch(0);
    }, 1500); // Slight delay to ensure UI is ready

