interface NewsSlideProps {
  byte: Byte;
  onLike: (id: string) => void;
  onSave: (id: string) => void;
}

const NewsSlide: React.FC<NewsSlideProps> = ({ byte, onLike, onSave }) => {
  const [isExpanded, setIsExpanded] = useState(false);

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (navigator.share) {
      try {
        await navigator.share({
          title: byte.title,
          text: byte.abstract,
          url: byte.sourceUrl || window.location.href,
        });
      } catch (err) { console.log('Error sharing:', err); }
    } else {
      navigator.clipboard.writeText(byte.sourceUrl || window.location.href);
      alert('Link copied to clipboard!');
    }
  };

  const handleFullStory = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (byte.sourceUrl) {
      window.open(byte.sourceUrl, '_blank');
    } else {
      alert("Source URL not available for this story.");
    }
  };

  return (
    // WRAPPER: Centers the floating card
    <div className="snap-center h-screen w-full flex items-center justify-center p-4 md:p-8">

      {/* 3D FLOATING CARD */}
      <div className="relative w-full max-w-[420px] h-[82vh] bg-white rounded-[40px] shadow-[0_35px_60px_-15px_rgba(0,0,0,0.15)] overflow-hidden transform transition-all duration-500 hover:scale-[1.01] flex flex-col">

        {/* IMAGE: Takes full height but is background */}
        <div className="absolute inset-0 z-0">
             <img 
                src={byte.fileUrl} 
                alt={byte.title} 
                className="w-full h-full object-cover"
             />
             {/* Gradient Overlay for Readability */}
             <div className="absolute inset-0 bg-gradient-to-b from-black/10 via-transparent to-black/80"></div>
             <div className="absolute inset-x-0 bottom-0 h-2/3 bg-gradient-to-t from-black via-black/50 to-transparent"></div>
        </div>

        {/* CONTENT LAYOUT */}
        <div className="relative z-10 flex flex-col justify-between h-full p-6 pb-8">

            {/* Top: Category Pill */}
            <div className="flex justify-between items-start">
                 <span className="px-3 py-1.5 bg-white/20 backdrop-blur-xl border border-white/20 rounded-full text-[10px] text-white font-bold uppercase tracking-widest shadow-lg">
                    {byte.category}
                 </span>
            </div>

            {/* Bottom: Info & Text */}
            <div className="flex flex-col gap-4">
                 {/* Publisher Info */}
                 <div className="flex items-center gap-2">
                    <div className="w-6 h-6 rounded-full bg-white flex items-center justify-center shadow-md">
                        <span className="font-serif font-bold text-[10px] text-black">V</span>
                    </div>
                    <span className="text-[10px] font-bold text-white/90 uppercase tracking-wide shadow-black drop-shadow-sm">{byte.publisher}</span>
                    <span className="text-[10px] text-white/60">•</span>
                    <span className="text-[10px] text-white/60 uppercase tracking-wide">{byte.publicationDate}</span>
                 </div>

                 {/* Title */}
                 <h2 className="font-serif-display text-3xl font-bold text-white leading-[1.1] drop-shadow-lg">
                    {byte.title}
                 </h2>

                 {/* Abstract */}
                 <div className={`overflow-hidden transition-all duration-300 ${isExpanded ? 'max-h-60 overflow-y-auto pr-2' : 'max-h-20'}`}>
                    <p 
                        className="font-sans text-sm leading-relaxed text-gray-200 drop-shadow-md"
                        onClick={() => setIsExpanded(!isExpanded)}
                    >
                        {byte.abstract}
                    </p>
                 </div>

                 {/* Actions Row */}
                 <div className="flex items-center justify-between pt-2">
                     <button 
                        onClick={handleFullStory}
                        className="px-5 py-2.5 bg-white text-black rounded-full text-[10px] font-bold uppercase tracking-widest hover:bg-gray-100 transition-colors shadow-lg"
                     >
                        Read Story
                     </button>

                     <div className="flex items-center gap-3">
                         {/* Like */}
                         <button 
                            onClick={() => onLike(byte.id)} 
                            className="w-10 h-10 rounded-full bg-white/10 backdrop-blur-md border border-white/10 flex items-center justify-center transition-transform active:scale-90"
                         >
                             <svg className={`w-5 h-5 ${byte.isLiked ? 'fill-red-500 text-red-500' : 'fill-none text-white'}`} stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
                               <path strokeLinecap="round" strokeLinejoin="round" d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" />
                             </svg>
                         </button>
                         {/* Share */}
                         <button 
                            onClick={handleShare}
                            className="w-10 h-10 rounded-full bg-white/10 backdrop-blur-md border border-white/10 flex items-center justify-center transition-transform active:scale-90 text-white"
                         >
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" /></svg>
                         </button>
                         {/* Save */}
                         <button 
                            onClick={() => onSave(byte.id)} 
                            className="w-10 h-10 rounded-full bg-white/10 backdrop-blur-md border border-white/10 flex items-center justify-center transition-transform active:scale-90 text-white"
                         >
                           <svg className={`w-5 h-5 ${byte.isSaved ? 'fill-white text-white' : 'fill-none text-white'}`} stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
                               <path strokeLinecap="round" strokeLinejoin="round" d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" />
                           </svg>
                         </button>
