        </div>

        {/* CONTENT LAYOUT */}
        <div className="relative z-10 flex flex-col justify-between h-full p-6 pb-8">

            {/* Top: Category Pill */}
            <div className="flex justify-between items-start">
                 <span className="px-3 py-1.5 bg-white/20 backdrop-blur-xl border border-white/20 rounded-full text-[10px] text-white font-bold uppercase tracking-widest shadow-lg">
                    {byte.category}
