                    <div className="w-6 h-6 rounded-full bg-white flex items-center justify-center shadow-md">
                        <span className="font-serif font-bold text-[10px] text-black">V</span>
                    </div>
                    <span className="text-[10px] font-bold text-white/90 uppercase tracking-wide shadow-black drop-shadow-sm">{byte.publisher}</span>
