                    <span className="text-[10px] text-white/60 uppercase tracking-wide">{byte.publicationDate}</span>
                 </div>

                 {/* Title */}
                 <h2 className="font-serif-display text-3xl font-bold text-white leading-[1.1] drop-shadow-lg">
                    {byte.title}
                 </h2>

                 {/* Abstract */}
                 <div className={`overflow-hidden transition-all duration-300 ${isExpanded ? 'max-h-60 overflow-y-auto pr-2' : 'max-h-20'}`}>
                    <p 
                        className="font-sans text-sm leading-relaxed text-gray-200 drop-shadow-md"
                        onClick={() => setIsExpanded(!isExpanded)}
                    >
                        {byte.abstract}
                    </p>
                 </div>

                 {/* Actions Row */}
                 <div className="flex items-center justify-between pt-2">
                     <button 
                        onClick={handleFullStory}
                        className="px-5 py-2.5 bg-white text-black rounded-full text-[10px] font-bold uppercase tracking-widest hover:bg-gray-100 transition-colors shadow-lg"
                     >
                        Read Story
                     </button>

                     <div className="flex items-center gap-3">
                         {/* Like */}
                         <button 
                            onClick={() => onLike(byte.id)} 
                            className="w-10 h-10 rounded-full bg-white/10 backdrop-blur-md border border-white/10 flex items-center justify-center transition-transform active:scale-90"
                         >
                             <svg className={`w-5 h-5 ${byte.isLiked ? 'fill-red-500 text-red-500' : 'fill-none text-white'}`} stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
                               <path strokeLinecap="round" strokeLinejoin="round" d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" />
                             </svg>
                         </button>
                         {/* Share */}
                         <button 
                            onClick={handleShare}
                            className="w-10 h-10 rounded-full bg-white/10 backdrop-blur-md border border-white/10 flex items-center justify-center transition-transform active:scale-90 text-white"
                         >
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" /></svg>
                         </button>
                         {/* Save */}
                         <button 
