import React, { useState, useEffect } from 'react';
import { UserPreferences } from '../types';

interface OnboardingProps {
  onComplete: (prefs: UserPreferences) => void;
}

const Onboarding: React.FC<OnboardingProps> = ({ onComplete }) => {
  const [step, setStep] = useState(1);
  const [isExiting, setIsExiting] = useState(false);
  const [prefs, setPrefs] = useState<UserPreferences>({
    topics: [],
    readingStyle: 'Brief summaries',
    tone: 'Straight facts',
    constraints: {
      noClickbait: true,
      fewerCelebrity: false,
      expertSources: true,
      safeMode: false
    }
  });

  const topicsList = ['AI & Tech', 'Startups', 'Global Markets', 'Policy', 'Geopolitics', 'Climate', 'Culture', 'Science', 'Finance', 'Health'];

  const toggleTopic = (topic: string) => {
    setPrefs(p => ({
      ...p,
      topics: p.topics.includes(topic) ? p.topics.filter(t => t !== topic) : [...p.topics, topic]
    }));
  };

  const handleNext = () => {
     setStep(s => s + 1);
  };

  const handleComplete = () => {
    setIsExiting(true);
    setTimeout(() => {
        onComplete(prefs);
    }, 800); // Allow exit animation to play
  };

  useEffect(() => {
    if (step === 4) {
      const timer = setTimeout(handleComplete, 2500);
      return () => clearTimeout(timer);
    }
  }, [step]);

  return (
    <div className={`fixed inset-0 z-[100] flex flex-col items-center justify-center overflow-hidden bg-[#F2F1EC] transition-opacity duration-700 ${isExiting ? 'opacity-0' : 'opacity-100'}`}>

      {/* 1. Subtle Premium Background Elements */}
      <div className="absolute inset-0 z-0">
          <div className="absolute top-[-20%] right-[-10%] w-[600px] h-[600px] bg-white rounded-full blur-[100px] opacity-60"></div>
          <div className="absolute bottom-[-10%] left-[-10%] w-[500px] h-[500px] bg-[#E5E4DE] rounded-full blur-[80px] opacity-60"></div>
      </div>

      {/* 2. MAIN CARD: 3D Depth Card */}
      <div className="relative z-10 w-full max-w-lg mx-4">

        <div className="relative bg-white/80 backdrop-blur-xl border border-white rounded-[40px] p-8 md:p-12 shadow-[0_30px_60px_-15px_rgba(0,0,0,0.1)] overflow-hidden transition-all duration-500">

            {/* Step 1: Welcome */}
            {step === 1 && (
                <div className="flex flex-col items-center text-center animate-fade-in">
                    <div className="w-20 h-20 mb-8 flex items-center justify-center bg-black text-white rounded-full shadow-xl">
                         <span className="font-serif-display text-4xl font-bold">V</span>
                    </div>

                    <h1 className="text-5xl font-serif-display font-bold text-gray-900 mb-4 tracking-tight">
                        Volv.
                    </h1>
                    <p className="text-lg text-gray-500 mb-12 font-sans leading-relaxed max-w-xs mx-auto">
                        Intelligent news, distilled for the modern mind.
                    </p>

                    <button 
                        onClick={handleNext}
                        className="group relative px-12 py-4 bg-black rounded-full transition-all hover:scale-105 hover:shadow-2xl"
                    >
                        <span className="relative z-10 font-bold text-white uppercase tracking-[0.2em] text-xs">Get Started</span>
                    </button>
                </div>
            )}

            {/* Step 2: Topics (Pill Selection) */}
            {step === 2 && (
                <div className="animate-fade-in">
                    <h2 className="text-3xl font-serif-display font-bold text-gray-900 mb-2 text-center">Curate.</h2>
                    <p className="text-gray-400 text-xs font-bold uppercase tracking-widest text-center mb-8">Select 3+ Interests</p>

                    <div className="flex flex-wrap gap-3 justify-center mb-12">
                        {topicsList.map(t => {
                            const isSelected = prefs.topics.includes(t);
                            return (
                                <button 
                                    key={t}
                                    onClick={() => toggleTopic(t)}
                                    className={`
                                        relative px-5 py-3 rounded-full text-sm font-bold transition-all duration-300 border
                                        ${isSelected 
                                            ? 'bg-black text-white border-black shadow-lg scale-105' 
                                            : 'bg-white border-gray-200 text-gray-500 hover:border-gray-300 hover:text-gray-900'}
                                    `}
                                >
                                    {t}
                                </button>
                            );
                        })}
                    </div>

                    <button 
                        onClick={handleNext}
                        disabled={prefs.topics.length < 3}
                        className="w-full py-4 rounded-full font-bold text-xs uppercase tracking-widest transition-all disabled:opacity-30
                        bg-black text-white shadow-lg hover:shadow-xl hover:scale-[1.01]"
                    >
                        Continue
                    </button>
                </div>
            )}

            {/* Step 3: Density */}
            {step === 3 && (
                <div className="animate-fade-in">
                    <h2 className="text-3xl font-serif-display font-bold text-gray-900 mb-2 text-center">Depth.</h2>
                    <p className="text-gray-400 text-xs font-bold uppercase tracking-widest text-center mb-8">Choose your flow</p>

                    <div className="space-y-4 mb-10">
                        {['Ultra quick (10s)', 'Brief summaries', 'Deep dives'].map(style => {
                            const val = style.split(' (')[0];
                            const isSelected = prefs.readingStyle === val;
                            return (
                                <button 
                                    key={style}
                                    onClick={() => { setPrefs(p => ({...p, readingStyle: val as any})); handleNext(); }}
                                    className={`
                                        w-full p-6 flex justify-between items-center text-left transition-all border rounded-3xl group
                                        ${isSelected 
                                            ? 'bg-black border-black text-white shadow-xl transform scale-[1.02]' 
                                            : 'bg-white border-gray-100 text-gray-500 hover:border-gray-200 hover:bg-gray-50'}
                                    `}
                                >
                                    <span className="font-bold text-lg font-serif-display">{style}</span>
                                    <div className={`
                                        w-5 h-5 rounded-full border-2 flex items-center justify-center transition-colors
                                        ${isSelected ? 'border-white bg-white' : 'border-gray-200 group-hover:border-gray-300'}
                                    `}>
                                        {isSelected && <div className="w-2 h-2 bg-black rounded-full" />}
                                    </div>
                                </button>
                            );
                        })}
                    </div>
                </div>
            )}

            {/* Step 4: Loading / Synthesis */}
            {step === 4 && (
                <div className="flex flex-col items-center justify-center py-12 animate-fade-in">
                    <div className="relative w-16 h-16 mb-8">
                        <div className="absolute inset-0 border-4 border-gray-100 rounded-full"></div>
                        <div className="absolute inset-0 border-4 border-black border-t-transparent rounded-full animate-spin"></div>
                    </div>

                    <h2 className="text-xl font-serif-display font-bold text-gray-900 mb-2">Personalizing Feed</h2>
                    <p className="text-xs text-gray-400 uppercase tracking-widest">Please wait...</p>
                </div>
            )}

        </div>

        {/* Footer Text */}
        <div className="text-center mt-6">
             <p className="text-[10px] text-gray-400 uppercase tracking-widest font-bold">Powered by Gemini 2.5</p>
        </div>

      </div>

      <style>{`
        @keyframes fade-in {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-fade-in {
          animation: fade-in 0.6s ease-out forwards;
        }
      `}</style>
    </div>
  );
};

export default Onboarding;

import React, { useState, useEffect, useMemo, useRef, useCallback } from 'react';
import Navbar from './components/Navbar';
import NewsSlide from './components/NewsSlide';
import CurateDrawer from './components/CurateDrawer';
import Onboarding from './components/Onboarding';
import { PAPERS } from './constants';
import { fetchRealTimeNews } from './services/geminiService';
import { Byte, UserPreferences } from './types';

const App: React.FC = () => {
  const [news, setNews] = useState<Byte[]>([]);
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [showOnboarding, setShowOnboarding] = useState<boolean>(true);
  const [selectedTopics, setSelectedTopics] = useState<string[]>(['US News', 'World', 'AI & Tech', 'Business', 'Science', 'Finance', 'Culture']);
  const [searchTerm, setSearchTerm] = useState('');

  // Streaming State
  const [streamStatus, setStreamStatus] = useState<string>(''); 
  const [isStreaming, setIsStreaming] = useState(false);

  const feedRef = useRef<HTMLDivElement>(null);
  const initialized = useRef(false);

  const BATCHES = useMemo(() => [
    ['Breaking News Global', 'World Politics'],
    ['Technology Trends', 'Artificial Intelligence'],
    ['Financial Markets', 'Crypto & Web3'],
    ['Science Breakthroughs', 'Health & Medicine'],
    ['Entertainment', 'Internet Culture', 'Sports']
  ], []);

  const startNewsStream = useCallback(async () => {
    if (!process.env.API_KEY || isStreaming) return;

    setIsStreaming(true);
    setStreamStatus('Initializing global feed...');

    for (let i = 0; i < BATCHES.length; i++) {
        const batchTopics = BATCHES[i];
        setStreamStatus(`Syncing: ${batchTopics.join(' & ')}...`);

        try {
            const newBytes = await fetchRealTimeNews(batchTopics);
            setNews(prev => {
                const existingIds = new Set(prev.map(p => p.id));
                const uniqueNew = newBytes.filter(b => !existingIds.has(b.id));
                return [...prev, ...uniqueNew];
            });

            if (i < BATCHES.length - 1) {
                await new Promise(resolve => setTimeout(resolve, 2000));
            }

        } catch (error) {
            console.error(`Batch ${i} failed`, error);
        }
    }

    setStreamStatus('');
    setIsStreaming(false);
  }, [BATCHES]);

  useEffect(() => {
    if (initialized.current) return;
    initialized.current = true;

    const hasSeenOnboarding = localStorage.getItem('bytes_onboarded') === 'true';
    if (hasSeenOnboarding) setShowOnboarding(false);

    const storedPrefs = localStorage.getItem('bytes_prefs');
    if (storedPrefs) {
      const prefs = JSON.parse(storedPrefs) as UserPreferences;
      if (prefs.topics?.length > 0) setSelectedTopics(prefs.topics);
    }

    setNews(PAPERS.map(p => ({ ...p, isLiked: false, isSaved: false })));

    if (hasSeenOnboarding) {
        setTimeout(startNewsStream, 1000);
    }
  }, [startNewsStream]);

  const handleRefresh = () => {
    setNews(PAPERS.map(p => ({ ...p, isLiked: false, isSaved: false })));
    feedRef.current?.scrollTo({ top: 0, behavior: 'smooth' });
    startNewsStream();
  };

  const handleOnboardingComplete = (prefs: UserPreferences) => {
    setShowOnboarding(false);
    setSelectedTopics(prefs.topics);
    localStorage.setItem('bytes_onboarded', 'true');
    localStorage.setItem('bytes_prefs', JSON.stringify(prefs));
    startNewsStream();
  };

  const handleLike = (id: string) => {
    setNews(prev => prev.map(item => 
      item.id === id ? { ...item, isLiked: !item.isLiked, likes: item.isLiked ? item.likes - 1 : item.likes + 1 } : item
    ));
  };

  const handleSave = (id: string) => {
    setNews(prev => prev.map(item => 
      item.id === id ? { ...item, isSaved: !item.isSaved } : item
    ));
  };

  const toggleTopic = (topic: string) => {
    setSelectedTopics(prev => 
      prev.includes(topic) ? prev.filter(t => t !== topic) : [...prev, topic]
    );
  };

  const filteredNews = useMemo(() => {
    return news.filter(byte => {
      if (byte.id.startsWith('live-') || byte.id.startsWith('fallback-')) return true; 
      const matchesTopic = selectedTopics.includes(byte.category) || selectedTopics.length === 0;
      const matchesSearch = searchTerm === '' || 
        byte.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
        byte.abstract.toLowerCase().includes(searchTerm.toLowerCase());
      return matchesTopic && matchesSearch;
    });
  }, [news, selectedTopics, searchTerm]);

  return (
    <div className="relative h-screen w-screen overflow-hidden bg-[#F2F1EC]">

      {showOnboarding ? (
        <Onboarding onComplete={handleOnboardingComplete} />
      ) : (
        <>
          <div 
            className={`
              relative z-10 w-full h-full transition-all duration-500 ease-[cubic-bezier(0.32,0.72,0,1)] bg-[#F2F1EC]
              ${isDrawerOpen ? 'scale-95 opacity-80 blur-[2px]' : 'scale-100 opacity-100'}
            `}
            style={{ transformOrigin: 'center center' }}
          >
            <Navbar 
                onProfileClick={() => setIsDrawerOpen(true)}
                onSearchClick={() => setIsDrawerOpen(true)}
                onNotifyClick={() => {}}
                onLiveClick={handleRefresh}
                isLiveLoading={isStreaming}
            />

            {/* FEED CONTAINER */}
            <div 
                ref={feedRef}
                className="h-screen w-full overflow-y-scroll snap-y snap-mandatory scroll-smooth no-scrollbar pt-20 md:pt-24"
            >
                {filteredNews.length > 0 ? (
                  <>
                    {filteredNews.map((byte, index) => (
                        <NewsSlide 
                          key={`${byte.id}-${index}`} 
                          byte={byte} 
                          onLike={handleLike} 
                          onSave={handleSave} 
                        />
                    ))}
                  </>
                ) : (
                    <div className="h-[70vh] w-full flex flex-col items-center justify-center text-center p-8 snap-center">
                        <h3 className="text-3xl font-serif-display font-bold text-[#1C1C1E] mb-3">Quiet today.</h3>
                        <p className="text-[#8E8E93] text-sm mb-8">Try adjusting your interests.</p>
                        <button 
                          onClick={() => setIsDrawerOpen(true)}
                          className="px-8 py-4 rounded-full bg-[#1C1C1E] text-white font-bold text-xs uppercase tracking-widest shadow-lg hover:scale-105 transition-transform"
                        >
                          Curate Feed
                        </button>
                    </div>
                )}

                {/* Status Indicator */}
                <div className="h-[30vh] w-full flex flex-col items-center justify-start pt-12 gap-3 transition-opacity duration-500 snap-center pb-20">
                    {isStreaming ? (
                        <>
                             <div className="flex items-center gap-2">
                                <span className="w-2 h-2 bg-[#1C1C1E] rounded-full animate-pulse"></span>
                                <span className="text-[10px] font-bold uppercase tracking-[0.2em] text-[#8E8E93]">Syncing global wire</span>
                            </div>
                            <div className="w-24 h-1 bg-[#E5E5EA] rounded-full overflow-hidden">
                                <div className="h-full bg-[#1C1C1E] animate-progress-indeterminate"></div>
                            </div>
                        </>
                    ) : (
                        <span className="text-[10px] font-bold uppercase tracking-[0.2em] text-[#D1D1D6]">
                             All Caught Up
                        </span>
                    )}
                </div>

            </div>
          </div>

          <CurateDrawer 
            isOpen={isDrawerOpen} 
            onClose={() => setIsDrawerOpen(false)}
            selectedTopics={selectedTopics}
            onTopicToggle={toggleTopic}
            onSearch={setSearchTerm}
          />
        </>
      )}

      <style>{`
        @keyframes progress-indeterminate {
            0% { width: 0%; margin-left: 0%; }
            50% { width: 50%; margin-left: 25%; }
            100% { width: 0%; margin-left: 100%; }
        }
        .animate-progress-indeterminate {
            animation: progress-indeterminate 1.5s infinite ease-in-out;
        }
      `}</style>
    </div>
  );
};

export default App;

