             {/* Gradient overlay for text protection if needed, though mostly clean */}
             <div className="absolute inset-0 bg-gradient-to-t from-black/40 to-transparent opacity-60"></div>

             {/* Category Pill Floating on Image */}
             <div className="absolute top-4 left-4">
                 <span className="px-4 py-1.5 bg-white/90 backdrop-blur-md rounded-full text-[10px] text-[#1C1C1E] font-bold uppercase tracking-widest shadow-sm">
                    {byte.category}
