                 <div className="flex items-center gap-2 opacity-60">
                    <span className="text-[10px] font-bold text-[#1C1C1E] uppercase tracking-wide">{byte.publisher}</span>
                    <span className="w-1 h-1 bg-[#1C1C1E] rounded-full"></span>
