                     >
                       <svg className={`w-5 h-5 ${byte.isSaved ? 'fill-[#1C1C1E] text-[#1C1C1E]' : 'fill-none text-[#1C1C1E]'}`} stroke="currentColor" strokeWidth="1.5" viewBox="0 0 24 24">
