                    </div>
                </div>
            )}

            {/* Step 4: Personalization Spinner */}
            {step === 4 && (
                <div className="flex flex-col items-center justify-center py-12">
                    <div className="relative w-16 h-16 mb-8">
                        <svg className="animate-spin w-full h-full text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="3"></circle>
                            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                        </svg>
                    </div>

                    <h2 className="text-xl font-serif-display font-bold text-white mb-2">Curating Feed</h2>
                    <p className="text-xs text-white/60 uppercase tracking-widest animate-pulse">Designing your experience...</p>
                </div>
            )}

        </div>

        {/* Footer Branding */}
        <div className="text-center mt-8">
             <p className="text-[9px] text-white/40 uppercase tracking-[0.2em] font-bold">Powered by Gemini</p>
        </div>

      </div>

      <style>{`
        @keyframes fade-in-up {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-fade-in-up {
          animation: fade-in-up 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards;
        }
      `}</style>
    </div>
  );
};

