import React, { useState, useRef, useEffect } from 'react';
import { Byte } from '../types';

interface NewsSlideProps {
  byte: Byte;
  onLike: (id: string) => void;
  onSave: (id: string) => void;
}

const NewsSlide: React.FC<NewsSlideProps> = ({ byte, onLike, onSave }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [inView, setInView] = useState(false);
  const slideRef = useRef<HTMLDivElement>(null);

  // Scroll Trigger Logic
  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        setInView(entry.isIntersecting);
      },
      { threshold: 0.4 }
    );

    if (slideRef.current) observer.observe(slideRef.current);
    return () => observer.disconnect();
  }, []);

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (navigator.share) {
      try {
        await navigator.share({
          title: byte.title,
          text: byte.abstract,
          url: byte.sourceUrl || window.location.href,
        });
      } catch (err) { console.log('Error sharing:', err); }
    } else {
      navigator.clipboard.writeText(byte.sourceUrl || window.location.href);
      alert('Link copied to clipboard!');
    }
  };

  const handleFullStory = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (byte.sourceUrl) {
      window.open(byte.sourceUrl, '_blank');
    } else {
      alert("Source URL not available for this story.");
    }
  };

  return (
    // WRAPPER: Full screen snap item with dynamic height for mobile
    // Added 'transparent' background to allow main app background to peek through
    <div 
        ref={slideRef}
        className="snap-start relative h-[100dvh] w-full bg-transparent overflow-hidden flex flex-col justify-end perspective-1000"
    >

      {/* 1. BACKGROUND IMAGE (Full Screen) */}
      <div className="absolute inset-0 z-0 overflow-hidden">
         <img 
            src={byte.fileUrl} 
            alt={byte.title} 
            className={`
                w-full h-full object-cover transition-transform duration-[8s] ease-out
                ${inView ? 'scale-110 opacity-100' : 'scale-100 opacity-90'}
            `}
            loading="lazy"
         />
         {/* Gradients for readability - adjusted for glass effect */}
         <div className="absolute inset-0 bg-gradient-to-b from-black/40 via-transparent to-black/90"></div>
         <div className="absolute bottom-0 left-0 right-0 h-3/5 bg-gradient-to-t from-black via-black/40 to-transparent opacity-80"></div>
      </div>

      {/* 2. FLOATING CONTENT LAYER */}
      {/* PADDING ADJUSTMENT: pb-24 ensures content sits above mobile home indicator/safe area */}
      <div className="relative z-10 w-full px-4 pb-24 flex items-end justify-between gap-2">

         {/* LEFT: Text Content Card (Glassmorphic) */}
         <div className={`flex-1 min-w-0 transition-all duration-700 delay-100 ease-out transform ${inView ? 'translate-y-0 opacity-100' : 'translate-y-12 opacity-0'}`}>

             {/* Volv Bits Pill */}
             <div className="inline-flex items-center gap-2 px-3 py-1.5 bg-white/10 backdrop-blur-md rounded-full mb-3 border border-white/20 shadow-sm">
                <div className="w-4 h-4 rounded-full bg-gradient-to-tr from-indigo-400 to-purple-400 flex items-center justify-center text-[8px] text-white font-bold shadow-glow">V</div>
                <span className="text-[10px] font-bold text-white uppercase tracking-widest">Volv Bits</span>
             </div>

             {/* Frosted Glass Card Container */}
             <div 
                className="glass-card rounded-[24px] p-5 origin-bottom-left w-full max-w-sm"
                onClick={() => setIsExpanded(!isExpanded)}
             >
                 <div className="flex flex-col gap-2">
                     {/* Headline */}
                     <h2 className="font-serif-display text-lg md:text-xl font-bold text-white leading-tight line-clamp-3 drop-shadow-md">
                        {byte.title}
                     </h2>

                     {/* Abstract */}
                     <div className={`transition-all duration-500 ease-[cubic-bezier(0.25,0.1,0.25,1)] overflow-hidden ${isExpanded ? 'max-h-60' : 'max-h-[3.5rem]'}`}>
                        <p className="font-sans text-xs md:text-sm leading-relaxed text-white/80">
                            {byte.abstract}
                        </p>
                     </div>

                     {/* Footer in Card */}
                     <div className="flex items-center justify-between pt-2 mt-1 border-t border-white/10">
                        <div className="flex items-center gap-2 truncate">
                            {byte.sourceUrl && (
                                <img src={`https://www.google.com/s2/favicons?domain=${new URL(byte.sourceUrl).hostname}&sz=32`} className="w-3 h-3 rounded-full opacity-80" alt="" />
                            )}
                             <span className="text-[9px] font-bold text-white/60 uppercase tracking-wide truncate max-w-[100px]">{byte.publisher}</span>
                        </div>
                        {isExpanded && (
                             <button 
                                onClick={handleFullStory}
                                className="px-3 py-1.5 bg-white text-black rounded-full text-[9px] font-bold uppercase tracking-widest hover:bg-gray-200 shrink-0"
                             >
                                Read
                             </button>
                        )}
                     </div>
                 </div>
             </div>

         </div>

         {/* RIGHT: Floating Actions (Vertical Stack) - Fixed Width to prevent overlapping */}
         <div className="flex flex-col items-center gap-5 mb-2 shrink-0 w-12">

             {/* Like */}
             <div className={`flex flex-col items-center gap-0.5 transition-all duration-500 delay-[200ms] ${inView ? 'translate-x-0 opacity-100' : 'translate-x-4 opacity-0'}`}>
                 <button 
                    onClick={() => onLike(byte.id)}
