                     <div className="p-2 rounded-full bg-white/10 backdrop-blur-sm border border-white/10 group-hover:bg-white/20 transition-all">
                        <svg 
                            className={`w-6 h-6 drop-shadow-md transition-all duration-300 ${byte.isLiked ? 'fill-rose-500 text-rose-500 scale-110' : 'fill-white/10 text-white hover:scale-110'}`} 
                            viewBox="0 0 24 24" 
