                 <button className="p-1.5 transition-transform active:scale-75 group">
                     <div className="p-2 rounded-full bg-white/10 backdrop-blur-sm border border-white/10 group-hover:bg-white/20 transition-all">
                        <svg className="w-5 h-5 text-white drop-shadow-md" fill="currentColor" viewBox="0 0 24 24"><path fillRule="evenodd" clipRule="evenodd" d="M12 22C17.5228 22 22 17.5228 22 12C22 6.47715 17.5228 2 12 2C6.47715 2 2 6.47715 2 12C2 13.5997 2.37562 15.1116 3.04346 16.4525C3.22094 16.8088 3.28001 17.2161 3.17712 17.6006L2.58151 19.8267C2.32295 20.793 3.20701 21.677 4.17335 21.4185L6.39939 20.8229C6.78393 20.72 7.19121 20.7791 7.54753 20.9565C8.88837 21.6244 10.4003 22 12 22ZM8 11C8 11.5523 8.44772 12 9 12H15C15.5523 12 16 11.5523 16 11C16 10.4477 15.5523 10 15 10H9C8.44772 10 8 10.4477 8 11ZM8 15C8 15.5523 8.44772 16 9 16H12C12.5523 16 13 15.5523 13 15C13 14.4477 12.5523 14 12 14H9C8.44772 14 8 14.4477 8 15Z" opacity="0.9" /></svg>
                     </div>
                 </button>
                 <span className="text-white text-[10px] font-bold drop-shadow-md">{byte.comments}</span>
             </div>

             {/* Save */}
             <div className={`flex flex-col items-center gap-0.5 transition-all duration-500 delay-[400ms] ${inView ? 'translate-x-0 opacity-100' : 'translate-x-4 opacity-0'}`}>
                 <button 
                    onClick={() => onSave(byte.id)} 
                    className="p-1.5 transition-transform active:scale-75 group"
                 >
                    <div className="p-2 rounded-full bg-white/10 backdrop-blur-sm border border-white/10 group-hover:bg-white/20 transition-all">
                        <svg 
                            className={`w-5 h-5 drop-shadow-md transition-all duration-300 ${byte.isSaved ? 'fill-white text-white' : 'fill-none text-white hover:scale-110'}`} 
                            stroke="currentColor" 
                            strokeWidth="2" 
                            viewBox="0 0 24 24"
