/**
 * Fetches real-time news using Google Search Grounding.
 */
export const fetchRealTimeNews = async (topics: string[]): Promise<Byte[]> => {
  if (!process.env.API_KEY) {
    console.warn("No API Key found for live news");
    return [];
  }

  const topicString = topics.length > 0 ? topics.join(', ') : 'Global Breaking News';

  const prompt = `
    Search for exactly 4 RECENT and SPECIFIC breaking news stories about: ${topicString}.

    CRITICAL REQUIREMENTS:
    1. Provide the FULL DEEP-LINK URL to the actual article page. DO NOT provide the homepage URL (e.g., use 'https://nytimes.com/specific-article' NOT 'https://nytimes.com').
    2. Respond strictly with a JSON array. No markdown, no commentary.

    Fields for each object:
    - "title": Compelling headline (<12 words).
    - "publisher": The specific news source name.
    - "abstract": A concise, high-impact summary (25-35 words).
    - "category": Broad topic (e.g., AI, Tech, World).
    - "sourceUrl": The specific deep-link article URL.
  `;

  const generate = async (retryCount = 0): Promise<any> => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      return await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: prompt,
        config: {
          tools: [{ googleSearch: {} }],
        },
      });
    } catch (error: any) {
      if ((error.status === 429 || error.message?.includes('429')) && retryCount < 1) {
         await new Promise(resolve => setTimeout(resolve, 3000));
         return generate(retryCount + 1);
      }
      throw error;
    }
  };

  try {
    const response = await generate();
    let text = response.text || "";
    text = text.replace(/```json/g, '').replace(/```/g, '').trim();

    // Basic repair for common JSON truncation
    if (text.startsWith('[') && !text.endsWith(']')) {
       const lastBrace = text.lastIndexOf('}');
       if (lastBrace !== -1) text = text.substring(0, lastBrace + 1) + ']';
    }

    const rawData = JSON.parse(text);
    if (!Array.isArray(rawData)) return generateFallbackNews(topicString);

    // Extraction of Grounding Links
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const webLinks = groundingChunks
      .filter((c: any) => c.web && c.web.uri)
      .map((c: any) => c.web.uri);

    return rawData.map((item: any, index: number) => {
      const cat = item.category || "World";

      // Determine the best URL
      // We prefer the item.sourceUrl from the model IF it looks like a deep link (contains slashes after domain)
      // Otherwise, we fallback to grounding chunks which are verified by Google Search
      let finalUrl = item.sourceUrl || "https://news.google.com";

      const isGeneric = (url: string) => {
        try {
          const u = new URL(url);
          return u.pathname === "/" || u.pathname === "" || u.pathname.length < 5;
        } catch { return true; }
      };

      if (isGeneric(finalUrl) && webLinks[index]) {
        finalUrl = webLinks[index];
      }

      return {
        id: `live-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
        title: item.title || "Breaking Update",
        publisher: item.publisher || "Global News",
        authors: ["AI Curator"],
        abstract: item.abstract || "Detailed coverage of this event is currently unfolding.",
        category: cat,
        readTime: "1 min read",
        fileUrl: getCategoryImageUrl(cat),
        likes: Math.floor(Math.random() * 400 + 100),
        comments: Math.floor(Math.random() * 20),
        isLiked: false,
        isSaved: false,
        publicationDate: "NOW",
        sourceUrl: finalUrl
      } as Byte;
    });

  } catch (e: any) {
    console.error("Gemini Fetch Error:", e);
    return generateFallbackNews(topicString);
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { Byte } from '../types';

interface NewsSlideProps {
  byte: Byte;
  onLike: (id: string) => void;
  onSave: (id: string) => void;
}

const NewsSlide: React.FC<NewsSlideProps> = ({ byte, onLike, onSave }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [inView, setInView] = useState(false);
  const slideRef = useRef<HTMLDivElement>(null);

  // Scroll Trigger Logic
  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        setInView(entry.isIntersecting);
      },
      { threshold: 0.4 }
    );

    if (slideRef.current) observer.observe(slideRef.current);
    return () => observer.disconnect();
  }, []);

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (navigator.share) {
      try {
        await navigator.share({
          title: byte.title,
          text: byte.abstract,
          url: byte.sourceUrl || window.location.href,
        });
      } catch (err) { console.log('Error sharing:', err); }
    } else {
      navigator.clipboard.writeText(byte.sourceUrl || window.location.href);
      alert('Link copied to clipboard!');
    }
  };

  const handleFullStory = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (byte.sourceUrl) {
      // Direct opening in a new tab is the most reliable way to handle external deep links
      // especially when inside a container or iframe.
      const win = window.open(byte.sourceUrl, '_blank', 'noopener,noreferrer');
      if (win) win.focus();
    } else {
      alert("Source link unavailable for this story.");
    }
  };

  return (
    <div 
        ref={slideRef}
        className="snap-start relative h-[100dvh] w-full bg-transparent overflow-hidden flex flex-col justify-end perspective-1000"
    >
      <div className="absolute inset-0 z-0 overflow-hidden rounded-[40px] m-2 md:m-4 shadow-2xl">
         <img 
            src={byte.fileUrl} 
            alt={byte.title} 
            className={`
                w-full h-full object-cover transition-transform duration-[8s] ease-out
                ${inView ? 'scale-110 opacity-100' : 'scale-100 opacity-90'}
            `}
            loading="lazy"
         />
         <div className="absolute inset-0 bg-gradient-to-b from-transparent via-transparent to-black/30"></div>
         <div className="absolute bottom-0 left-0 right-0 h-1/2 bg-gradient-to-t from-black/50 to-transparent"></div>
      </div>

      <div className="relative z-10 w-full px-6 pb-28 flex items-end justify-between gap-4">
         <div className={`flex-1 min-w-0 transition-all duration-700 delay-100 ease-out transform ${inView ? 'translate-y-0 opacity-100' : 'translate-y-12 opacity-0'}`}>
             <div className="inline-flex items-center gap-2 px-3 py-1.5 bg-white/80 backdrop-blur-md rounded-full mb-3 shadow-lg">
                <div className="w-4 h-4 rounded-full bg-gradient-to-tr from-pink-400 to-rose-400 flex items-center justify-center text-[8px] text-white font-bold">V</div>
