/**
 * Fetches real-time news using Google Search Grounding.
 */
export const fetchRealTimeNews = async (topics: string[]): Promise<Byte[]> => {
  if (!process.env.API_KEY) {
    console.warn("No API Key found for live news");
    return [];
  }

  const topicString = topics.length > 0 ? topics.join(', ') : 'Global Breaking News';

  const prompt = `
    Using Google Search, find exactly 4 CURRENT, SPECIFIC, and ACCURATE breaking news stories about: ${topicString}.

    CRITICAL INSTRUCTION FOR LINKS:
    Every story MUST have a "sourceUrl" that is a DEEP-LINK to the actual article page. 
    A deep-link MUST have a specific path (e.g., "site.com/2024/news/headline"). 
    DO NOT provide homepage URLs (e.g., "nytimes.com"). If you only have a homepage URL, find a different story.

    Respond STRICTLY with a JSON array. 
    Required JSON Fields:
    - "title": Concise headline (max 10 words).
    - "publisher": The specific media outlet name.
    - "abstract": A high-signal summary (25-35 words).
    - "category": Choose from (US News, World, AI & Tech, Business, Science, Finance, Culture).
    - "sourceUrl": The verified deep-link article URL.
  `;

  const generate = async (retryCount = 0): Promise<any> => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      return await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: prompt,
        config: {
          tools: [{ googleSearch: {} }],
        },
      });
    } catch (error: any) {
      if ((error.status === 429 || error.message?.includes('429')) && retryCount < 1) {
         await new Promise(resolve => setTimeout(resolve, 3000));
         return generate(retryCount + 1);
      }
      throw error;
    }
  };

  try {
    const response = await generate();
    let text = response.text || "";

    // Clean JSON response
    text = text.replace(/```json/g, '').replace(/```/g, '').trim();

    // Final attempt to fix common formatting issues
    if (text.startsWith('[') && !text.endsWith(']')) {
       const lastBrace = text.lastIndexOf('}');
       if (lastBrace !== -1) text = text.substring(0, lastBrace + 1) + ']';
    }

    const rawData = JSON.parse(text);
    if (!Array.isArray(rawData)) return generateFallbackNews(topicString);

    // Extraction of Grounding Links to cross-reference
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const webLinks = groundingChunks
      .filter((c: any) => c.web && c.web.uri)
      .map((c: any) => c.web.uri);

    return rawData.map((item: any, index: number) => {
      const cat = item.category || "World";

      // Validation logic: check if URL is likely a deep link
      const isDeepLink = (url: string) => {
        try {
          const u = new URL(url);
          // Check if pathname has content beyond just a trailing slash
          const path = u.pathname.replace(/\/$/, "");
          return path.length > 5; // Heuristic: path needs to be long enough to be an article
        } catch { return false; }
      };

      let finalUrl = item.sourceUrl || "";

      // If the provided link is weak, try to grab one from search grounding metadata
      if (!isDeepLink(finalUrl) && webLinks.length > 0) {
          // If we have grounding links, use the one corresponding to this index or the first one
          finalUrl = webLinks[index] || webLinks[0];
      }

      // Final fallback if everything is still broken
      if (!finalUrl || finalUrl === "" || !finalUrl.startsWith('http')) {
          finalUrl = "https://news.google.com/search?q=" + encodeURIComponent(item.title || topicString);
      }

      return {
        id: `live-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
        title: item.title || "Breaking Update",
        publisher: item.publisher || "Global Wire",
        authors: ["AI Curator"],
        abstract: item.abstract || "Detailed coverage of this event is currently unfolding from verified sources.",
        category: cat,
        readTime: "1 min read",
        fileUrl: getCategoryImageUrl(cat),
        likes: Math.floor(Math.random() * 400 + 100),
        comments: Math.floor(Math.random() * 25),
        isLiked: false,
        isSaved: false,
        publicationDate: "NOW",
        sourceUrl: finalUrl
      } as Byte;
    });

  } catch (e: any) {
    console.error("Gemini Fetch Error:", e);
    return generateFallbackNews(topicString);
  }
};

