 */
export const fetchRealTimeNews = async (topics: string[]): Promise<Byte[]> => {
  if (!process.env.API_KEY) {
    console.warn("No API Key found for live news");
    return [];
  }

  const topicString = topics.length > 0 ? topics.join(', ') : 'Global Breaking News';

  const prompt = `
    Using Google Search grounding, identify 4 distinct, highly specific, and very recent breaking news stories regarding: ${topicString}.

    STRICT URL GUIDELINES:
    - You MUST provide the direct URL to the full article page for each story.
    - A valid deep-link URL must contain a specific article path (e.g., domain.com/year/month/day/headline).
    - NEVER provide a homepage URL like 'cnn.com' or 'bbc.co.uk'. 
    - Verify that each 'sourceUrl' you provide actually exists in your search results.

    Return ONLY a JSON array with these fields:
    - "title": Impactful headline (<12 words).
    - "publisher": The specific news organization.
    - "abstract": A precise summary (20-30 words).
    - "category": Topic tag (e.g. World, Tech, Science).
    - "sourceUrl": THE VERIFIED DEEP-LINK URL.
  `;

  const generate = async (retryCount = 0): Promise<any> => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      return await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: prompt,
        config: {
          tools: [{ googleSearch: {} }],
        },
      });
    } catch (error: any) {
      if ((error.status === 429 || error.message?.includes('429')) && retryCount < 1) {
         await new Promise(resolve => setTimeout(resolve, 3000));
         return generate(retryCount + 1);
      }
      throw error;
    }
  };

  try {
    const response = await generate();
    let text = response.text || "";

    // Extract JSON safely
    const jsonMatch = text.match(/\[[\s\S]*\]/);
    if (jsonMatch) {
      text = jsonMatch[0];
    }

    const rawData = JSON.parse(text);
    if (!Array.isArray(rawData)) return generateFallbackNews(topicString);

    // Extract real URLs from the grounding metadata provided by the tool
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const verifiedUris = groundingChunks
      .filter((chunk: any) => chunk.web && chunk.web.uri)
      .map((chunk: any) => chunk.web.uri);

    return rawData.map((item: any, index: number) => {
      const cat = item.category || "World";

      // Accuracy logic: Cross-reference model output with search results
      const isGeneric = (url: string) => {
        try {
          const u = new URL(url);
          const p = u.pathname.replace(/\/$/, "");
          return p.length < 6 || p.includes('home') || p.includes('index');
        } catch { return true; }
      };

      let finalUrl = item.sourceUrl || "";

      // If the model's chosen URL looks like a homepage, swap it for a verified URI from search grounding
      if (isGeneric(finalUrl) && verifiedUris.length > 0) {
          // Attempt to match by index, or fallback to first available search result
          finalUrl = verifiedUris[index] || verifiedUris[0];
      }

      // If still generic or missing, use a direct search link as a safety net
      if (isGeneric(finalUrl)) {
          finalUrl = `https://www.google.com/search?q=${encodeURIComponent(item.title)}&tbm=nws`;
      }

      return {
        id: `live-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
        title: item.title || "Breaking News Update",
        publisher: item.publisher || "News Wire",
        authors: ["AI Curator"],
        abstract: item.abstract || "Detailed coverage of this specific development is now available from verified sources.",
        category: cat,
        readTime: "1 min read",
        fileUrl: getCategoryImageUrl(cat),
        likes: Math.floor(Math.random() * 500 + 50),
        comments: Math.floor(Math.random() * 30),
        isLiked: false,
        isSaved: false,
        publicationDate: "JUST NOW",
        sourceUrl: finalUrl
      } as Byte;
    });

  } catch (e: any) {
    console.error("Gemini Live News Error:", e);
    return generateFallbackNews(topicString);
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { Byte } from '../types';

interface NewsSlideProps {
  byte: Byte;
  onLike: (id: string) => void;
  onSave: (id: string) => void;
}

const NewsSlide: React.FC<NewsSlideProps> = ({ byte, onLike, onSave }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [inView, setInView] = useState(false);
  const slideRef = useRef<HTMLDivElement>(null);

  // Scroll Trigger Logic
  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        setInView(entry.isIntersecting);
      },
      { threshold: 0.4 }
    );

    if (slideRef.current) observer.observe(slideRef.current);
    return () => observer.disconnect();
  }, []);

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (navigator.share) {
      try {
        await navigator.share({
          title: byte.title,
          text: byte.abstract,
          url: byte.sourceUrl || window.location.href,
        });
      } catch (err) { console.log('Error sharing:', err); }
    } else {
      navigator.clipboard.writeText(byte.sourceUrl || window.location.href);
      alert('Link copied to clipboard!');
    }
  };

  const handleFullStory = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (byte.sourceUrl) {
      // Direct opening in a new window is the most resilient method for modern browsers
      // especially when dealing with sites that implement frame-busting or strict CSP.
      const newsWindow = window.open(byte.sourceUrl, '_blank', 'noopener,noreferrer');
      if (newsWindow) {
        newsWindow.focus();
      }
    } else {
      alert("Source link unavailable for this story.");
    }
  };

  return (
    <div 
        ref={slideRef}
        className="snap-start relative h-[100dvh] w-full bg-transparent overflow-hidden flex flex-col justify-end perspective-1000"
    >
      <div className="absolute inset-0 z-0 overflow-hidden rounded-[40px] m-2 md:m-4 shadow-2xl">
         <img 
            src={byte.fileUrl} 
            alt={byte.title} 
            className={`
                w-full h-full object-cover transition-transform duration-[8s] ease-out
                ${inView ? 'scale-110 opacity-100' : 'scale-100 opacity-90'}
            `}
            loading="lazy"
         />
         <div className="absolute inset-0 bg-gradient-to-b from-transparent via-transparent to-black/30"></div>
         <div className="absolute bottom-0 left-0 right-0 h-1/2 bg-gradient-to-t from-black/50 to-transparent"></div>
      </div>

      <div className="relative z-10 w-full px-6 pb-28 flex items-end justify-between gap-4">
         <div className={`flex-1 min-w-0 transition-all duration-700 delay-100 ease-out transform ${inView ? 'translate-y-0 opacity-100' : 'translate-y-12 opacity-0'}`}>
             <div className="inline-flex items-center gap-2 px-3 py-1.5 bg-white/80 backdrop-blur-md rounded-full mb-3 shadow-lg">
                <div className="w-4 h-4 rounded-full bg-gradient-to-tr from-pink-400 to-rose-400 flex items-center justify-center text-[8px] text-white font-bold">V</div>
                <span className="text-[10px] font-bold text-[#831843] uppercase tracking-widest">Volv Bits</span>
             </div>

             <div 
                className="glass-card rounded-[28px] p-6 origin-bottom-left w-full max-w-md shadow-2xl cursor-pointer"
                onClick={() => setIsExpanded(!isExpanded)}
             >
                 <div className="flex flex-col gap-2">
                     <h2 className="font-serif-display text-lg md:text-2xl font-bold text-[#4a044e] leading-tight line-clamp-3">
                        {byte.title}
                     </h2>

                     <div className={`transition-all duration-500 ease-[cubic-bezier(0.25,0.1,0.25,1)] overflow-hidden ${isExpanded ? 'max-h-60' : 'max-h-[3.5rem]'}`}>
                        <p className="font-sans text-xs md:text-sm leading-relaxed text-[#831843]/80 font-medium">
                            {byte.abstract}
                        </p>
                     </div>

                     <div className="flex items-center justify-between pt-3 mt-1 border-t border-[#831843]/10">
                        <div className="flex items-center gap-2 truncate">
                            {byte.sourceUrl && (
                                <img src={`https://www.google.com/s2/favicons?domain=${new URL(byte.sourceUrl).hostname}&sz=32`} className="w-4 h-4 rounded-full opacity-80" alt="" />
                            )}
                             <span className="text-[9px] font-bold text-[#831843]/60 uppercase tracking-wide truncate max-w-[120px]">{byte.publisher}</span>
                        </div>
                        {isExpanded && (
                             <button 
                                onClick={handleFullStory}
                                className="px-4 py-1.5 bg-[#831843] text-white rounded-full text-[9px] font-bold uppercase tracking-widest hover:scale-105 transition-transform shrink-0 shadow-md active:opacity-70"
                             >
                                Read
                             </button>
                        )}
                     </div>
                 </div>
             </div>
         </div>

         <div className="flex flex-col items-center gap-5 mb-2 shrink-0 w-12">
             <div className={`flex flex-col items-center gap-1 transition-all duration-500 delay-[200ms] ${inView ? 'translate-x-0 opacity-100' : 'translate-x-4 opacity-0'}`}>
                 <button 
                    onClick={() => onLike(byte.id)}
                    className="p-1.5 transition-transform active:scale-75 group"
