/**
 * Heuristic to find the best matching link for a headline from search metadata
 */
const findBestVerifiedLink = (headline: string, publisher: string, groundingChunks: any[]) => {
  if (!groundingChunks || groundingChunks.length === 0) return null;

  const hLower = headline.toLowerCase();
  const pLower = publisher.toLowerCase();

  // Scoring results based on title overlap and publisher matching
  const scoredResults = groundingChunks
    .filter(chunk => chunk.web && chunk.web.uri)
    .map(chunk => {
        const cTitle = (chunk.web.title || "").toLowerCase();
        const cUri = chunk.web.uri.toLowerCase();

        let score = 0;
        // Check word overlap
        const hWords = hLower.split(/\W+/).filter(w => w.length > 3);
        hWords.forEach(w => { if (cTitle.includes(w)) score += 10; });

        // Publisher bonus
        if (cTitle.includes(pLower) || cUri.includes(pLower.replace(/\s+/g, ''))) score += 30;

        // Penalize generic homepages
        const path = new URL(chunk.web.uri).pathname;
        if (path === "/" || path === "" || path.length < 5) score -= 50;

        return { uri: chunk.web.uri, score };
    })
    .sort((a, b) => b.score - a.score);

  return scoredResults[0]?.score > 0 ? scoredResults[0].uri : null;
};

export const fetchRealTimeNews = async (topics: string[]): Promise<Byte[]> => {
  if (!process.env.API_KEY) return [];

  const topicString = topics.length > 0 ? topics.join(', ') : 'Global News';

  const prompt = `
    Find 4 specific, recent news stories about: ${topicString}.

    CRITICAL ACCURACY RULES:
    1. For each story, you MUST provide the specific article URL (DEEP LINK).
    2. The 'sourceUrl' MUST lead directly to the story, NOT a homepage or category page.
    3. Ensure the title and publisher match actual recent reporting.

    Output strictly as a JSON array with these fields:
    - "title": Specific headline.
    - "publisher": News source name.
    - "abstract": 25-word summary.
    - "category": Topic (World, Tech, Business, etc.).
    - "sourceUrl": VERIFIED DEEP-LINK URL.
  `;

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: { tools: [{ googleSearch: {} }] },
    });

    let text = response.text || "[]";
    const jsonMatch = text.match(/\[[\s\S]*\]/);
    if (jsonMatch) text = jsonMatch[0];

    const rawData = JSON.parse(text);
    if (!Array.isArray(rawData)) return generateFallbackNews(topicString);

    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

    return rawData.map((item: any) => {
      const cat = item.category || "World";

      // Step 1: Try to find a verified link from the search grounding metadata
      const verifiedLink = findBestVerifiedLink(item.title, item.publisher, groundingChunks);

      // Step 2: Use the model's URL if it looks like a deep link, otherwise use verified
      const isDeep = (url: string) => {
        try { return new URL(url).pathname.length > 8; } catch { return false; }
      };

      let finalUrl = verifiedLink || item.sourceUrl || "";

      // Safety Fallback: If no deep link exists, create a specific Google News search for THIS story
      if (!isDeep(finalUrl)) {
          finalUrl = `https://news.google.com/search?q=${encodeURIComponent(item.title + " " + item.publisher)}&hl=en-US&gl=US&ceid=US:en`;
      }

      return {
        id: `live-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
        title: item.title || "Breaking News",
        publisher: item.publisher || "News Source",
        authors: ["AI Curator"],
        abstract: item.abstract || "Summary unavailable.",
        category: cat,
        readTime: "1 min read",
        fileUrl: getCategoryImageUrl(cat),
        likes: Math.floor(Math.random() * 300 + 50),
        comments: Math.floor(Math.random() * 15),
        isLiked: false,
        isSaved: false,
        publicationDate: "NOW",
        sourceUrl: finalUrl
      } as Byte;
    });

  } catch (e) {
    console.error("News Fetch Failed:", e);
    return generateFallbackNews(topicString);
  }
};

