/**
 * Robust heuristic to match a model-generated item with a verified search link.
 * Prioritizes deep-links and matches based on headline keyword overlap.
 */
const findBestVerifiedLink = (headline: string, publisher: string, groundingChunks: any[]) => {
  if (!groundingChunks || groundingChunks.length === 0) return null;

  // Normalize inputs for better matching
  const hNorm = headline.toLowerCase().replace(/[^\w\s]/g, '');
  const pNorm = publisher.toLowerCase().replace(/[^\w\s]/g, '');
  const hWords = hNorm.split(/\s+/).filter(w => w.length > 3);

  const scoredResults = groundingChunks
    .filter(chunk => chunk.web && chunk.web.uri)
    .map(chunk => {
        const cTitle = (chunk.web.title || "").toLowerCase();
        const cUri = chunk.web.uri.toLowerCase();
        let score = 0;

        // Word overlap scoring
        hWords.forEach(w => {
            if (cTitle.includes(w)) score += 20;
        });

        // Publisher check
        if (cTitle.includes(pNorm) || cUri.includes(pNorm.replace(/\s+/g, ''))) {
            score += 40;
        }

        // Deep-link validation: path must contain more than just '/' or '/index'
        try {
            const url = new URL(chunk.web.uri);
            const path = url.pathname.replace(/\/$/, "");
            if (path.length > 8 && !path.includes('home') && !path.includes('category')) {
                score += 30;
            } else {
                score -= 100; // Heavy penalty for homepages
            }
        } catch {
            score -= 100;
        }

        return { uri: chunk.web.uri, score };
    })
    .sort((a, b) => b.score - a.score);

  // Return the highest scoring result if it passes a minimum threshold
  return scoredResults[0] && scoredResults[0].score > 30 ? scoredResults[0].uri : null;
};

export const fetchRealTimeNews = async (topics: string[]): Promise<Byte[]> => {
  if (!process.env.API_KEY) return [];

  const topicString = topics.length > 0 ? topics.join(', ') : 'Global Breaking News';

  const prompt = `
    Perform a Google Search for the 4 most recent, specific, and impactful news articles regarding: ${topicString}.

    CRITICAL REQUIREMENT FOR REDIRECTION ACCURACY:
    For every news story, you must identify its unique DEEP-LINK URL. 
    A deep-link MUST point to a specific article page (e.g., "example.com/2024/news/headline-slug").
    STRICTLY AVOID generic homepages or index pages (e.g., do NOT use "cnn.com" or "bbc.com").

    If you cannot find a specific article link for a story, skip that story and find another one that has a verified source URL.

    Respond ONLY with a JSON array:
    - "title": The EXACT or very close headline from the source.
    - "publisher": The news organization name.
    - "abstract": A 25-30 word summary that distills the key fact.
    - "category": Choose one: World, Tech, Business, Science, Politics, Finance, Culture.
    - "sourceUrl": THE VERIFIED DEEP-LINK URL.
  `;

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: { 
        tools: [{ googleSearch: {} }],
      },
    });

    let text = response.text || "[]";
    const jsonMatch = text.match(/\[[\s\S]*\]/);
    if (jsonMatch) text = jsonMatch[0];

    const rawData = JSON.parse(text);
    if (!Array.isArray(rawData)) return generateFallbackNews(topicString);

    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

    return rawData.map((item: any, index: number) => {
      const cat = item.category || "World";

      // 1. Try to find a verified link from the actual search results using semantic matching
      let finalUrl = findBestVerifiedLink(item.title, item.publisher, groundingChunks);

      // 2. If semantic matching fails, check if the model's provided URL is a deep-link
      if (!finalUrl) {
          const modelUrl = item.sourceUrl || "";
          try {
              const u = new URL(modelUrl);
              const path = u.pathname.replace(/\/$/, "");
              if (path.length > 10 && !path.includes('home')) {
                  finalUrl = modelUrl;
              }
          } catch {}
      }

      // 3. Last Resort: Search Redirect
      // If we still don't have a reliable deep-link, we create a precision search link 
      // which is better than landing on a generic homepage.
      if (!finalUrl) {
          finalUrl = `https://www.google.com/search?q=${encodeURIComponent(item.title + " " + item.publisher)}&tbm=nws`;
      }

      return {
        id: `live-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
        title: item.title || "Latest Update",
        publisher: item.publisher || "Global Wire",
        authors: ["AI Curator"],
        abstract: item.abstract || "Detailed coverage of this specific development is currently being updated.",
        category: cat,
        readTime: "1 min read",
        fileUrl: getCategoryImageUrl(cat),
        likes: Math.floor(Math.random() * 400 + 50),
        comments: Math.floor(Math.random() * 20),
        isLiked: false,
        isSaved: false,
        publicationDate: "NOW",
        sourceUrl: finalUrl
      } as Byte;
    });

  } catch (e) {
    console.error("News Stream Error:", e);
    return generateFallbackNews(topicString);
  }
};

