import React, { useState, useEffect } from 'react';
import { UserPreferences } from '../types';

interface OnboardingProps {
  onComplete: (prefs: UserPreferences) => void;
}

const Onboarding: React.FC<OnboardingProps> = ({ onComplete }) => {
  const [step, setStep] = useState(1);
  const [isExiting, setIsExiting] = useState(false);
  const [prefs, setPrefs] = useState<UserPreferences>({
    topics: [],
    readingStyle: 'Brief summaries',
    tone: 'Straight facts',
    constraints: {
      noClickbait: true,
      fewerCelebrity: false,
      expertSources: true,
      safeMode: false
    }
  });

  const topicsList = ['AI & Tech', 'Startups', 'Global Markets', 'Policy', 'Geopolitics', 'Climate', 'Culture', 'Science', 'Finance', 'Health'];

  const toggleTopic = (topic: string) => {
    setPrefs(p => ({
      ...p,
      topics: p.topics.includes(topic) ? p.topics.filter(t => t !== topic) : [...p.topics, topic]
    }));
  };

  const handleNext = () => {
     setStep(s => s + 1);
  };

  const handleComplete = () => {
    setIsExiting(true);
    setTimeout(() => {
        onComplete(prefs);
    }, 800);
  };

  useEffect(() => {
    if (step === 4) {
      const timer = setTimeout(handleComplete, 2500);
      return () => clearTimeout(timer);
    }
  }, [step]);

  return (
    <div className={`fixed inset-0 z-[100] flex flex-col items-center justify-center overflow-hidden transition-opacity duration-700 ${isExiting ? 'opacity-0' : 'opacity-100'}`}>

      {/* 1. Main Floating Card (Light Glass) */}
      <div className="relative z-10 w-full max-w-[360px] md:max-w-md mx-6">

        {/* Card Body */}
        <div className="glass-card rounded-[32px] md:rounded-[40px] p-6 md:p-10 transition-all duration-500 animate-fade-in-up shadow-2xl ring-1 ring-white/50">

            {/* Step 1: Welcome / "Get Started" */}
            {step === 1 && (
                <div className="flex flex-col items-center text-center">
                    <div className="w-16 h-16 md:w-20 md:h-20 mb-6 md:mb-8 flex items-center justify-center bg-white shadow-lg text-[#831843] rounded-2xl md:rounded-3xl transform -rotate-3 border border-rose-100">
                         <span className="font-serif-display text-3xl md:text-4xl font-bold">V</span>
                    </div>

                    <h1 className="text-4xl md:text-5xl font-serif-display font-bold text-[#4a044e] mb-3 tracking-tighter drop-shadow-sm">
                        Volv.
                    </h1>
                    <p className="text-[#831843]/70 mb-8 md:mb-10 font-sans text-[13px] leading-relaxed max-w-[240px] mx-auto font-medium">
                        Intelligent news, distilled. <br/> Experience clarity in 9 seconds.
                    </p>

