                    <h2 className="text-lg font-serif-display font-bold text-[#4a044e] mb-2">Curating Feed</h2>
                    <p className="text-[10px] text-[#831843]/60 uppercase tracking-[0.2em] animate-pulse">Designing experience...</p>
                </div>
            )}

        </div>

        {/* Footer Branding */}
        <div className="text-center mt-6">
             <p className="text-[9px] text-[#4a044e]/40 uppercase tracking-[0.2em] font-bold">Powered by Gemini</p>
