            {/* Step 1: Welcome / "Get Started" */}
            {step === 1 && (
                <div className="flex flex-col items-center text-center">
                    <div className="w-14 h-14 md:w-20 md:h-20 mb-5 md:mb-8 flex items-center justify-center bg-white shadow-lg text-[#831843] rounded-xl md:rounded-3xl transform -rotate-3 border border-rose-100">
                         <span className="font-serif-display text-2xl md:text-4xl font-bold">V</span>
                    </div>

                    <h1 className="text-3xl md:text-5xl font-serif-display font-bold text-[#4a044e] mb-2 tracking-tighter drop-shadow-sm">
                        Volv.
                    </h1>
                    <p className="text-[#831843]/70 mb-6 md:mb-10 font-sans text-[11px] md:text-[13px] leading-relaxed max-w-[200px] md:max-w-[240px] mx-auto font-medium">
                        Intelligent news, distilled. <br/> Experience clarity in 9 seconds.
                    </p>

                    <div className="w-full space-y-3 px-1">
                        <button 
                            onClick={handleNext}
                            className="w-full py-3 md:py-3.5 bg-[#831843] text-white rounded-full font-bold text-[10px] md:text-[11px] uppercase tracking-[0.2em] shadow-lg hover:scale-[1.02] transition-transform active:scale-95"
                        >
                            Get Started
                        </button>
                    </div>

                    <p className="mt-5 md:mt-8 text-[9px] text-[#831843]/40 font-semibold tracking-wide">By continuing you agree to our Terms.</p>
                </div>
            )}

            {/* Step 2: Topics Selection */}
            {step === 2 && (
                <div className="flex flex-col h-full">
                    <div className="text-center mb-4 md:mb-8">
                        <h2 className="text-lg md:text-2xl font-serif-display font-bold text-[#4a044e] mb-1">Your Interests</h2>
                        <p className="text-[#831843]/60 text-[10px] md:text-xs font-medium">Select 3 topics to tailor your feed</p>
                    </div>

                    <div className="flex flex-wrap gap-1.5 md:gap-2 justify-center mb-6 md:mb-10">
                        {topicsList.map(t => {
                            const isSelected = prefs.topics.includes(t);
                            return (
                                <button 
                                    key={t}
                                    onClick={() => toggleTopic(t)}
                                    className={`
                                        px-3 py-1.5 md:px-4 md:py-2 rounded-full text-[10px] md:text-[11px] font-bold transition-all duration-300 border uppercase tracking-wide
                                        ${isSelected 
                                            ? 'bg-[#831843] text-white border-[#831843] shadow-md transform scale-105' 
                                            : 'bg-white border-rose-200 text-[#831843]/80 hover:bg-rose-50'}
                                    `}
                                >
                                    {t}
                                </button>
                            );
                        })}
                    </div>

                    <div className="mt-auto px-1">
                         <button 
                            onClick={handleNext}
                            disabled={prefs.topics.length < 3}
                            className="w-full py-3 md:py-3.5 rounded-full font-bold text-[10px] md:text-[11px] uppercase tracking-[0.2em] transition-all disabled:opacity-30 disabled:cursor-not-allowed
                            bg-[#831843] text-white shadow-lg hover:shadow-xl hover:scale-[1.01] active:scale-95"
                        >
                            Continue
                        </button>
                    </div>
                </div>
            )}

            {/* Step 3: Density Preference */}
            {step === 3 && (
                <div>
                     <div className="text-center mb-5 md:mb-8">
                        <h2 className="text-lg md:text-2xl font-serif-display font-bold text-[#4a044e] mb-1">Reading Style</h2>
                        <p className="text-[#831843]/60 text-[10px] md:text-xs font-medium">How much depth do you need?</p>
                    </div>

                    <div className="space-y-2 mb-6 md:mb-10">
                        {['Ultra quick (10s)', 'Brief summaries', 'Deep dives'].map(style => {
                            const val = style.split(' (')[0];
                            const isSelected = prefs.readingStyle === val;
                            return (
                                <button 
                                    key={style}
                                    onClick={() => { setPrefs(p => ({...p, readingStyle: val as any})); handleNext(); }}
                                    className={`
                                        w-full p-3 md:p-4 flex justify-between items-center text-left transition-all border rounded-[16px] md:rounded-[20px]
                                        ${isSelected 
                                            ? 'bg-rose-100 border-rose-200 text-[#4a044e] shadow-sm' 
                                            : 'bg-white border-rose-100 text-[#831843]/60 hover:bg-rose-50'}
                                    `}
                                >
                                    <span className={`font-bold text-xs md:text-sm tracking-tight`}>{style}</span>
                                    <div className={`
                                        w-3.5 h-3.5 md:w-4 md:h-4 rounded-full border flex items-center justify-center transition-colors
                                        ${isSelected ? 'border-[#831843] bg-[#831843]' : 'border-rose-300'}
                                    `}>
                                        {isSelected && <div className="w-1 md:w-1.5 h-1 md:h-1.5 bg-white rounded-full" />}
                                    </div>
                                </button>
                            );
                        })}
                    </div>
                </div>
            )}

            {/* Step 4: Personalization Spinner */}
            {step === 4 && (
                <div className="flex flex-col items-center justify-center py-6 md:py-8">
                    <div className="relative w-10 h-10 md:w-14 md:h-14 mb-4 md:mb-6">
                        <svg className="animate-spin w-full h-full text-[#be185d]" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="3"></circle>
                            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                        </svg>
                    </div>

                    <h2 className="text-base md:text-lg font-serif-display font-bold text-[#4a044e] mb-1">Curating Feed</h2>
                    <p className="text-[9px] md:text-[10px] text-[#831843]/60 uppercase tracking-[0.2em] animate-pulse">Designing experience...</p>
                </div>
            )}

        </div>

        {/* Footer Branding */}
        <div className="text-center mt-6">
             <p className="text-[9px] text-[#4a044e]/40 uppercase tracking-[0.2em] font-bold">Powered by Gemini</p>
        </div>

      </div>

      <style>{`
        @keyframes fade-in-up {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-fade-in-up {
          animation: fade-in-up 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards;
        }
