import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Byte } from '../types';

interface NewsSlideProps {
  byte: Byte;
  onLike: (id: string) => void;
  onSave: (id: string) => void;
}

const NewsSlide: React.FC<NewsSlideProps> = ({ byte, onLike, onSave }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [inView, setInView] = useState(false);
  const [showHeart, setShowHeart] = useState(false);
  const slideRef = useRef<HTMLDivElement>(null);
  const lastTapRef = useRef<number>(0);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        setInView(entry.isIntersecting);
      },
      { threshold: 0.45 }
    );

    if (slideRef.current) observer.observe(slideRef.current);
    return () => observer.disconnect();
  }, []);

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (navigator.share) {
      try {
        await navigator.share({
          title: byte.title,
          text: byte.abstract,
          url: byte.sourceUrl || window.location.href,
        });
      } catch (err) { console.log('Error sharing:', err); }
    } else {
      navigator.clipboard.writeText(byte.sourceUrl || window.location.href);
      alert('Link copied to clipboard!');
    }
  };

  const handleFullStory = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (byte.sourceUrl) {
      const win = window.open(byte.sourceUrl, '_blank', 'noopener,noreferrer');
      if (win) win.focus();
    } else {
      alert("Source link currently unavailable.");
    }
  };

  // Double Tap Logic
  const handleContainerClick = (e: React.MouseEvent) => {
    const now = Date.now();
    const DOUBLE_TAP_DELAY = 300;

    if (now - lastTapRef.current < DOUBLE_TAP_DELAY) {
      // Double Tap Detected
      if (!byte.isLiked) {
        onLike(byte.id);
      }
      setShowHeart(true);
      setTimeout(() => setShowHeart(false), 1000);
    } else {
      // Single Tap - could toggle expand if clicked on text, but here we let it bubble or handle separately
    }
    lastTapRef.current = now;
  };

  const toggleExpand = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsExpanded(!isExpanded);
  };

  return (
    <div 
        ref={slideRef}
        className="snap-start relative h-[100dvh] w-full bg-transparent overflow-hidden flex flex-col justify-end perspective-1000"
        onClick={handleContainerClick}
    >
      {/* 
         Card Container 
         - Mobile: minimal margins for immersive feel
         - Desktop: larger margins for card feel
      */}
      <div className="absolute inset-0 z-0 overflow-hidden rounded-[20px] md:rounded-[40px] m-1.5 md:m-4 shadow-2xl bg-black">
         <img 
            src={byte.fileUrl} 
            alt={byte.title} 
            className={`
                w-full h-full object-cover transition-transform duration-[10s] ease-out will-change-transform
                ${inView ? 'scale-110 opacity-100' : 'scale-100 opacity-90'}
            `}
            loading="lazy"
         />

         {/* Immersive Gradients */}
         {/* Top gradient for Navbar visibility */}
         <div className="absolute inset-x-0 top-0 h-32 bg-gradient-to-b from-black/40 to-transparent pointer-events-none"></div>

         {/* Bottom gradient for text readability */}
         <div className="absolute inset-0 bg-gradient-to-b from-transparent via-black/10 to-black/90 pointer-events-none"></div>
      </div>

      {/* Big Heart Animation Overlay */}
      {showHeart && (
        <div className="absolute inset-0 z-30 flex items-center justify-center pointer-events-none animate-popup">
           <svg className="w-24 h-24 text-white/90 drop-shadow-2xl fill-white" viewBox="0 0 24 24">
             <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/>
           </svg>
        </div>
      )}

      {/* Content Layer */}
      <div className="relative z-10 w-full px-5 md:px-8 pb-24 md:pb-28 flex items-end justify-between gap-4">

         {/* Text Content */}
         <div className={`flex-1 min-w-0 transition-all duration-700 delay-75 ease-out transform ${inView ? 'translate-y-0 opacity-100' : 'translate-y-8 opacity-0'}`}>

             {/* Volv Badge - Minimalist */}
             <div className="inline-flex items-center gap-2 mb-3 opacity-90">
                <div className="w-1.5 h-1.5 rounded-full bg-rose-500 animate-pulse"></div>
                <span className="text-[10px] font-bold text-white/90 uppercase tracking-[0.2em] drop-shadow-md">Volv Wire</span>
             </div>

             {/* Text Block - Removed Glass Box for cleaner look */}
             <div 
                className="group cursor-pointer"
                onClick={toggleExpand}
             >
                 <div className="flex flex-col gap-2">
                     <h2 className="font-serif-display text-2xl md:text-4xl font-bold text-white leading-[1.1] tracking-tight drop-shadow-lg line-clamp-3">
                        {byte.title}
                     </h2>

                     <div className={`transition-all duration-500 ease-[cubic-bezier(0.25,0.1,0.25,1)] overflow-hidden ${isExpanded ? 'max-h-80 opacity-100' : 'max-h-[3.8rem] opacity-90'}`}>
                        <p className="font-sans text-[13px] md:text-[15px] leading-relaxed text-white/90 font-medium drop-shadow-md">
                            {byte.abstract}
                        </p>
                     </div>

                     <div className="flex items-center gap-3 pt-3">
                        {/* Publisher Info */}
                        <div className="flex items-center gap-2 truncate opacity-80">
                            {byte.sourceUrl && (
                                <img src={`https://www.google.com/s2/favicons?domain=${new URL(byte.sourceUrl).hostname}&sz=32`} className="w-4 h-4 rounded-full border border-white/30" alt="" />
                            )}
                             <span className="text-[10px] font-bold text-white uppercase tracking-widest truncate">{byte.publisher}</span>
                             <span className="text-[10px] text-white/50">•</span>
                             <span className="text-[10px] text-white/70">{byte.readTime}</span>
                        </div>

                        {/* Read More Button (Shows on Expand) */}
                        <div className={`transition-all duration-300 ${isExpanded ? 'opacity-100 w-auto translate-x-0' : 'opacity-0 w-0 -translate-x-2 overflow-hidden'}`}>
                             <button 
                                onClick={handleFullStory}
                                className="px-4 py-1.5 bg-white/20 hover:bg-white/30 backdrop-blur-md text-white border border-white/20 rounded-full text-[9px] font-bold uppercase tracking-widest transition-all flex items-center gap-1.5 whitespace-nowrap"
                             >
                                Read
                                <svg className="w-2.5 h-2.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M14 5l7 7m0 0l-7 7m7-7H3"/></svg>
                             </button>
                        </div>
                     </div>
                 </div>
             </div>
         </div>

         {/* Sidebar Actions - Minimalist White Icons */}
         <div className="flex flex-col items-center gap-6 mb-2 shrink-0 w-12 pb-2">

             {/* Like Button */}
             <div className={`flex flex-col items-center gap-1 transition-all duration-500 delay-[150ms] ${inView ? 'translate-x-0 opacity-100' : 'translate-x-8 opacity-0'}`}>
                 <button onClick={(e) => { e.stopPropagation(); onLike(byte.id); }} className="group relative">
                     <div className="absolute inset-0 bg-white/10 blur-md rounded-full scale-0 group-active:scale-150 transition-transform"></div>
                     <svg className={`w-8 h-8 drop-shadow-lg transition-all duration-300 ${byte.isLiked ? 'fill-rose-500 text-rose-500 scale-110' : 'fill-transparent text-white stroke-[1.5px] hover:scale-110'}`} viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" />
                     </svg>
                 </button>
                 <span className="text-white text-[10px] font-bold drop-shadow-md tracking-wider">{byte.likes}</span>
             </div>

             {/* Comment Button (Visual Only) */}
             <div className={`flex flex-col items-center gap-1 transition-all duration-500 delay-[250ms] ${inView ? 'translate-x-0 opacity-100' : 'translate-x-8 opacity-0'}`}>
                 <button className="group" onClick={(e) => e.stopPropagation()}>
                     <svg className="w-7 h-7 text-white drop-shadow-lg stroke-[1.5px] hover:scale-110 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" />
                     </svg>
                 </button>
                 <span className="text-white text-[10px] font-bold drop-shadow-md tracking-wider">{byte.comments}</span>
             </div>

             {/* Save Button */}
             <div className={`flex flex-col items-center gap-1 transition-all duration-500 delay-[350ms] ${inView ? 'translate-x-0 opacity-100' : 'translate-x-8 opacity-0'}`}>
                 <button onClick={(e) => { e.stopPropagation(); onSave(byte.id); }} className="group">
                    <svg className={`w-7 h-7 drop-shadow-lg transition-all duration-300 stroke-[1.5px] ${byte.isSaved ? 'fill-white text-white' : 'fill-transparent text-white hover:scale-110'}`} stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" />
                    </svg>
                 </button>
             </div>

             {/* Share Button */}
             <div className={`flex flex-col items-center gap-1 transition-all duration-500 delay-[450ms] ${inView ? 'translate-x-0 opacity-100' : 'translate-x-8 opacity-0'}`}>
                 <button onClick={handleShare} className="group">
                    <svg className="w-7 h-7 text-white drop-shadow-lg stroke-[1.5px] hover:scale-110 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
                    </svg>
                 </button>
             </div>
         </div>
      </div>

      <style>{`
        .perspective-1000 { perspective: 1000px; }
