import React, { useState, useRef, useEffect } from 'react';
import { Byte } from '../types';

interface NewsSlideProps {
  byte: Byte;
  onLike: (id: string) => void;
  onSave: (id: string) => void;
}

const NewsSlide: React.FC<NewsSlideProps> = ({ byte, onLike, onSave }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [inView, setInView] = useState(false);
  const [showHeart, setShowHeart] = useState(false);
  const slideRef = useRef<HTMLDivElement>(null);
  const lastTap = useRef<number>(0);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        setInView(entry.isIntersecting);
      },
      { threshold: 0.5 }
    );

    if (slideRef.current) observer.observe(slideRef.current);
    return () => observer.disconnect();
  }, []);

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (navigator.share) {
      try {
        await navigator.share({
          title: byte.title,
          text: byte.abstract,
          url: byte.sourceUrl || window.location.href,
        });
      } catch (err) { console.log('Error sharing:', err); }
    } else {
      navigator.clipboard.writeText(byte.sourceUrl || window.location.href);
      alert('Link copied to clipboard!');
    }
  };

  const handleFullStory = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (byte.sourceUrl) {
      const win = window.open(byte.sourceUrl, '_blank', 'noopener,noreferrer');
      if (win) win.focus();
    } else {
      alert("Source link currently unavailable.");
    }
  };

  const handleDoubleTap = (e: React.MouseEvent) => {
    const now = Date.now();
    const DOUBLE_TAP_DELAY = 300;
    if (now - lastTap.current < DOUBLE_TAP_DELAY) {
        if (!byte.isLiked) onLike(byte.id);
        setShowHeart(true);
        setTimeout(() => setShowHeart(false), 1000);
    }
    lastTap.current = now;
  };

  return (
    <div 
        ref={slideRef}
        className="snap-start relative h-[100dvh] w-full flex items-center justify-center p-0 md:p-4 perspective-1000"
        onClick={handleDoubleTap}
    >
      {/* Immersive Card Container */}
      <div className={`
        relative w-full h-full md:h-[95%] md:w-[480px] 
        bg-black overflow-hidden shadow-2xl transition-all duration-700
        ${inView ? 'scale-100 opacity-100' : 'scale-[0.98] opacity-90'}
        md:rounded-[40px] rounded-none border border-white/10
      `}>

         {/* Background Image */}
         <img 
            src={byte.fileUrl} 
            alt={byte.title} 
            className="absolute inset-0 w-full h-full object-cover opacity-90"
            loading="lazy"
         />

         {/* Cinematic Gradients for Legibility */}
         <div className="absolute inset-0 bg-gradient-to-b from-black/60 via-transparent to-transparent h-40 pointer-events-none" />
         <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/40 to-transparent pointer-events-none" />

         {/* Heart Animation for Double Tap */}
         {showHeart && (
             <div className="absolute inset-0 flex items-center justify-center pointer-events-none z-50">
                 <svg className="w-28 h-28 text-white/90 drop-shadow-2xl fill-current animate-ping-short" viewBox="0 0 24 24">
                     <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/>
                 </svg>
             </div>
         )}

         {/* Main Interface Layer */}
         <div className="absolute inset-0 flex flex-col justify-end p-5 pb-24 md:pb-28">

             {/* Floating Right Sidebar Actions */}
             <div className="absolute right-3 bottom-24 flex flex-col items-center gap-6 z-20">

                 {/* Like */}
                 <div className="flex flex-col items-center gap-1">
                    <button 
                        onClick={(e) => { e.stopPropagation(); onLike(byte.id); }}
                        className="group relative p-3"
                    >
                        <div className="absolute inset-0 bg-black/20 blur-lg rounded-full" />
                        <svg className={`w-8 h-8 drop-shadow-xl transition-all duration-300 ${byte.isLiked ? 'text-rose-500 fill-rose-500 scale-110' : 'text-white hover:scale-110'}`} viewBox="0 0 24 24" stroke="currentColor" strokeWidth="1.5">
