export const sendMessageToGemini = async (history: {role: string, text: string}[], newMessage: string): Promise<string> => {
  try {
    if (!process.env.API_KEY) return "Missing API Key.";
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...history.map(h => ({
          role: h.role === 'model' ? 'model' : 'user',
          parts: [{ text: h.text }]
        })),
        { role: 'user', parts: [{ text: newMessage }] }
      ],
      config: { systemInstruction: getSystemInstruction() }
    });
    return response.text || "No response.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Service unavailable.";
  }
};

const generateFallbackNews = (topicString: string): Byte[] => {
    return [
        {
            id: `fallback-${Date.now()}`,
            title: `Latest Updates: ${topicString.split(',')[0]}`,
            publisher: "Bytes Wire",
            authors: ["AI Curator"],
            abstract: "We are currently syncing with global sources to bring you the most accurate real-time coverage.",
            category: "World",
            readTime: "1 min",
            fileUrl: getCategoryImageUrl("World"),
            likes: 150,
            comments: 5,
            publicationDate: "Now",
            isLiked: false,
            isSaved: false,
            sourceUrl: `https://www.google.com/search?q=${encodeURIComponent(topicString)}&tbm=nws`
        }
    ];
};

/**
 * Intelligent Deep-Link Matcher
 * Analyzes search results to find the specific article URL that matches the generated headline.
 * STRICT MODE: Only returns a URL if it matches the content, otherwise returns null.
 */
const findBestVerifiedLink = (headline: string, publisher: string, groundingChunks: any[]) => {
  if (!groundingChunks || groundingChunks.length === 0) return null;

  const hNorm = headline.toLowerCase().replace(/[^\w\s]/g, '');
  const pNorm = publisher.toLowerCase().replace(/[^\w\s]/g, '');
  const hWords = hNorm.split(/\s+/).filter(w => w.length > 3);

  const scoredResults = groundingChunks
    .filter(chunk => chunk.web && chunk.web.uri)
    .map(chunk => {
        const cTitle = (chunk.web.title || "").toLowerCase();
        const cUri = chunk.web.uri.toLowerCase();
        let score = 0;

        // 1. Semantic Title Match (Headline words present in Source Title)
        let matchCount = 0;
        hWords.forEach(w => {
            if (cTitle.includes(w)) matchCount++;
        });
        if (hWords.length > 0) {
            score += (matchCount / hWords.length) * 100;
        }

        // 2. Publisher Identity Match
        if (cTitle.includes(pNorm) || cUri.includes(pNorm.replace(/\s+/g, ''))) {
            score += 40;
        }

        // 3. Deep Link Structural Validation
        try {
            const url = new URL(chunk.web.uri);
            const path = url.pathname;
            // Reward paths that look like articles (e.g. /2024/05/title, /article/123)
            // Penalize root paths (e.g. /, /index.html)
            if (path.length > 1 && path.split('/').length > 2) {
                score += 30;
            }
            if (path === '/' || path === '' || path === '/index.html' || path.includes('login') || path.includes('subscribe')) {
                score -= 200; // Nuclear penalty for non-content pages
            }
        } catch {
            score -= 200;
        }

        return { uri: chunk.web.uri, score };
    })
    .sort((a, b) => b.score - a.score);

  // High threshold to ensure we don't return garbage links. 
  // It's better to fallback to a search page than to send a user to a random wrong article.
  return scoredResults[0] && scoredResults[0].score > 50 ? scoredResults[0].uri : null;
};

export const fetchRealTimeNews = async (topics: string[]): Promise<Byte[]> => {
  if (!process.env.API_KEY) return [];

  const topicString = topics.length > 0 ? topics.join(', ') : 'Global Breaking News';

  // Prompt optimized for high throughput (6 items) and high accuracy
  const prompt = `
    Find 6 distinct, high-impact breaking news stories related to: ${topicString}.

    CRITICAL REQUIREMENTS:
    1. Events must be from the last 24 hours.
    2. Verify facts against multiple sources.
    3. Avoid duplicate stories.
    4. PRIORITIZE FACTUAL ACCURACY over sensationalism.

    Output strictly as a valid JSON array:
    [
      {
        "title": "Concise Headline",
        "publisher": "Source Name",
        "abstract": "Compelling summary (max 35 words)",
        "category": "Category Name"
      }
    ]
  `;

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: { 
        tools: [{ googleSearch: {} }],
      },
    });

    let text = response.text || "[]";
    const jsonMatch = text.match(/\[[\s\S]*\]/);
    if (jsonMatch) text = jsonMatch[0];

    let rawData;
    try {
        rawData = JSON.parse(text);
    } catch (e) {
        return generateFallbackNews(topicString);
    }

    if (!Array.isArray(rawData)) return generateFallbackNews(topicString);

    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

    return rawData.map((item: any) => {
      const cat = item.category || "World";

      // 1. Try to find a verified deep link from the actual search metadata
      // This is the ONLY way we accept a direct link. We do not trust the model's hallucinated URLs.
      let finalUrl = findBestVerifiedLink(item.title, item.publisher, groundingChunks);

      // 2. Fallback: Create a specific Google News search link
      // This guarantees the user never hits a 404 page. It sends them to a live search for that specific story.
      if (!finalUrl) {
          finalUrl = `https://www.google.com/search?q=${encodeURIComponent(item.title + " " + item.publisher)}&tbm=nws`;
      }

      return {
        id: `live-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
        title: item.title || "News Update",
        publisher: item.publisher || "Global Wire",
        authors: ["AI Curator"],
        abstract: item.abstract || "Full details available at the source.",
        category: cat,
        readTime: "1 min read",
        fileUrl: getCategoryImageUrl(cat),
        likes: Math.floor(Math.random() * 500 + 100),
        comments: Math.floor(Math.random() * 50),
        isLiked: false,
        isSaved: false,
        publicationDate: "JUST NOW",
        sourceUrl: finalUrl
      } as Byte;
    });

  } catch (e) {
    console.error("Gemini Fetch Error:", e);
    return generateFallbackNews(topicString);
  }
};

import React, { useState, useEffect, useMemo, useRef, useCallback } from 'react';
import Navbar from './components/Navbar';
import NewsSlide from './components/NewsSlide';
import CurateDrawer from './components/CurateDrawer';
import Onboarding from './components/Onboarding';
import InteractiveBackground from './components/InteractiveBackground';
import { PAPERS } from './constants';
import { fetchRealTimeNews } from './services/geminiService';
import { Byte, UserPreferences } from './types';

const App: React.FC = () => {
  const [news, setNews] = useState<Byte[]>([]);
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [showOnboarding, setShowOnboarding] = useState<boolean>(true);
  const [selectedTopics, setSelectedTopics] = useState<string[]>(['US News', 'World', 'AI & Tech', 'Business', 'Science', 'Finance', 'Culture']);
  const [searchTerm, setSearchTerm] = useState('');

  // Streaming State
  const [streamStatus, setStreamStatus] = useState<string>(''); 
  const [isStreaming, setIsStreaming] = useState(false);

  const feedRef = useRef<HTMLDivElement>(null);
  const initialized = useRef(false);

  // Optimized for Speed: 2 Large Parallel Batches
  const BATCHES = useMemo(() => [
    ['Breaking News', 'World Politics', 'US National', 'Global Economy', 'Finance', 'Business Markets'],
    ['Artificial Intelligence', 'Technology', 'Science', 'Health', 'Internet Culture', 'Entertainment', 'Sports']
  ], []);

  const startNewsStream = useCallback(async () => {
    if (!process.env.API_KEY || isStreaming) return;

    setIsStreaming(true);
    setStreamStatus('Syncing global wire...');

    // Fire all batches in parallel for maximum throughput
    const fetchPromises = BATCHES.map(async (batchTopics) => {
        try {
            const newBytes = await fetchRealTimeNews(batchTopics);
            setNews(prev => {
                const existingIds = new Set(prev.map(p => p.id));
                const uniqueNew = newBytes.filter(b => !existingIds.has(b.id));
                // Interleave new items or just append? Appending keeps the "feed" growing naturally.
                // We shuffle slightly to mix the parallel results visually if they arrive close together.
                return [...prev, ...uniqueNew];
            });
        } catch (error) {
            console.error(`Batch failed`, error);
        }
    });

    await Promise.all(fetchPromises);

    setStreamStatus('');
    setIsStreaming(false);
  }, [BATCHES, isStreaming]);

  useEffect(() => {
    if (initialized.current) return;
    initialized.current = true;

    // Force Onboarding to show by not checking localStorage

    const storedPrefs = localStorage.getItem('bytes_prefs');
    if (storedPrefs) {
      const prefs = JSON.parse(storedPrefs) as UserPreferences;
      if (prefs.topics?.length > 0) setSelectedTopics(prefs.topics);
    }

    setNews(PAPERS.map(p => ({ ...p, isLiked: false, isSaved: false })));

    // Removed auto-start of stream here, it triggers after onboarding completes
  }, [startNewsStream]);

  const handleRefresh = () => {
    // Keep existing items until new ones arrive to prevent flash, or clear if preferred.
    // Let's clear to show fresh reload effect.
    setNews(PAPERS.map(p => ({ ...p, isLiked: false, isSaved: false })));
    feedRef.current?.scrollTo({ top: 0, behavior: 'smooth' });
    startNewsStream();
  };

  const handleOnboardingComplete = (prefs: UserPreferences) => {
    setShowOnboarding(false);
    setSelectedTopics(prefs.topics);
    localStorage.setItem('bytes_onboarded', 'true');
    localStorage.setItem('bytes_prefs', JSON.stringify(prefs));
    startNewsStream();
  };

  const handleLike = (id: string) => {
    setNews(prev => prev.map(item => 
      item.id === id ? { ...item, isLiked: !item.isLiked, likes: item.isLiked ? item.likes - 1 : item.likes + 1 } : item
    ));
  };

  const handleSave = (id: string) => {
    setNews(prev => prev.map(item => 
      item.id === id ? { ...item, isSaved: !item.isSaved } : item
    ));
  };

  const toggleTopic = (topic: string) => {
    setSelectedTopics(prev => 
      prev.includes(topic) ? prev.filter(t => t !== topic) : [...prev, topic]
    );
  };

  const filteredNews = useMemo(() => {
    return news.filter(byte => {
      if (byte.id.startsWith('live-') || byte.id.startsWith('fallback-')) return true; 
      const matchesTopic = selectedTopics.includes(byte.category) || selectedTopics.length === 0;
      const matchesSearch = searchTerm === '' || 
        byte.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
        byte.abstract.toLowerCase().includes(searchTerm.toLowerCase());
      return matchesTopic && matchesSearch;
    });
  }, [news, selectedTopics, searchTerm]);

  return (
    <div className="relative h-[100dvh] w-full overflow-hidden text-[#4a044e]">

      {/* BACKGROUND LAYER */}
      <InteractiveBackground />

      {showOnboarding ? (
        <Onboarding onComplete={handleOnboardingComplete} />
      ) : (
        <>
          <div className="relative z-10 w-full h-full">
            <Navbar 
                onProfileClick={() => setIsDrawerOpen(true)}
                onSearchClick={() => setIsDrawerOpen(true)}
                onNotifyClick={() => {}}
                onLiveClick={handleRefresh}
                isLiveLoading={isStreaming}
            />

            {/* FEED CONTAINER */}
            <div 
                ref={feedRef}
                className="h-[100dvh] w-full overflow-y-scroll snap-y snap-mandatory scroll-smooth no-scrollbar"
            >
                {filteredNews.length > 0 ? (
                  <>
                    {filteredNews.map((byte, index) => (
                        <NewsSlide 
                          key={`${byte.id}-${index}`} 
                          byte={byte} 
                          onLike={handleLike} 
                          onSave={handleSave} 
                        />
                    ))}
                  </>
                ) : (
                    <div className="h-[100dvh] w-full flex flex-col items-center justify-center text-center p-8 snap-center">
                        <div className="glass-panel p-8 rounded-[32px] max-w-sm w-full mx-auto shadow-xl">
                            <h3 className="text-3xl font-serif-display font-bold text-[#831843] mb-3">Quiet today.</h3>
                            <p className="text-[#831843]/60 text-sm mb-8">Try adjusting your interests.</p>
                            <button 
                              onClick={() => setIsDrawerOpen(true)}
                              className="px-8 py-4 rounded-full bg-[#831843] text-white font-bold text-xs uppercase tracking-widest shadow-lg hover:scale-105 transition-transform"
                            >
                              Curate Feed
                            </button>
                        </div>
                    </div>
                )}

                {/* Status Indicator */}
                <div className="h-[20dvh] w-full flex flex-col items-center justify-center gap-3 snap-center text-[#831843]/50 pb-20">
                    {isStreaming ? (
                        <>
                             <div className="flex items-center gap-2">
                                <span className="w-2 h-2 bg-[#be185d] rounded-full animate-pulse"></span>
                                <span className="text-[10px] font-bold uppercase tracking-[0.2em]">Syncing global wire</span>
                            </div>
                            <div className="w-24 h-1 bg-[#831843]/10 rounded-full overflow-hidden">
                                <div className="h-full bg-[#be185d] animate-progress-indeterminate"></div>
                            </div>
                        </>
                    ) : (
                        <span className="text-[10px] font-bold uppercase tracking-[0.2em]">
                             You're all caught up
                        </span>
                    )}
                </div>

            </div>
          </div>

          <CurateDrawer 
            isOpen={isDrawerOpen} 
            onClose={() => setIsDrawerOpen(false)}
            selectedTopics={selectedTopics}
            onTopicToggle={toggleTopic}
            onSearch={setSearchTerm}
          />
        </>
      )}

      <style>{`
        @keyframes progress-indeterminate {
            0% { width: 0%; margin-left: 0%; }
            50% { width: 50%; margin-left: 25%; }
            100% { width: 0%; margin-left: 100%; }
        }
        .animate-progress-indeterminate {
            animation: progress-indeterminate 1.5s infinite ease-in-out;
        }
      `}</style>
    </div>
  );
};

export default App;

