                    </div>

                    <div className="flex flex-wrap gap-2 justify-center mb-8">
                        {topicsList.map(t => {
                            const isSelected = prefs.topics.includes(t);
                            return (
                                <button 
                                    key={t}
                                    onClick={() => toggleTopic(t)}
                                    className={`
