            {/* Step 2: Name Input */}
            {step === 2 && (
                <div className="flex flex-col h-full my-auto">
                    <div className="text-center mb-8">
                         <h2 className="text-xl md:text-2xl font-serif-display font-bold text-[#4a044e] mb-2">First, an introduction.</h2>
