import React, { useState, useEffect, useMemo, useRef, useCallback } from 'react';
import Navbar from './components/Navbar';
import NewsSlide from './components/NewsSlide';
import CurateDrawer from './components/CurateDrawer';
import Onboarding from './components/Onboarding';
import InteractiveBackground from './components/InteractiveBackground';
import { PAPERS } from './constants';
import { fetchRealTimeNews } from './services/geminiService';
import { Byte, UserPreferences } from './types';

const App: React.FC = () => {
  // Use ordered buckets to ensure Batch 0 (Breaking) is always first, even if it loads last
  const [newsBuckets, setNewsBuckets] = useState<Record<number, Byte[]>>({});
  const nextBatchIndex = useRef(0);

  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [showOnboarding, setShowOnboarding] = useState<boolean>(true);
  const [selectedTopics, setSelectedTopics] = useState<string[]>(['US News', 'World', 'AI & Tech', 'Business', 'Science', 'Finance', 'Culture']);
  const [searchTerm, setSearchTerm] = useState('');
  const [userName, setUserName] = useState('');

  // Streaming State
  const [streamStatus, setStreamStatus] = useState<string>(''); 
  const [isStreaming, setIsStreaming] = useState(false);

  const feedRef = useRef<HTMLDivElement>(null);
  const loadMoreRef = useRef<HTMLDivElement>(null);
  const initialized = useRef(false);

  // Flatten buckets into a single feed for rendering
  const news = useMemo(() => {
    return Object.keys(newsBuckets)
      .map(Number)
      .sort((a, b) => a - b) // Ensure strictly ascending order (0, 1, 2...)
      .flatMap(key => newsBuckets[key]);
  }, [newsBuckets]);

  // Dynamic Batch Generation based on User Topics
  const getDynamicBatches = useCallback(() => {
    if (selectedTopics.length <= 3) {
      return [
        [...selectedTopics, 'Breaking News'],
        ['Global Economy', 'World Politics'],
        ['Technology', 'Science'],
        ['Culture', 'Entertainment'],
        ['Sports', 'Health']
      ];
    }
    const chunks: string[][] = [];
    const chunkSize = Math.ceil(selectedTopics.length / 5);
    for (let i = 0; i < selectedTopics.length; i += chunkSize) {
        chunks.push(selectedTopics.slice(i, i + chunkSize));
    }
    while (chunks.length < 5) {
        chunks.push(['Breaking News', 'Trending']);
    }
    return chunks.slice(0, 5); 
  }, [selectedTopics]);

  const startNewsStream = useCallback(async () => {
    if (!process.env.API_KEY || isStreaming) return;

    setIsStreaming(true);
    setStreamStatus(userName ? `Curating for ${userName}...` : 'Initializing velocity wire...');

    // Reset buckets and indices
    setNewsBuckets({}); 
    nextBatchIndex.current = 5; // Reserve 0-4 for initial batches

    // Force scroll to absolute top immediately
    feedRef.current?.scrollTo({ top: 0, behavior: 'instant' });

    const batches = getDynamicBatches();

    const fetchPromises = batches.map(async (batchTopics, index) => {
        try {
            await new Promise(r => setTimeout(r, index * 100)); 
            const newBytes = await fetchRealTimeNews(batchTopics);

            setNewsBuckets(prev => {
                // Ensure unique IDs across all buckets to prevent key collisions
                // though fetchRealTimeNews generates unique IDs, extra safety is good
                return {
                    ...prev,
                    [index]: newBytes
                };
            });
        } catch (error) {
            console.error(`Batch ${index} failed`, error);
        }
    });

    await Promise.all(fetchPromises);
    setStreamStatus('');
    setIsStreaming(false);
  }, [getDynamicBatches, isStreaming, userName]);

  // Infinite Scroll Loader
  const handleLoadMore = useCallback(async () => {
      if (isStreaming) return;

      setIsStreaming(true);

      // Determine next indices
      const idx1 = nextBatchIndex.current++;
      const idx2 = nextBatchIndex.current++;

      const allBatches = getDynamicBatches();
      const randomBatch1 = allBatches[Math.floor(Math.random() * allBatches.length)];
      const randomBatch2 = allBatches[Math.floor(Math.random() * allBatches.length)];

      try {
          const [res1, res2] = await Promise.all([
              fetchRealTimeNews(randomBatch1),
              fetchRealTimeNews(randomBatch2)
          ]);

          setNewsBuckets(prev => ({
              ...prev,
              [idx1]: res1,
              [idx2]: res2
          }));

      } catch (err) {
          console.error("Load more failed", err);
      } finally {
          setIsStreaming(false);
      }
  }, [isStreaming, getDynamicBatches]);

  // Scroll Observer for Infinite Load
  useEffect(() => {
      const observer = new IntersectionObserver(
          (entries) => {
              if (entries[0].isIntersecting && !isStreaming && news.length > 5) {
                  handleLoadMore();
              }
          },
          { threshold: 0.1, rootMargin: '200px' } 
      );
      if (loadMoreRef.current) observer.observe(loadMoreRef.current);
      return () => observer.disconnect();
  }, [news.length, isStreaming, handleLoadMore]);

  useEffect(() => {
    if (initialized.current) return;
    initialized.current = true;

    const storedPrefs = localStorage.getItem('bytes_prefs');
    if (storedPrefs) {
      const prefs = JSON.parse(storedPrefs) as UserPreferences;
      if (prefs.topics?.length > 0) setSelectedTopics(prefs.topics);
      if (prefs.userName) setUserName(prefs.userName);
      setShowOnboarding(false); 
      setTimeout(() => startNewsStream(), 500);
    } else {
        setShowOnboarding(true);
    }

    // Initial placeholder
    setNewsBuckets({ 0: PAPERS.map(p => ({ ...p, isLiked: false, isSaved: false })) });
  }, []);

  const handleRefresh = () => {
    setNewsBuckets({}); 
    setStreamStatus(userName ? `Rewiring for ${userName}...` : 'Rewiring feed...');
    feedRef.current?.scrollTo({ top: 0, behavior: 'instant' }); 
    startNewsStream();
  };

  const handleOnboardingComplete = (prefs: UserPreferences) => {
    setShowOnboarding(false);
    setSelectedTopics(prefs.topics);
    if (prefs.userName) setUserName(prefs.userName);
    localStorage.setItem('bytes_onboarded', 'true');
    localStorage.setItem('bytes_prefs', JSON.stringify(prefs));
    setTimeout(() => startNewsStream(), 300);
  };

  const updateBucketItem = (id: string, modifier: (item: Byte) => Byte) => {
    setNewsBuckets(prev => {
        const next = { ...prev };
        let found = false;
        // Search through buckets to find and update the item
        for (const key of Object.keys(next)) {
            const numKey = Number(key);
            const originalList = next[numKey];
            const idx = originalList.findIndex(item => item.id === id);

            if (idx !== -1) {
                // Update specific item in specific bucket
                const newList = [...originalList];
                newList[idx] = modifier(newList[idx]);
                next[numKey] = newList;
                found = true;
                break;
            }
        }
        return found ? next : prev;
    });
  };

  const handleLike = (id: string) => {
    updateBucketItem(id, item => ({ 
        ...item, 
        isLiked: !item.isLiked, 
        likes: item.isLiked ? item.likes - 1 : item.likes + 1 
    }));
  };

  const handleSave = (id: string) => {
    updateBucketItem(id, item => ({ ...item, isSaved: !item.isSaved }));
  };

  const toggleTopic = (topic: string) => {
    setSelectedTopics(prev => {
        const newTopics = prev.includes(topic) ? prev.filter(t => t !== topic) : [...prev, topic];
        const prefs = JSON.parse(localStorage.getItem('bytes_prefs') || '{}');
        localStorage.setItem('bytes_prefs', JSON.stringify({...prefs, topics: newTopics}));
        return newTopics;
    });
  };

  const filteredNews = useMemo(() => {
    return news.filter(byte => {
      if (byte.id.startsWith('live-') || byte.id.startsWith('fallback-')) return true; 
      const matchesTopic = selectedTopics.includes(byte.category) || selectedTopics.length === 0;
      const matchesSearch = searchTerm === '' || 
        byte.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
        byte.abstract.toLowerCase().includes(searchTerm.toLowerCase());
      return matchesTopic && matchesSearch;
    });
  }, [news, selectedTopics, searchTerm]);

  return (
    <div className="relative h-[100dvh] w-full overflow-hidden text-[#4a044e] bg-[#fff1f2]">

      {/* BACKGROUND LAYER */}
      <InteractiveBackground />

      {showOnboarding ? (
        <Onboarding onComplete={handleOnboardingComplete} />
      ) : (
        <>
          <div className="relative z-10 w-full h-full">
            <Navbar 
                onProfileClick={() => setIsDrawerOpen(true)}
                onSearchClick={() => setIsDrawerOpen(true)}
                onNotifyClick={() => {}}
                onLiveClick={handleRefresh}
                isLiveLoading={isStreaming}
                userName={userName}
            />

            {/* FEED CONTAINER */}
            <div 
                ref={feedRef}
                className="h-[100dvh] w-full overflow-y-scroll snap-y snap-mandatory no-scrollbar overscroll-none"
                style={{ scrollBehavior: 'auto' }} 
            >
                {filteredNews.length > 0 ? (
                  <>
                    {filteredNews.map((byte, index) => (
                        <NewsSlide 
                          key={`${byte.id}-${index}`} 
                          byte={byte} 
                          onLike={handleLike} 
                          onSave={handleSave} 
                        />
                    ))}
                  </>
                ) : !isStreaming ? (
                    <div className="h-[100dvh] w-full flex flex-col items-center justify-center text-center p-8 snap-center">
                        <div className="glass-panel p-8 rounded-[32px] max-w-sm w-full mx-auto shadow-xl">
                            <h3 className="text-3xl font-serif-display font-bold text-[#831843] mb-3">Quiet today.</h3>
                            <p className="text-[#831843]/60 text-sm mb-8">Try adjusting your interests.</p>
                            <button 
                              onClick={() => setIsDrawerOpen(true)}
                              className="px-8 py-4 rounded-full bg-[#831843] text-white font-bold text-xs uppercase tracking-widest shadow-lg hover:scale-105 transition-transform"
                            >
                              Curate Feed
                            </button>
                        </div>
                    </div>
                ) : null}

                {/* Infinite Scroll & Status Indicator */}
                <div 
                    ref={loadMoreRef}
                    className="h-[20dvh] w-full flex flex-col items-center justify-center gap-3 snap-center text-[#831843]/50 pb-20"
                >
                    {isStreaming ? (
                        <>
                             <div className="flex items-center gap-2">
                                <span className="w-2 h-2 bg-[#be185d] rounded-full animate-pulse"></span>
                                <span className="text-[10px] font-bold uppercase tracking-[0.2em]">Syncing {news.length}...</span>
                            </div>
                            <div className="w-24 h-1 bg-[#831843]/10 rounded-full overflow-hidden">
                                <div className="h-full bg-[#be185d] animate-progress-indeterminate"></div>
                            </div>
                        </>
                    ) : (
                        <span className="text-[10px] font-bold uppercase tracking-[0.2em] opacity-50">
                             Scroll for more
                        </span>
                    )}
                </div>

            </div>
          </div>

          <CurateDrawer 
            isOpen={isDrawerOpen} 
            onClose={() => setIsDrawerOpen(false)}
            selectedTopics={selectedTopics}
            onTopicToggle={toggleTopic}
            onSearch={setSearchTerm}
          />
        </>
      )}

      <style>{`
        @keyframes progress-indeterminate {
            0% { width: 0%; margin-left: 0%; }
            50% { width: 50%; margin-left: 25%; }
            100% { width: 0%; margin-left: 100%; }
        }
        .animate-progress-indeterminate {
            animation: progress-indeterminate 1.5s infinite ease-in-out;
        }
      `}</style>
    </div>
  );
};

