const generateFallbackNews = (topicString: string): Byte[] => {
    // Return a subset of high-quality static papers mixed with generated meta-stories
    return PAPERS.slice(0, 3).map((p, i) => ({
        ...p,
        id: `fallback-${Date.now()}-${i}`,
        title: i === 0 ? `Latest in ${topicString.split(',')[0]}` : p.title,
        publicationDate: "JUST NOW"
    }));
};

const findBestVerifiedLink = (headline: string, publisher: string, groundingChunks: any[]) => {
  if (!groundingChunks || groundingChunks.length === 0) return null;
  const hWords = headline.toLowerCase().replace(/[^\w\s]/g, '').split(/\s+/).filter(w => w.length > 3);
  const scoredResults = groundingChunks
    .filter(chunk => chunk.web && chunk.web.uri)
    .map(chunk => {
        const cTitle = (chunk.web.title || "").toLowerCase();
        let matchCount = 0;
        hWords.forEach(w => { if (cTitle.includes(w)) matchCount++; });
        return { uri: chunk.web.uri, score: (matchCount / Math.max(1, hWords.length)) * 100 };
    })
    .sort((a, b) => b.score - a.score);
  return scoredResults[0] && scoredResults[0].score > 40 ? scoredResults[0].uri : null;
};

export const fetchRealTimeNews = async (topics: string[]): Promise<Byte[]> => {
  const topicString = topics.length > 0 ? topics.join(', ') : 'Breaking News';

  if (!process.env.API_KEY) return generateFallbackNews(topicString);

  const prompt = `Find 5 breaking news stories from the last 24 hours about: ${topicString}. Output strictly as valid JSON array: [{"title": "Headline", "publisher": "Source", "abstract": "Summary (30 words)", "category": "Topic"}]`;

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: { tools: [{ googleSearch: {} }] },
    });

    let text = response.text || "[]";
    const jsonMatch = text.match(/\[[\s\S]*\]/);
    if (jsonMatch) text = jsonMatch[0];

    const rawData = JSON.parse(text);
    if (!Array.isArray(rawData) || rawData.length === 0) return generateFallbackNews(topicString);

    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

    return rawData.map((item: any, i: number) => {
      const cat = item.category || "World";
      let finalUrl = findBestVerifiedLink(item.title, item.publisher, groundingChunks);
      if (!finalUrl) finalUrl = `https://www.google.com/search?q=${encodeURIComponent(item.title)}&tbm=nws`;

      return {
        id: `live-${Date.now()}-${i}`,
        title: item.title,
        publisher: item.publisher,
        authors: ["AI Curator"],
        abstract: item.abstract,
        category: cat,
        readTime: "1 min",
        fileUrl: getCategoryImageUrl(cat),
        likes: Math.floor(Math.random() * 500),
        comments: Math.floor(Math.random() * 20),
        publicationDate: "NOW",
        sourceUrl: finalUrl
      } as Byte;
    });

  } catch (e) {
    console.warn("API Error (likely quota), using fallback.");
    return generateFallbackNews(topicString);
  }
};

import React, { useState, useEffect, useMemo, useRef, useCallback } from 'react';
import Navbar from './components/Navbar';
import NewsSlide from './components/NewsSlide';
import CurateDrawer from './components/CurateDrawer';
import Onboarding from './components/Onboarding';
import InteractiveBackground from './components/InteractiveBackground';
import { PAPERS, DEFAULT_CATEGORIES } from './constants';
import { fetchRealTimeNews } from './services/geminiService';
import { Byte, UserPreferences } from './types';

const App: React.FC = () => {
  const [newsBuckets, setNewsBuckets] = useState<Record<number, Byte[]>>({});
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [showOnboarding, setShowOnboarding] = useState<boolean>(true);
  const [storedPrefs, setStoredPrefs] = useState<UserPreferences | null>(null);
  const [selectedTopics, setSelectedTopics] = useState<string[]>(['US News', 'World', 'AI & Tech', 'Business', 'Science']);
  const [searchTerm, setSearchTerm] = useState('');
  const [userName, setUserName] = useState('');
  const [streamStatus, setStreamStatus] = useState<string>(''); 
  const [isStreaming, setIsStreaming] = useState(false);
  const feedRef = useRef<HTMLDivElement>(null);
  const initialized = useRef(false);

  const news = useMemo(() => {
    return Object.keys(newsBuckets)
      .map(Number)
      .sort((a, b) => a - b) 
      .flatMap(key => newsBuckets[key]);
  }, [newsBuckets]);

  const getDynamicBatches = useCallback(() => {
    const customTopics = selectedTopics.filter(t => !DEFAULT_CATEGORIES.some(c => c.label === t));
    const batch0 = ['Breaking News', ...customTopics.slice(0, 2)];
    const batch1 = selectedTopics.filter(t => !batch0.includes(t)).slice(0, 3);
    return [batch0, batch1, ['Global Trends', 'Innovation']];
  }, [selectedTopics]);

  const startNewsStream = useCallback(async (isRefresh = false) => {
    if (isStreaming) return;
    setIsStreaming(true);
    setStreamStatus('Syncing feed...');
    if (isRefresh) {
        setNewsBuckets({}); 
        if (feedRef.current) feedRef.current.scrollTop = 0;
    }

    const batches = getDynamicBatches();

    // 1. Fetch Batch 0 (Top) FIRST
    try {
        const b0 = await fetchRealTimeNews(batches[0]);
        setNewsBuckets(prev => ({ ...prev, 0: b0 }));
    } catch (e) {
        setNewsBuckets({ 0: PAPERS.slice(0, 4) });
    }

    // 2. Load others in background with stagger to respect quota
    const others = batches.slice(1);
    others.forEach(async (topics, i) => {
        await new Promise(r => setTimeout(r, (i + 1) * 2000));
        const bX = await fetchRealTimeNews(topics);
        setNewsBuckets(prev => ({ ...prev, [i+1]: bX }));
    });

    setStreamStatus('');
    setIsStreaming(false);
  }, [getDynamicBatches, isStreaming]);

  useEffect(() => {
    if (initialized.current) return;
    initialized.current = true;
    const prefsStr = localStorage.getItem('bytes_prefs');
    if (prefsStr) {
      const prefs = JSON.parse(prefsStr);
      setStoredPrefs(prefs);
    }
  }, []);

  const handleOnboardingComplete = (prefs: UserPreferences) => {
    setSelectedTopics(prefs.topics);
    setUserName(prefs.userName || '');
    localStorage.setItem('bytes_prefs', JSON.stringify(prefs));
    setShowOnboarding(false);
    setTimeout(() => startNewsStream(true), 100);
  };

  const handleLike = (id: string) => {
    setNewsBuckets(prev => {
        const next = {...prev};
        Object.keys(next).forEach(k => {
            const numK = Number(k);
            next[numK] = next[numK].map(item => item.id === id ? {...item, isLiked: !item.isLiked, likes: item.isLiked ? item.likes - 1 : item.likes + 1} : item);
        });
        return next;
    });
  };

  const handleSave = (id: string) => {
    setNewsBuckets(prev => {
        const next = {...prev};
        Object.keys(next).forEach(k => {
            const numK = Number(k);
            next[numK] = next[numK].map(item => item.id === id ? {...item, isSaved: !item.isSaved} : item);
        });
        return next;
    });
  };

  const filteredNews = useMemo(() => {
    return news.filter(byte => {
      const matchesSearch = searchTerm === '' || byte.title.toLowerCase().includes(searchTerm.toLowerCase());
      return matchesSearch;
    });
  }, [news, searchTerm]);

  return (
    <div className="relative h-[100dvh] w-full overflow-hidden text-[#4a044e] bg-[#fff1f2]">
      <InteractiveBackground />
      {showOnboarding ? (
        <Onboarding onComplete={handleOnboardingComplete} existingPrefs={storedPrefs} />
      ) : (
        <div className="relative z-10 w-full h-full animate-fade-in">
          <Navbar 
            onProfileClick={() => setIsDrawerOpen(true)} 
            onSearchClick={() => setIsDrawerOpen(true)} 
            onNotifyClick={() => {}} 
            onLiveClick={() => startNewsStream(true)} 
            isLiveLoading={isStreaming} 
            userName={userName} 
          />
          <div ref={feedRef} className="h-[100dvh] w-full overflow-y-scroll snap-y snap-mandatory no-scrollbar">
            {filteredNews.length > 0 ? (
                filteredNews.map((byte, idx) => <NewsSlide key={`${byte.id}-${idx}`} byte={byte} onLike={handleLike} onSave={handleSave} />)
            ) : (
                <div className="h-full flex items-center justify-center p-8 text-center snap-center">
                    <div className="glass-panel p-8 rounded-[40px] shadow-xl">
                        <h3 className="text-2xl font-serif-display font-bold text-[#831843] mb-4">Syncing with sources...</h3>
                        <div className="w-16 h-1 bg-[#831843]/10 rounded-full mx-auto overflow-hidden"><div className="h-full bg-[#831843] animate-progress"></div></div>
                    </div>
                </div>
            )}
            {filteredNews.length > 0 && isStreaming && (
                <div className="h-[20vh] flex items-center justify-center snap-center pb-20 opacity-50"><span className="text-[10px] font-bold uppercase tracking-widest">Syncing more...</span></div>
            )}
          </div>
        </div>
      )}
      <CurateDrawer isOpen={isDrawerOpen} onClose={() => setIsDrawerOpen(false)} selectedTopics={selectedTopics} onTopicToggle={(t) => setSelectedTopics(p => p.includes(t) ? p.filter(x => x !== t) : [...p, t])} onSearch={setSearchTerm} />
      <style>{`
        @keyframes progress { 0% { width: 0%; transform: translateX(-100%); } 100% { width: 100%; transform: translateX(100%); } }
        .animate-progress { animation: progress 1.5s infinite linear; }
        .animate-fade-in { animation: fade-in 0.8s ease-out forwards; }
        @keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
      `}</style>
    </div>
  );
};

export default App;

import { GoogleGenAI } from "@google/genai";
import { PAPERS } from '../constants';
import { Byte } from '../types';

const getCategoryImageUrl = (category: string): string => {
  const map: Record<string, string> = {
    'Business': 'photo-1611974765270-ca12586343bb',
    'Tech': 'photo-1518770660439-4636190af475',
    'Science': 'photo-1507413245164-6160d8298b31',
    'World': 'photo-1521737604893-d14cc237f11d',
    'Finance': 'photo-1611974765270-ca12586343bb',
    'Health': 'photo-1576091160399-112ba8d25d1d',
    'Culture': 'photo-1499750310107-5fef28a66643',
    'Politics': 'photo-1529101091760-61df6be5d187',
  };
  const key = Object.keys(map).find(k => category.includes(k)) || 'World';
  const imgId = map[key] || 'photo-1504711434969-e33886168f5c';
  return `https://images.unsplash.com/${imgId}?auto=format&fit=crop&q=80&w=1200`;
};

const generateFallbackNews = (topicString: string): Byte[] => {
    return PAPERS.slice(0, 3).map((p, i) => ({
        ...p,
        id: `fallback-${Date.now()}-${i}-${Math.random()}`,
        title: i === 0 ? `Latest in ${topicString.split(',')[0]}` : p.title,
        publicationDate: "JUST NOW"
    }));
};

const findBestVerifiedLink = (headline: string, publisher: string, groundingChunks: any[]) => {
  if (!groundingChunks || groundingChunks.length === 0) return null;
  const hWords = headline.toLowerCase().replace(/[^\w\s]/g, '').split(/\s+/).filter(w => w.length > 3);
  const scoredResults = groundingChunks
    .filter(chunk => chunk.web && chunk.web.uri)
    .map(chunk => {
        const cTitle = (chunk.web.title || "").toLowerCase();
        let matchCount = 0;
        hWords.forEach(w => { if (cTitle.includes(w)) matchCount++; });
        return { uri: chunk.web.uri, score: (matchCount / Math.max(1, hWords.length)) * 100 };
    })
    .sort((a, b) => b.score - a.score);
  return scoredResults[0] && scoredResults[0].score > 40 ? scoredResults[0].uri : null;
};

export const fetchRealTimeNews = async (topics: string[]): Promise<Byte[]> => {
  const topicString = topics.length > 0 ? topics.join(', ') : 'Breaking News';

  if (!process.env.API_KEY) return generateFallbackNews(topicString);

  // Added "distinct" and "narrow focus" instructions to prevent repetitive general news
  const prompt = `
    Find 5 HIGHLY SPECIFIC, distinct breaking news stories from the last 24 hours strictly about these topics: ${topicString}. 
    Avoid generic global headlines unless they are directly related to the topics.
    Output strictly as a valid JSON array of objects: 
    [{"title": "Specific Headline", "publisher": "Source Name", "abstract": "30-word summary", "category": "TopicName"}]
  `;

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: { 
        tools: [{ googleSearch: {} }],
        temperature: 0.7 // Slight randomness to avoid repetitive API responses
      },
    });

    let text = response.text || "[]";
    const jsonMatch = text.match(/\[[\s\S]*\]/);
    if (jsonMatch) text = jsonMatch[0];

    const rawData = JSON.parse(text);
    if (!Array.isArray(rawData) || rawData.length === 0) return generateFallbackNews(topicString);

    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

    return rawData.map((item: any, i: number) => {
      const cat = item.category || (topics[0] || "World");
      let finalUrl = findBestVerifiedLink(item.title, item.publisher, groundingChunks);
      if (!finalUrl) finalUrl = `https://www.google.com/search?q=${encodeURIComponent(item.title + " " + item.publisher)}&tbm=nws`;

      // Use a more robust ID based on title hash to help with deduplication
      const titleHash = item.title.substring(0, 10).replace(/\s/g, '_');
      return {
        id: `live-${titleHash}-${Date.now()}-${i}`,
        title: item.title,
        publisher: item.publisher,
        authors: ["AI Curator"],
        abstract: item.abstract,
        category: cat,
        readTime: "1 min",
        fileUrl: getCategoryImageUrl(cat),
        likes: Math.floor(Math.random() * 500),
        comments: Math.floor(Math.random() * 20),
        publicationDate: "NOW",
        sourceUrl: finalUrl
      } as Byte;
    });

  } catch (e) {
    console.warn("API Error (likely quota), using fallback.");
    return generateFallbackNews(topicString);
  }
};

import React, { useState, useEffect, useMemo, useRef, useCallback } from 'react';
import Navbar from './components/Navbar';
import NewsSlide from './components/NewsSlide';
import CurateDrawer from './components/CurateDrawer';
import Onboarding from './components/Onboarding';
import InteractiveBackground from './components/InteractiveBackground';
import { PAPERS, DEFAULT_CATEGORIES } from './constants';
import { fetchRealTimeNews } from './services/geminiService';
import { Byte, UserPreferences } from './types';

const App: React.FC = () => {
  const [newsBuckets, setNewsBuckets] = useState<Record<number, Byte[]>>({});
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [showOnboarding, setShowOnboarding] = useState<boolean>(true);
  const [storedPrefs, setStoredPrefs] = useState<UserPreferences | null>(null);
  const [selectedTopics, setSelectedTopics] = useState<string[]>(['US News', 'World', 'AI & Tech', 'Business', 'Science']);
  const [searchTerm, setSearchTerm] = useState('');
  const [userName, setUserName] = useState('');
  const [streamStatus, setStreamStatus] = useState<string>(''); 
  const [isStreaming, setIsStreaming] = useState(false);

  // Track unique IDs to prevent duplicates
  const loadedIds = useRef<Set<string>>(new Set());
  const topicCycleIndex = useRef(0);
  const nextBatchIndex = useRef(1);
  const feedRef = useRef<HTMLDivElement>(null);
  const loadMoreRef = useRef<HTMLDivElement>(null);
  const initialized = useRef(false);

  const news = useMemo(() => {
    return Object.keys(newsBuckets)
      .map(Number)
      .sort((a, b) => a - b) 
      .flatMap(key => newsBuckets[key]);
  }, [newsBuckets]);

  // Filters out duplicates based on title/id and keeps global registry updated
  const deduplicate = useCallback((items: Byte[]) => {
    return items.filter(item => {
      // Create a simplified key to catch "same news different source" or API repeats
      const key = item.title.toLowerCase().trim().substring(0, 40);
      if (loadedIds.current.has(key)) return false;
      loadedIds.current.add(key);
      return true;
    });
  }, []);

  const getDynamicBatches = useCallback(() => {
    if (selectedTopics.length === 0) return [['Breaking News'], ['Global Trends']];

    // Group selected topics into logical pairs for the initial load
    const chunks: string[][] = [];
    for (let i = 0; i < selectedTopics.length; i += 2) {
      chunks.push(selectedTopics.slice(i, i + 2));
    }
    return chunks.length > 0 ? chunks : [['Breaking News']];
  }, [selectedTopics]);

  const startNewsStream = useCallback(async (isRefresh = false) => {
    if (isStreaming) return;
    setIsStreaming(true);
    setStreamStatus('Syncing feed...');

    if (isRefresh) {
        setNewsBuckets({}); 
        loadedIds.current.clear();
        nextBatchIndex.current = 1;
        topicCycleIndex.current = 0;
        if (feedRef.current) feedRef.current.scrollTop = 0;
    }

    const batches = getDynamicBatches();

    // 1. Fetch First Batch (Top Priority)
    try {
        const rawB0 = await fetchRealTimeNews(batches[0]);
        const b0 = deduplicate(rawB0);

        // If API returns nothing unique, inject static papers once
        const finalB0 = b0.length > 0 ? b0 : deduplicate(PAPERS.slice(0, 4));
        setNewsBuckets(prev => ({ ...prev, 0: finalB0 }));
    } catch (e) {
        setNewsBuckets({ 0: deduplicate(PAPERS.slice(0, 4)) });
    }

    // 2. Load one more batch in background to fill the screen
    if (batches.length > 1) {
        setTimeout(async () => {
            try {
                const rawB1 = await fetchRealTimeNews(batches[1]);
                const b1 = deduplicate(rawB1);
                if (b1.length > 0) {
                    setNewsBuckets(prev => ({ ...prev, 1: b1 }));
                    nextBatchIndex.current = 2;
                }
            } catch (err) {}
        }, 1500);
    }

    setStreamStatus('');
    setIsStreaming(false);
  }, [getDynamicBatches, isStreaming, deduplicate]);

  // Infinite Scroll Handler: Cycles through user interests for uniqueness
  const handleLoadMore = useCallback(async () => {
    if (isStreaming || selectedTopics.length === 0) return;
    setIsStreaming(true);

    // Pick the next topic in the user's interest list to ensure variety
    const topicToFetch = selectedTopics[topicCycleIndex.current % selectedTopics.length];
    topicCycleIndex.current++;

    const batchIdx = nextBatchIndex.current++;

    try {
      const rawNewNews = await fetchRealTimeNews([topicToFetch]);
      const uniqueNews = deduplicate(rawNewNews);

      if (uniqueNews.length > 0) {
        setNewsBuckets(prev => ({ ...prev, [batchIdx]: uniqueNews }));
      } else {
        // If API yielded no unique news for this topic, try one more time with a generic one
        const rawGlobal = await fetchRealTimeNews(['Global Innovation']);
        const uniqueGlobal = deduplicate(rawGlobal);
        if (uniqueGlobal.length > 0) {
          setNewsBuckets(prev => ({ ...prev, [batchIdx]: uniqueGlobal }));
        }
      }
    } catch (err) {
      console.error("Load more failed", err);
    } finally {
      setIsStreaming(false);
    }
  }, [isStreaming, selectedTopics, deduplicate]);

  // Intersection Observer for Infinite Scroll
  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && !isStreaming && news.length > 0) {
          handleLoadMore();
        }
      },
      { threshold: 0.1, rootMargin: '400px' }
    );
    if (loadMoreRef.current) observer.observe(loadMoreRef.current);
    return () => observer.disconnect();
  }, [news.length, isStreaming, handleLoadMore]);

  useEffect(() => {
    if (initialized.current) return;
    initialized.current = true;
    const prefsStr = localStorage.getItem('bytes_prefs');
    if (prefsStr) {
      const prefs = JSON.parse(prefsStr);
      setStoredPrefs(prefs);
    }
  }, []);

  const handleOnboardingComplete = (prefs: UserPreferences) => {
    setSelectedTopics(prefs.topics);
    setUserName(prefs.userName || '');
    localStorage.setItem('bytes_prefs', JSON.stringify(prefs));
    setShowOnboarding(false);
    setTimeout(() => startNewsStream(true), 100);
  };

  const handleLike = (id: string) => {
    setNewsBuckets(prev => {
        const next = {...prev};
        Object.keys(next).forEach(k => {
            const numK = Number(k);
            next[numK] = next[numK].map(item => item.id === id ? {...item, isLiked: !item.isLiked, likes: item.isLiked ? item.likes - 1 : item.likes + 1} : item);
        });
        return next;
    });
  };

  const handleSave = (id: string) => {
    setNewsBuckets(prev => {
        const next = {...prev};
        Object.keys(next).forEach(k => {
            const numK = Number(k);
            next[numK] = next[numK].map(item => item.id === id ? {...item, isSaved: !item.isSaved} : item);
        });
        return next;
    });
  };

  const filteredNews = useMemo(() => {
    if (!searchTerm) return news;
    return news.filter(byte => byte.title.toLowerCase().includes(searchTerm.toLowerCase()));
  }, [news, searchTerm]);

  return (
    <div className="relative h-[100dvh] w-full overflow-hidden text-[#4a044e] bg-[#fff1f2]">
      <InteractiveBackground />
      {showOnboarding ? (
        <Onboarding onComplete={handleOnboardingComplete} existingPrefs={storedPrefs} />
      ) : (
        <div className="relative z-10 w-full h-full animate-fade-in">
          <Navbar 
            onProfileClick={() => setIsDrawerOpen(true)} 
            onSearchClick={() => setIsDrawerOpen(true)} 
            onNotifyClick={() => {}} 
            onLiveClick={() => startNewsStream(true)} 
            isLiveLoading={isStreaming} 
            userName={userName} 
          />
          <div ref={feedRef} className="h-[100dvh] w-full overflow-y-scroll snap-y snap-mandatory no-scrollbar">
            {filteredNews.length > 0 ? (
                filteredNews.map((byte, idx) => <NewsSlide key={`${byte.id}-${idx}`} byte={byte} onLike={handleLike} onSave={handleSave} />)
            ) : (
                <div className="h-full flex items-center justify-center p-8 text-center snap-center">
                    <div className="glass-panel p-8 rounded-[40px] shadow-xl">
                        <h3 className="text-2xl font-serif-display font-bold text-[#831843] mb-4">Syncing with sources...</h3>
                        <div className="w-16 h-1 bg-[#831843]/10 rounded-full mx-auto overflow-hidden"><div className="h-full bg-[#831843] animate-progress"></div></div>
                    </div>
                </div>
            )}

            {/* Load More Trigger */}
            <div ref={loadMoreRef} className="h-20 w-full flex items-center justify-center snap-center pb-20">
                {isStreaming && (
                    <div className="flex items-center gap-3">
                        <div className="w-1.5 h-1.5 bg-[#831843] rounded-full animate-bounce delay-0"></div>
                        <div className="w-1.5 h-1.5 bg-[#831843] rounded-full animate-bounce delay-150"></div>
                        <div className="w-1.5 h-1.5 bg-[#831843] rounded-full animate-bounce delay-300"></div>
                    </div>
                )}
            </div>
          </div>
        </div>
      )}
      <CurateDrawer 
        isOpen={isDrawerOpen} 
        onClose={() => setIsDrawerOpen(false)} 
        selectedTopics={selectedTopics} 
        onTopicToggle={(t) => {
            setSelectedTopics(p => {
                const updated = p.includes(t) ? p.filter(x => x !== t) : [...p, t];
                // Refresh feed if topics changed significantly
                setTimeout(() => startNewsStream(true), 200);
                return updated;
            });
        }} 
        onSearch={setSearchTerm} 
      />
      <style>{`
        @keyframes progress { 0% { width: 0%; transform: translateX(-100%); } 100% { width: 100%; transform: translateX(100%); } }
        .animate-progress { animation: progress 1.5s infinite linear; }
        .animate-fade-in { animation: fade-in 0.8s ease-out forwards; }
        @keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
      `}</style>
    </div>
  );
};

export default App;

