import { PAPERS } from '../constants';
import { Byte } from '../types';

const getCategoryImageUrl = (category: string): string => {
  const map: Record<string, string> = {
    'Business': 'photo-1611974765270-ca12586343bb',
    'Tech': 'photo-1518770660439-4636190af475',
    'Science': 'photo-1507413245164-6160d8298b31',
    'World': 'photo-1521737604893-d14cc237f11d',
    'Finance': 'photo-1611974765270-ca12586343bb',
    'Health': 'photo-1576091160399-112ba8d25d1d',
    'Culture': 'photo-1499750310107-5fef28a66643',
    'Politics': 'photo-1529101091760-61df6be5d187',
  };
  const key = Object.keys(map).find(k => category.includes(k)) || 'World';
  const imgId = map[key] || 'photo-1504711434969-e33886168f5c';
  return `https://images.unsplash.com/${imgId}?auto=format&fit=crop&q=80&w=1200`;
};

const generateFallbackNews = (topicString: string): Byte[] => {
    return PAPERS.slice(0, 8).map((p, i) => ({
        ...p,
        id: `fallback-${Date.now()}-${i}-${Math.random()}`,
        title: p.title,
        publicationDate: "JUST NOW"
    }));
};

/**
 * Improved link matching logic that scores based on headline similarity AND publisher authority.
 */
const findBestVerifiedLink = (headline: string, publisher: string, groundingChunks: any[]) => {
  if (!groundingChunks || groundingChunks.length === 0) return null;

  const hWords = headline.toLowerCase().replace(/[^\w\s]/g, '').split(/\s+/).filter(w => w.length > 3);
  const pWords = publisher.toLowerCase().split(/\s+/).filter(w => w.length > 2);

  const scoredResults = groundingChunks
    .filter(chunk => chunk.web && chunk.web.uri)
    .map(chunk => {
        const cTitle = (chunk.web.title || "").toLowerCase();
        const cUri = chunk.web.uri.toLowerCase();

        let headlineMatchCount = 0;
        hWords.forEach(w => { if (cTitle.includes(w)) headlineMatchCount++; });

        let publisherMatch = 0;
        pWords.forEach(w => { 
            if (cTitle.includes(w) || cUri.includes(w)) publisherMatch++; 
        });

        // Calculate score: 75% weight on headline matching, 25% weight on publisher presence
        const hScore = (headlineMatchCount / Math.max(1, hWords.length)) * 75;
        const pScore = publisherMatch > 0 ? 25 : 0;

        return { uri: chunk.web.uri, score: hScore + pScore };
    })
    .sort((a, b) => b.score - a.score);

  // Threshold increased to 50 for stricter verification
  return scoredResults[0] && scoredResults[0].score > 50 ? scoredResults[0].uri : null;
};

export const fetchRealTimeNews = async (topics: string[]): Promise<Byte[]> => {
  const topicString = topics.length > 0 ? topics.join(', ') : 'Breaking News';

  if (!process.env.API_KEY) return generateFallbackNews(topicString);

  const prompt = `
    Find 10 HIGH-AUTHORITY breaking news stories from the last 24 hours strictly about: ${topicString}. 
    Each story must be a verifiable event, breakthrough, or announcement. Avoid vague or evergreen content.
    For each story, identify the primary reporting outlet (e.g., Bloomberg, Reuters, The Verge).

    Output ONLY a valid JSON array: 
    [{"title": "Accurate Headline", "publisher": "Reputable Source", "abstract": "Concise factual summary", "category": "Specific Topic"}]
  `;

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: { 
        tools: [{ googleSearch: {} }],
        temperature: 0.1, // Lower temperature for stricter factual consistency
        systemInstruction: "You are a world-class news curator and fact-checker. Your mission is to provide 100% accurate, verified, and timely news. Use Google Search grounding to corroborate every single headline and summary you provide. If a story lacks multiple reputable sources or looks like a rumor, ignore it. Output strictly valid JSON."
      },
    });

    let text = response.text || "[]";
    const jsonMatch = text.match(/\[[\s\S]*\]/);
    if (jsonMatch) text = jsonMatch[0];

    const rawData = JSON.parse(text);
    if (!Array.isArray(rawData) || rawData.length === 0) return generateFallbackNews(topicString);

    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

    return rawData.map((item: any, i: number) => {
      const cat = item.category || (topics[0] || "World");
      // Improved verification pass
      let finalUrl = findBestVerifiedLink(item.title, item.publisher, groundingChunks);

      // Secondary fallback: a more targeted search link if grounding verification wasn't perfect
      if (!finalUrl) finalUrl = `https://www.google.com/search?q=${encodeURIComponent(item.title + " " + (item.publisher || ""))}&tbm=nws`;

      const titleHash = item.title.substring(0, 15).replace(/[^\w]/g, '_');
      return {
        id: `live-${titleHash}-${Date.now()}-${i}`,
        title: item.title,
        publisher: item.publisher || "Verified Source",
        authors: ["Bytes Editorial"],
        abstract: item.abstract,
        category: cat,
        readTime: "1 min",
        fileUrl: getCategoryImageUrl(cat),
        likes: Math.floor(Math.random() * 400) + 200,
        comments: Math.floor(Math.random() * 15) + 5,
        publicationDate: "NOW",
        sourceUrl: finalUrl
      } as Byte;
    });

  } catch (e: any) {
    if (e?.message?.includes('quota') || e?.status === 429) {
        console.warn("API quota limit. Using high-signal fallback news.");
    }
    return generateFallbackNews(topicString);
  }
};

import React, { useState, useEffect, useMemo, useRef, useCallback } from 'react';
import Navbar from './components/Navbar';
import NewsSlide from './components/NewsSlide';
import CurateDrawer from './components/CurateDrawer';
import Onboarding from './components/Onboarding';
import InteractiveBackground from './components/InteractiveBackground';
import { PAPERS } from './constants';
import { fetchRealTimeNews } from './services/geminiService';
import { Byte, UserPreferences } from './types';

const App: React.FC = () => {
  const [newsBuckets, setNewsBuckets] = useState<Record<number, Byte[]>>({});
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [showOnboarding, setShowOnboarding] = useState<boolean>(true);
  const [storedPrefs, setStoredPrefs] = useState<UserPreferences | null>(null);
  const [selectedTopics, setSelectedTopics] = useState<string[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [userName, setUserName] = useState('');
  const [streamStatus, setStreamStatus] = useState<string>(''); 
  const [isStreaming, setIsStreaming] = useState(false);

  const loadedIds = useRef<Set<string>>(new Set());
  const nextBatchIndex = useRef(0);
  const topicCycleIndex = useRef(0);
  const feedRef = useRef<HTMLDivElement>(null);
  const loadMoreRef = useRef<HTMLDivElement>(null);
  const initialized = useRef(false);

  const news = useMemo(() => {
    return Object.keys(newsBuckets)
      .map(Number)
      .sort((a, b) => a - b) 
      .flatMap(key => newsBuckets[key]);
  }, [newsBuckets]);

  const deduplicate = useCallback((items: Byte[]) => {
    return items.filter(item => {
      const key = item.title.toLowerCase().trim().substring(0, 45);
      if (loadedIds.current.has(key)) return false;
      loadedIds.current.add(key);
      return true;
    });
  }, []);

  const loadNextBatch = useCallback(async (isInitial = false) => {
    if (isStreaming) return;
    setIsStreaming(true);

    const currentBatchIdx = nextBatchIndex.current;

    // FETCH LOGIC: Reduced from 3 to 2 topics per request. 
    // This improves "Accuracy" because it allows the model to find deeper matches for fewer subjects.
    let fetchTopics = ['Breaking News'];
    if (selectedTopics.length > 0) {
        const topics = [];
        for (let i = 0; i < 2; i++) {
            topics.push(selectedTopics[(topicCycleIndex.current + i) % selectedTopics.length]);
        }
        fetchTopics = topics;
        topicCycleIndex.current += 2;
    }

    setStreamStatus(isInitial ? 'Verifying feed...' : 'Cross-referencing...');

    try {
        const rawNews = await fetchRealTimeNews(fetchTopics);
        const uniqueNews = deduplicate(rawNews);

        const batchData = uniqueNews.length > 0 ? uniqueNews : deduplicate(PAPERS.slice(0, 6));

        setNewsBuckets(prev => ({ ...prev, [currentBatchIdx]: batchData }));
        nextBatchIndex.current++;

        if (isInitial) {
            // Speed optimization: trigger next load soon after first, once UI has settled
            setTimeout(() => {
                setIsStreaming(false); 
                loadNextBatch(false);
            }, 1000);
        }
    } catch (e) {
        setNewsBuckets(prev => ({ ...prev, [currentBatchIdx]: deduplicate(PAPERS.slice(0, 4)) }));
        nextBatchIndex.current++;
    } finally {
        setIsStreaming(false);
        setStreamStatus('');
    }
  }, [isStreaming, selectedTopics, deduplicate]);

  const startNewsStream = useCallback(async (isRefresh = false) => {
    if (isRefresh) {
        setNewsBuckets({}); 
        loadedIds.current.clear();
        nextBatchIndex.current = 0;
        topicCycleIndex.current = 0;
        if (feedRef.current) feedRef.current.scrollTop = 0;
    }
    await loadNextBatch(true);
  }, [loadNextBatch]);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && !isStreaming && !showOnboarding && news.length > 0) {
            loadNextBatch();
        }
      },
      { threshold: 0.05, rootMargin: '600px' }
    );
    if (loadMoreRef.current) observer.observe(loadMoreRef.current);
    return () => observer.disconnect();
  }, [news.length, isStreaming, showOnboarding, loadNextBatch]);

  useEffect(() => {
    if (initialized.current) return;
    initialized.current = true;
    const prefsStr = localStorage.getItem('bytes_prefs');
    if (prefsStr) {
      const prefs = JSON.parse(prefsStr);
      setStoredPrefs(prefs);
      setSelectedTopics(prefs.topics || []);
      setUserName(prefs.userName || '');
    }
  }, []);

  const handleOnboardingComplete = (prefs: UserPreferences) => {
    setSelectedTopics(prefs.topics);
    setUserName(prefs.userName || '');
    localStorage.setItem('bytes_prefs', JSON.stringify(prefs));
    setShowOnboarding(false);
    setTimeout(() => startNewsStream(true), 100);
  };

  const handleLike = (id: string) => {
    setNewsBuckets(prev => {
        const next = {...prev};
        Object.keys(next).forEach(k => {
            const numK = Number(k);
            next[numK] = next[numK].map(item => item.id === id ? {...item, isLiked: !item.isLiked, likes: item.isLiked ? item.likes - 1 : item.likes + 1} : item);
        });
        return next;
    });
  };

  const handleSave = (id: string) => {
    setNewsBuckets(prev => {
        const next = {...prev};
        Object.keys(next).forEach(k => {
            const numK = Number(k);
            next[numK] = next[numK].map(item => item.id === id ? {...item, isSaved: !item.isSaved} : item);
        });
        return next;
    });
  };

  const filteredNews = useMemo(() => {
    if (!searchTerm) return news;
    return news.filter(byte => byte.title.toLowerCase().includes(searchTerm.toLowerCase()));
  }, [news, searchTerm]);

  return (
    <div className="relative h-[100dvh] w-full overflow-hidden text-[#4a044e] bg-[#fff1f2]">
      <InteractiveBackground />

      {showOnboarding ? (
        <Onboarding onComplete={handleOnboardingComplete} existingPrefs={storedPrefs} />
      ) : (
        <div className="relative z-10 w-full h-full animate-fade-in">
          <Navbar 
            onProfileClick={() => setIsDrawerOpen(true)} 
            onSearchClick={() => setIsDrawerOpen(true)} 
            onNotifyClick={() => {}} 
            onLiveClick={() => startNewsStream(true)} 
            isLiveLoading={isStreaming} 
            userName={userName} 
          />

          <div ref={feedRef} className="h-[100dvh] w-full overflow-y-scroll snap-y snap-mandatory no-scrollbar">
            {filteredNews.length > 0 ? (
                <>
                  {filteredNews.map((byte, idx) => (
                    <NewsSlide key={`${byte.id}-${idx}`} byte={byte} onLike={handleLike} onSave={handleSave} />
                  ))}
                </>
            ) : (
                <div className="h-full flex items-center justify-center p-8 text-center snap-center">
                    <div className="glass-panel p-10 rounded-[48px] shadow-2xl max-w-sm w-full border border-white/60">
                        <h3 className="text-2xl font-serif-display font-bold text-[#831843] mb-6">
                            {streamStatus || "Synthesizing Feed..."}
                        </h3>
                        <div className="w-20 h-1.5 bg-[#831843]/10 rounded-full mx-auto overflow-hidden">
                            <div className="h-full bg-gradient-to-r from-[#831843] to-[#be185d] animate-progress"></div>
                        </div>
                    </div>
                </div>
            )}

            <div ref={loadMoreRef} className="h-60 w-full flex items-center justify-center snap-center pb-40">
                {isStreaming && filteredNews.length > 0 && (
                    <div className="flex items-center gap-3 bg-white/60 backdrop-blur-xl px-8 py-4 rounded-full border border-white/60 shadow-xl scale-90 md:scale-100">
                        <div className="w-2 h-2 bg-[#831843] rounded-full animate-bounce delay-0"></div>
                        <div className="w-2 h-2 bg-[#831843] rounded-full animate-bounce delay-150"></div>
                        <div className="w-2 h-2 bg-[#831843] rounded-full animate-bounce delay-300"></div>
                        <span className="text-xs font-bold uppercase tracking-widest text-[#831843] ml-2">Syncing</span>
                    </div>
                )}
            </div>
          </div>
        </div>
      )}

      <CurateDrawer 
        isOpen={isDrawerOpen} 
        onClose={() => setIsDrawerOpen(false)} 
        selectedTopics={selectedTopics} 
        onTopicToggle={(t) => {
            setSelectedTopics(p => {
                const updated = p.includes(t) ? p.filter(x => x !== t) : [...p, t];
                setTimeout(() => startNewsStream(true), 200);
                return updated;
            });
        }} 
        onSearch={setSearchTerm} 
      />

      <style>{`
        @keyframes progress { 
          0% { transform: translateX(-100%); } 
          100% { transform: translateX(100%); } 
        }
        .animate-progress { animation: progress 1.2s infinite linear; }
        .animate-fade-in { animation: fade-in 0.6s ease-out forwards; }
        @keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
      `}</style>
    </div>
  );
};

export default App;

