    'Health': 'photo-1576091160399-112ba8d25d1d',
    'Culture': 'photo-1499750310107-5fef28a66643',
    'Politics': 'photo-1529101091760-61df6be5d187',
  };
  const key = Object.keys(map).find(k => category.includes(k)) || 'World';
  const imgId = map[key] || 'photo-1504711434969-e33886168f5c';
  return `https://images.unsplash.com/${imgId}?auto=format&fit=crop&q=80&w=1200`;
};

/**
 * High-speed interest-based fallback. 
 * Filters internal data to match user interests when API is down.
 */
export const getInterestBasedFallback = (userTopics: string[]): Byte[] => {
  if (!userTopics || userTopics.length === 0) return PAPERS;

  return PAPERS.filter(p => 
    userTopics.some(topic => 
      p.category.toLowerCase().includes(topic.toLowerCase()) || 
      p.title.toLowerCase().includes(topic.toLowerCase())
    )
  ).concat(PAPERS.filter(p => !userTopics.includes(p.category))).slice(0, 15).map((p, i) => ({
    ...p,
    id: `local-${Date.now()}-${i}`,
    isOffline: true,
    publicationDate: "CURATED"
  }));
};

const findBestVerifiedLink = (headline: string, publisher: string, groundingChunks: any[]) => {
  if (!groundingChunks || groundingChunks.length === 0) return null;
  const hWords = headline.toLowerCase().replace(/[^\w\s]/g, '').split(/\s+/).filter(w => w.length > 3);
  const scoredResults = groundingChunks
    .filter(chunk => chunk.web && chunk.web.uri)
    .map(chunk => {
        const cTitle = (chunk.web.title || "").toLowerCase();
        let hMatch = 0;
        hWords.forEach(w => { if (cTitle.includes(w)) hMatch++; });
        return { uri: chunk.web.uri, score: hMatch };
    })
    .sort((a, b) => b.score - a.score);
  return scoredResults[0] && scoredResults[0].score > 2 ? scoredResults[0].uri : null;
};

export const fetchRealTimeNews = async (topics: string[]): Promise<Byte[]> => {
  const topicString = topics.length > 0 ? topics.join(', ') : 'Breaking News';

  if (!process.env.API_KEY) return getInterestBasedFallback(topics);

  // Prompt optimized for SPEED and DENSITY (15 items, less fluff)
  const prompt = `
    Find 15 HIGH-SIGNAL breaking news stories from the last 24h about: ${topicString}. 
    Be extremely specific. Focus on verified headlines. 
    Output as a DENSE JSON array: 
    [{"t": "Headline", "p": "Source", "a": "40-word summary", "c": "Topic"}]
  `;

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: { 
        tools: [{ googleSearch: {} }],
        temperature: 0.1,
        thinkingConfig: { thinkingBudget: 0 }, // DISABLE THINKING FOR SPEED
        systemInstruction: "You are an ultra-fast news JSON generator. Provide high-quality verified news. Use search grounding to ensure accuracy."
      },
    });

    let text = response.text || "[]";
    const jsonMatch = text.match(/\[[\s\S]*\]/);
    if (jsonMatch) text = jsonMatch[0];

    const rawData = JSON.parse(text);
    if (!Array.isArray(rawData) || rawData.length === 0) return getInterestBasedFallback(topics);

    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

    return rawData.map((item: any, i: number) => {
      const title = item.t || item.title;
      const publisher = item.p || item.publisher;
      const abstract = item.a || item.abstract;
      const cat = item.c || item.category || topics[0];

      let finalUrl = findBestVerifiedLink(title, publisher, groundingChunks);
      if (!finalUrl) finalUrl = `https://www.google.com/search?q=${encodeURIComponent(title)}&tbm=nws`;

      return {
        id: `live-${Date.now()}-${i}`,
        title,
        publisher,
        authors: ["Bytes News"],
        abstract,
        category: cat,
        readTime: "1 min",
        fileUrl: getCategoryImageUrl(cat),
        likes: Math.floor(Math.random() * 500) + 100,
        comments: Math.floor(Math.random() * 20),
        publicationDate: "NOW",
        sourceUrl: finalUrl
      } as Byte;
    });

  } catch (e: any) {
    console.warn("Rapid Sync Fallback Active.");
    return getInterestBasedFallback(topics);
  }
};

import React, { useState, useEffect, useMemo, useRef, useCallback } from 'react';
import Navbar from './components/Navbar';
import NewsSlide from './components/NewsSlide';
import CurateDrawer from './components/CurateDrawer';
import Onboarding from './components/Onboarding';
import InteractiveBackground from './components/InteractiveBackground';
import { fetchRealTimeNews, getInterestBasedFallback } from './services/geminiService';
import { Byte, UserPreferences } from './types';

const App: React.FC = () => {
  const [newsBuckets, setNewsBuckets] = useState<Record<number, Byte[]>>({});
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [showOnboarding, setShowOnboarding] = useState<boolean>(true);
  const [storedPrefs, setStoredPrefs] = useState<UserPreferences | null>(null);
  const [selectedTopics, setSelectedTopics] = useState<string[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [userName, setUserName] = useState('');
  const [streamStatus, setStreamStatus] = useState<string>(''); 
  const [isStreaming, setIsStreaming] = useState(false);
  const [isQuotaExceeded, setIsQuotaExceeded] = useState(false);

  const loadedIds = useRef<Set<string>>(new Set());
  const nextBatchIndex = useRef(0);
  const topicCycleIndex = useRef(0);
  const lastFetchTime = useRef<number>(0);
  const feedRef = useRef<HTMLDivElement>(null);
  const loadMoreRef = useRef<HTMLDivElement>(null);
  const initialized = useRef(false);

  const saveToCache = (buckets: Record<number, Byte[]>) => {
    localStorage.setItem('bytes_cached_buckets', JSON.stringify(buckets));
    localStorage.setItem('bytes_cached_ids', JSON.stringify(Array.from(loadedIds.current)));
  };

  const news = useMemo(() => {
    return Object.keys(newsBuckets)
      .map(Number)
      .sort((a, b) => a - b) 
      .flatMap(key => newsBuckets[key]);
  }, [newsBuckets]);

  const deduplicate = useCallback((items: Byte[]) => {
    return items.filter(item => {
      const key = item.title.toLowerCase().trim().substring(0, 45);
      if (loadedIds.current.has(key)) return false;
      loadedIds.current.add(key);
      return true;
    });
  }, []);

  const loadNextBatch = useCallback(async (isInitial = false) => {
    const now = Date.now();
    // Allow initial load to bypass throttle for speed
    if (isStreaming || (now - lastFetchTime.current < 5000 && !isInitial)) return;

    setIsStreaming(true);
    lastFetchTime.current = now;

    const currentBatchIdx = nextBatchIndex.current;

    // Select a mix of user topics for this batch
    let fetchTopics = ['World News'];
    if (selectedTopics.length > 0) {
        const topics = [];
        for (let i = 0; i < 3; i++) {
            topics.push(selectedTopics[(topicCycleIndex.current + i) % selectedTopics.length]);
        }
        fetchTopics = topics;
        topicCycleIndex.current += 3;
    }

    setStreamStatus(isInitial ? `Syncing ${fetchTopics[0]}...` : 'Deep syncing...');

    try {
        const rawNews = await fetchRealTimeNews(fetchTopics);
        const isFallback = rawNews.some(n => n.id.startsWith('local-'));
        setIsQuotaExceeded(isFallback);

        const uniqueNews = deduplicate(rawNews);
        const batchData = uniqueNews.length > 0 ? uniqueNews : deduplicate(getInterestBasedFallback(selectedTopics));

        setNewsBuckets(prev => {
            const updated = { ...prev, [currentBatchIdx]: batchData };
            saveToCache(updated);
            return updated;
        });
        nextBatchIndex.current++;
    } catch (e) {
        setIsQuotaExceeded(true);
        setNewsBuckets(prev => ({ ...prev, [currentBatchIdx]: deduplicate(getInterestBasedFallback(selectedTopics)) }));
        nextBatchIndex.current++;
    } finally {
        setIsStreaming(false);
        setStreamStatus('');
    }
  }, [isStreaming, selectedTopics, deduplicate]);

  const startNewsStream = useCallback(async (isRefresh = false) => {
    if (isRefresh) {
        setNewsBuckets({}); 
        loadedIds.current.clear();
        nextBatchIndex.current = 0;
        topicCycleIndex.current = 0;
        if (feedRef.current) feedRef.current.scrollTop = 0;
    }
    await loadNextBatch(true);
  }, [loadNextBatch]);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && !isStreaming && !showOnboarding && news.length > 0) {
            loadNextBatch();
        }
      },
      { threshold: 0.05, rootMargin: '800px' }
    );
    if (loadMoreRef.current) observer.observe(loadMoreRef.current);
    return () => observer.disconnect();
  }, [news.length, isStreaming, showOnboarding, loadNextBatch]);

  useEffect(() => {
    if (initialized.current) return;
    initialized.current = true;

    const prefsStr = localStorage.getItem('bytes_prefs');
    if (prefsStr) {
      const prefs = JSON.parse(prefsStr);
      setStoredPrefs(prefs);
      setSelectedTopics(prefs.topics || []);
      setUserName(prefs.userName || '');
    }

    const cachedBuckets = localStorage.getItem('bytes_cached_buckets');
    const cachedIds = localStorage.getItem('bytes_cached_ids');
    if (cachedBuckets && cachedIds) {
        try {
            const parsedBuckets = JSON.parse(cachedBuckets);
            const parsedIds = JSON.parse(cachedIds);
            setNewsBuckets(parsedBuckets);
            loadedIds.current = new Set(parsedIds);
            nextBatchIndex.current = Object.keys(parsedBuckets).length;
        } catch(e) {}
    }
  }, []);

  const handleOnboardingComplete = (prefs: UserPreferences) => {
    setSelectedTopics(prefs.topics);
    setUserName(prefs.userName || '');
    localStorage.setItem('bytes_prefs', JSON.stringify(prefs));
    setShowOnboarding(false);
    setTimeout(() => startNewsStream(true), 100);
  };

  const handleLike = (id: string) => {
    setNewsBuckets(prev => {
        const next = {...prev};
        Object.keys(next).forEach(k => {
            const numK = Number(k);
            next[numK] = next[numK].map(item => item.id === id ? {...item, isLiked: !item.isLiked, likes: item.isLiked ? item.likes - 1 : item.likes + 1} : item);
        });
        return next;
    });
  };

  const handleSave = (id: string) => {
    setNewsBuckets(prev => {
        const next = {...prev};
        Object.keys(next).forEach(k => {
            const numK = Number(k);
            next[numK] = next[numK].map(item => item.id === id ? {...item, isSaved: !item.isSaved} : item);
        });
        return next;
    });
  };

  const filteredNews = useMemo(() => {
    if (!searchTerm) return news;
    return news.filter(byte => byte.title.toLowerCase().includes(searchTerm.toLowerCase()));
  }, [news, searchTerm]);

  return (
    <div className="relative h-[100dvh] w-full overflow-hidden text-[#4a044e] bg-[#fff1f2]">
      <InteractiveBackground />

      {showOnboarding ? (
        <Onboarding onComplete={handleOnboardingComplete} existingPrefs={storedPrefs} />
      ) : (
        <div className="relative z-10 w-full h-full animate-fade-in">
          <Navbar 
            onProfileClick={() => setIsDrawerOpen(true)} 
            onSearchClick={() => setIsDrawerOpen(true)} 
            onNotifyClick={() => {}} 
            onLiveClick={() => startNewsStream(true)} 
            isLiveLoading={isStreaming} 
            userName={userName} 
          />

          {isQuotaExceeded && (
            <div className="fixed top-20 left-1/2 -translate-x-1/2 z-[60] animate-fade-in">
                <div className="bg-white/80 backdrop-blur-xl border border-rose-200 px-4 py-1.5 rounded-full shadow-lg flex items-center gap-2">
                    <div className="w-1.5 h-1.5 bg-rose-500 rounded-full animate-pulse"></div>
                    <span className="text-[9px] font-bold uppercase tracking-widest text-[#831843]">Interest-Based Archive</span>
                </div>
            </div>
          )}

          <div ref={feedRef} className="h-[100dvh] w-full overflow-y-scroll snap-y snap-mandatory no-scrollbar">
            {filteredNews.length > 0 ? (
                <>
                  {filteredNews.map((byte, idx) => (
                    <NewsSlide key={`${byte.id}-${idx}`} byte={byte} onLike={handleLike} onSave={handleSave} />
                  ))}
                </>
            ) : (
                <div className="h-full flex items-center justify-center p-8 text-center snap-center">
                    <div className="glass-panel p-10 rounded-[48px] shadow-2xl max-w-sm w-full border border-white/60">
                        <h3 className="text-xl font-serif-display font-bold text-[#831843] mb-6 animate-pulse">
                            {streamStatus || "Syncing Feed..."}
                        </h3>
                        <div className="w-20 h-1 bg-[#831843]/10 rounded-full mx-auto overflow-hidden">
                            <div className="h-full bg-gradient-to-r from-[#831843] to-[#be185d] animate-progress"></div>
                        </div>
                    </div>
                </div>
            )}

            <div ref={loadMoreRef} className="h-40 w-full flex items-center justify-center snap-center pb-20">
                {isStreaming && filteredNews.length > 0 && (
                    <div className="flex items-center gap-3 bg-white/60 backdrop-blur-xl px-6 py-3 rounded-full border border-white/60 shadow-xl">
                        <div className="w-1.5 h-1.5 bg-[#831843] rounded-full animate-bounce"></div>
                        <span className="text-[10px] font-bold uppercase tracking-widest text-[#831843]">Fetching</span>
                    </div>
                )}
            </div>
          </div>
        </div>
      )}

      <CurateDrawer 
        isOpen={isDrawerOpen} 
        onClose={() => setIsDrawerOpen(false)} 
        selectedTopics={selectedTopics} 
        onTopicToggle={(t) => {
            setSelectedTopics(p => {
                const updated = p.includes(t) ? p.filter(x => x !== t) : [...p, t];
                setTimeout(() => startNewsStream(true), 200);
                return updated;
            });
        }} 
        onSearch={setSearchTerm} 
      />

      <style>{`
        @keyframes progress { 
          0% { transform: translateX(-100%); } 
          100% { transform: translateX(100%); } 
        }
        .animate-progress { animation: progress 0.8s infinite linear; }
        .animate-fade-in { animation: fade-in 0.4s ease-out forwards; }
        @keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
      `}</style>
    </div>
  );
};

