  };
  const key = Object.keys(map).find(k => category.includes(k)) || 'World';
  const imgId = map[key] || 'photo-1504711434969-e33886168f5c';
  return `https://images.unsplash.com/${imgId}?auto=format&fit=crop&q=80&w=1200`;
};

/**
 * Intelligent local matching engine. 
 * Ranks internal news based on how many user interests match.
 */
export const getInterestBasedFallback = (userTopics: string[]): Byte[] => {
  if (!userTopics || userTopics.length === 0) return PAPERS;

  const scoredPapers = PAPERS.map(p => {
    let score = 0;
    const content = (p.title + " " + p.category + " " + p.abstract).toLowerCase();
    userTopics.forEach(topic => {
        if (content.includes(topic.toLowerCase())) score += 10;
    });
    return { ...p, score };
  });

  return scoredPapers
    .sort((a, b) => b.score - a.score)
    .map((p, i) => ({
        ...p,
        id: `local-${Date.now()}-${i}`,
        isOffline: true,
        publicationDate: "ARCHIVE"
    }));
};

const findBestVerifiedLink = (headline: string, groundingChunks: any[]) => {
  if (!groundingChunks || groundingChunks.length === 0) return null;
  const hWords = headline.toLowerCase().split(/\s+/).filter(w => w.length > 3);
  const scoredResults = groundingChunks
    .filter(chunk => chunk.web && chunk.web.uri)
    .map(chunk => {
        const cTitle = (chunk.web.title || "").toLowerCase();
        let match = 0;
        hWords.forEach(w => { if (cTitle.includes(w)) match++; });
        return { uri: chunk.web.uri, score: match };
    })
    .sort((a, b) => b.score - a.score);
  return scoredResults[0] && scoredResults[0].score > 2 ? scoredResults[0].uri : null;
};

/**
 * High-efficiency sync. 
 * Fetches one large batch for ALL topics to save quota.
 */
export const fetchRealTimeNews = async (topics: string[]): Promise<Byte[]> => {
  if (!process.env.API_KEY) return getInterestBasedFallback(topics);

  const topicStr = topics.length > 0 ? topics.join(', ') : 'Breaking News';

  // High-density prompt to get the most "bang for buck" from one request
  const prompt = `
    TASK: Find 20 HIGH-SIGNAL breaking news stories from the last 24h.
    TOPICS TO COVER: ${topicStr}.
    INSTRUCTION: Ensure a diverse mix. For each item, provide a factual 3-sentence summary.
    OUTPUT FORMAT: Strictly return a JSON array of objects: 
    [{"t": "Headline", "s": "Source", "a": "Abstract", "c": "Topic"}]
  `;

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: { 
        tools: [{ googleSearch: {} }],
        temperature: 0.1,
        thinkingConfig: { thinkingBudget: 0 },
        systemInstruction: "You are an efficient news aggregator. Focus on speed and precision. Return strictly valid JSON."
      },
    });

    let text = response.text || "[]";
    const jsonMatch = text.match(/\[[\s\S]*\]/);
    if (jsonMatch) text = jsonMatch[0];

    const rawData = JSON.parse(text);
    if (!Array.isArray(rawData) || rawData.length === 0) return getInterestBasedFallback(topics);

    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

    return rawData.map((item: any, i: number) => {
      const title = item.t || item.title;
      const publisher = item.s || item.source || item.publisher;
      const abstract = item.a || item.abstract;
      const cat = item.c || item.category || "World";

      let finalUrl = findBestVerifiedLink(title, groundingChunks);
      if (!finalUrl) finalUrl = `https://www.google.com/search?q=${encodeURIComponent(title)}&tbm=nws`;

      return {
        id: `live-${Date.now()}-${i}`,
        title,
        publisher,
        authors: ["Bytes Editor"],
        abstract,
        category: cat,
        readTime: "1 min",
        fileUrl: getCategoryImageUrl(cat),
        likes: Math.floor(Math.random() * 500) + 200,
        comments: Math.floor(Math.random() * 25),
        publicationDate: "LIVE",
        sourceUrl: finalUrl
      } as Byte;
    });

  } catch (e: any) {
    console.warn("Gemini Quota Hit or Error. Local engine activated.");
    return getInterestBasedFallback(topics);
  }
};

import React, { useState, useEffect, useMemo, useRef, useCallback } from 'react';
import Navbar from './components/Navbar';
import NewsSlide from './components/NewsSlide';
import CurateDrawer from './components/CurateDrawer';
import Onboarding from './components/Onboarding';
import InteractiveBackground from './components/InteractiveBackground';
import { fetchRealTimeNews, getInterestBasedFallback } from './services/geminiService';
import { Byte, UserPreferences } from './types';

const SYNC_TTL = 60 * 60 * 1000; // 1 hour Cache TTL

const App: React.FC = () => {
  const [news, setNews] = useState<Byte[]>([]);
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [showOnboarding, setShowOnboarding] = useState<boolean>(true);
  const [storedPrefs, setStoredPrefs] = useState<UserPreferences | null>(null);
  const [selectedTopics, setSelectedTopics] = useState<string[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [userName, setUserName] = useState('');
  const [isStreaming, setIsStreaming] = useState(false);
  const [lastSyncTime, setLastSyncTime] = useState<number | null>(null);
  const [isQuotaExceeded, setIsQuotaExceeded] = useState(false);

  const initialized = useRef(false);
  const feedRef = useRef<HTMLDivElement>(null);

  const saveToCache = (items: Byte[]) => {
    localStorage.setItem('bytes_cached_news', JSON.stringify(items));
    localStorage.setItem('bytes_last_sync', Date.now().toString());
  };

  /**
   * CONSOLIDATED SYNC:
   * Fetches news for all interests in one call.
   */
  const performGlobalSync = useCallback(async (force = false) => {
    if (isStreaming) return;

    // Quota Protection: If synced recently, don't call API again unless forced
    const now = Date.now();
    if (!force && lastSyncTime && (now - lastSyncTime < SYNC_TTL)) {
        console.log("Using fresh cache. Skipping API call.");
        return;
    }

    setIsStreaming(true);
    setIsQuotaExceeded(false);

    try {
        const rawNews = await fetchRealTimeNews(selectedTopics);
        const isLocal = rawNews.some(n => n.id.startsWith('local-'));

        setIsQuotaExceeded(isLocal);
        setNews(rawNews);
        setLastSyncTime(now);
        saveToCache(rawNews);

    } catch (e) {
        setIsQuotaExceeded(true);
        const fallback = getInterestBasedFallback(selectedTopics);
        setNews(fallback);
    } finally {
        setIsStreaming(false);
    }
  }, [isStreaming, selectedTopics, lastSyncTime]);

  // Initial Data Load Logic
  useEffect(() => {
    if (initialized.current) return;
    initialized.current = true;

    // 1. Load User Prefs
    const prefsStr = localStorage.getItem('bytes_prefs');
    if (prefsStr) {
      const prefs = JSON.parse(prefsStr);
      setStoredPrefs(prefs);
      setSelectedTopics(prefs.topics || []);
      setUserName(prefs.userName || '');
      setShowOnboarding(false);
    }

    // 2. Load Cache (Instant Load)
    const cachedNews = localStorage.getItem('bytes_cached_news');
    const cachedSync = localStorage.getItem('bytes_last_sync');
    if (cachedNews && cachedSync) {
        setNews(JSON.parse(cachedNews));
        setLastSyncTime(parseInt(cachedSync));
    }
  }, []);

  // Trigger sync only if needed when topics change
  useEffect(() => {
    if (!showOnboarding && selectedTopics.length > 0) {
      const now = Date.now();
      if (!lastSyncTime || (now - lastSyncTime > SYNC_TTL)) {
        performGlobalSync();
      }
    }
  }, [selectedTopics, showOnboarding, performGlobalSync, lastSyncTime]);

  const handleOnboardingComplete = (prefs: UserPreferences) => {
    setSelectedTopics(prefs.topics);
    setUserName(prefs.userName || '');
    localStorage.setItem('bytes_prefs', JSON.stringify(prefs));
    setShowOnboarding(false);
    performGlobalSync(true); // Force first sync
  };

  const handleLike = (id: string) => {
    setNews(prev => prev.map(n => n.id === id ? {...n, isLiked: !n.isLiked, likes: n.isLiked ? n.likes - 1 : n.likes + 1} : n));
  };

  const handleSave = (id: string) => {
    setNews(prev => prev.map(n => n.id === id ? {...n, isSaved: !n.isSaved} : n));
  };

  const filteredNews = useMemo(() => {
    if (!searchTerm) return news;
    return news.filter(byte => byte.title.toLowerCase().includes(searchTerm.toLowerCase()));
  }, [news, searchTerm]);

  return (
    <div className="relative h-[100dvh] w-full overflow-hidden text-[#4a044e] bg-[#fff1f2]">
      <InteractiveBackground />

      {showOnboarding ? (
        <Onboarding onComplete={handleOnboardingComplete} existingPrefs={storedPrefs} />
      ) : (
        <div className="relative z-10 w-full h-full animate-fade-in">
          <Navbar 
            onProfileClick={() => setIsDrawerOpen(true)} 
            onSearchClick={() => setIsDrawerOpen(true)} 
            onNotifyClick={() => {}} 
            onLiveClick={() => performGlobalSync(true)} 
            isLiveLoading={isStreaming} 
            userName={userName} 
          />

          {/* Sync Status Overlay */}
          <div className="fixed top-20 left-1/2 -translate-x-1/2 z-[60] flex flex-col items-center gap-2 pointer-events-none">
              {isQuotaExceeded && (
                <div className="bg-white/80 backdrop-blur-xl border border-rose-200 px-4 py-1.5 rounded-full shadow-lg animate-fade-in">
                    <span className="text-[9px] font-bold uppercase tracking-widest text-[#831843]">Archived Digest</span>
                </div>
              )}
              {lastSyncTime && !isStreaming && (
                <div className="text-[8px] font-bold uppercase tracking-[0.2em] text-[#831843]/40 bg-white/30 backdrop-blur-sm px-3 py-1 rounded-full border border-white/40">
                    Last Synced: {Math.floor((Date.now() - lastSyncTime) / 60000)}m ago
                </div>
              )}
          </div>

          <div ref={feedRef} className="h-[100dvh] w-full overflow-y-scroll snap-y snap-mandatory no-scrollbar">
            {filteredNews.length > 0 ? (
                <>
                  {filteredNews.map((byte, idx) => (
                    <NewsSlide key={`${byte.id}-${idx}`} byte={byte} onLike={handleLike} onSave={handleSave} />
                  ))}
                  {/* End of Feed Sentinel */}
                  <div className="h-[100dvh] w-full flex flex-col items-center justify-center snap-center p-12 text-center">
                      <div className="glass-card p-10 rounded-[40px] border border-white/60 shadow-xl max-w-sm">
                          <h3 className="text-xl font-serif-display font-bold text-[#4a044e] mb-4">You're caught up!</h3>
                          <p className="text-xs text-[#831843]/60 mb-8 leading-relaxed">We'll fetch fresh stories automatically soon, or you can force a refresh below.</p>
                          <button 
                            onClick={() => performGlobalSync(true)}
                            className="w-full py-4 bg-[#831843] text-white rounded-full font-bold text-[10px] uppercase tracking-widest shadow-lg active:scale-95 transition-transform"
                          >
                            Refresh Live Feed
                          </button>
                      </div>
                  </div>
                </>
            ) : (
                <div className="h-full flex items-center justify-center p-8 text-center snap-center">
                    <div className="glass-panel p-10 rounded-[48px] shadow-2xl max-w-sm w-full border border-white/60">
                        <div className="relative w-12 h-12 mx-auto mb-6">
                            <div className="absolute inset-0 bg-rose-200 rounded-full animate-ping opacity-20"></div>
                            <div className="relative w-full h-full bg-[#831843] rounded-full flex items-center justify-center">
                                <svg className="w-6 h-6 text-white animate-spin" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                            </div>
                        </div>
                        <h3 className="text-xl font-serif-display font-bold text-[#831843] mb-2">Syncing Your Interests</h3>
                        <p className="text-[10px] font-bold uppercase tracking-widest text-[#831843]/40">Synthesizing personalized feed...</p>
                    </div>
                </div>
            )}
          </div>
        </div>
      )}

      <CurateDrawer 
        isOpen={isDrawerOpen} 
        onClose={() => setIsDrawerOpen(false)} 
        selectedTopics={selectedTopics} 
        onTopicToggle={(t) => {
            setSelectedTopics(p => {
                const next = p.includes(t) ? p.filter(x => x !== t) : [...p, t];
                // Reset sync time to allow immediate refresh for new topics
                setLastSyncTime(null);
                return next;
            });
        }} 
        onSearch={setSearchTerm} 
      />

      <style>{`
        .animate-fade-in { animation: fade-in 0.4s ease-out forwards; }
        @keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
      `}</style>
    </div>
  );
};

export default App;

