const saveToDatabase = (news: Byte[], status: SyncMetadata['status']) => {
  localStorage.setItem(DB_KEY, JSON.stringify(news));
  localStorage.setItem(META_KEY, JSON.stringify({
    lastSyncTimestamp: Date.now(),
    status,
    version: '1.0'
  }));
};

/**
 * DETERMINISTIC SYNC ENGINE
 * Only called by the background worker.
 */
export const syncFeedWithBackend = async (topics: string[]): Promise<{ success: boolean; status: SyncMetadata['status'] }> => {
  if (!process.env.API_KEY) return { success: false, status: 'FAILED' };

  const currentBatch = getDatabaseFeed();
  const topicQuery = topics.length > 0 ? topics.join(', ') : 'Breaking News';
  const today = new Date().toISOString().split('T')[0];

  const prompt = `
    Find 15 distinct breaking news stories from ${today} strictly about: ${topicQuery}.
    Focus on specific announcements, product launches, or policy changes.
  `;

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              source: { type: Type.STRING },
              summary: { type: Type.STRING },
              category: { type: Type.STRING }
            },
            required: ["title", "source", "summary", "category"]
          }
        },
        systemInstruction: "You are a professional news editor. Output only valid JSON. Ensure search grounding is used for real-time accuracy."
      }
    });

    const rawData = JSON.parse(response.text || "[]");
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

    // Deduplication Logic (Title-Hash)
    const existingTitles = new Set(currentBatch.map(n => n.title.toLowerCase().trim()));
    const newItems: Byte[] = [];

    rawData.forEach((item: any, i: number) => {
      if (!existingTitles.has(item.title.toLowerCase().trim())) {
        newItems.push({
          id: `live-${Date.now()}-${i}`,
          title: item.title,
          publisher: item.source,
          authors: ["Bytes Global"],
          abstract: item.summary,
          category: item.category,
          readTime: "1 min",
          fileUrl: getCategoryImageUrl(item.category),
          likes: Math.floor(Math.random() * 400) + 100,
          comments: Math.floor(Math.random() * 20),
          publicationDate: "NOW",
          sourceUrl: `https://www.google.com/search?q=${encodeURIComponent(item.title)}&tbm=nws`,
          syncTimestamp: Date.now()
        });
      }
    });

    // Merge & Prune (Keep last 50 items)
    const updatedFeed = [...newItems, ...currentBatch].slice(0, 50);
    saveToDatabase(updatedFeed, 'IDLE');
    return { success: true, status: 'IDLE' };

  } catch (error: any) {
    if (error?.status === 429 || error?.message?.includes('quota')) {
      saveToDatabase(currentBatch, 'QUOTA_EXCEEDED');
      return { success: false, status: 'QUOTA_EXCEEDED' };
    }
    saveToDatabase(currentBatch, 'FAILED');
    return { success: false, status: 'FAILED' };
  }
};

import React, { useState, useEffect, useMemo, useRef, useCallback } from 'react';
import Navbar from './components/Navbar';
import NewsSlide from './components/NewsSlide';
