/**
 * PRODUCTION SYNC ENGINE
 * Fetches high-density news batches, deduplicates, and saves to persistent store.
 */
export const syncWithBackend = async (topics: string[]): Promise<{ success: boolean; status: SyncMetadata['status'] }> => {
  if (!process.env.API_KEY) return { success: false, status: 'FAILED' };

  const currentDb = getDatabaseFeed();
  const topicQuery = topics.length > 0 ? topics.join(', ') : 'Breaking Global News';
  const today = new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric' });

  // 1. High-Density Unified Prompt
  const prompt = `
    Find 15-20 distinct, verifiable breaking news stories from the last 24 hours about: ${topicQuery}.
    Focus on impact, specific data points, and factual clarity.
  `;

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              t: { type: Type.STRING, description: "Short punchy headline" },
              s: { type: Type.STRING, description: "News source/publisher" },
              a: { type: Type.STRING, description: "3-sentence technical summary" },
              c: { type: Type.STRING, description: "Best category (Tech, World, Science, Business)" }
            },
            required: ["t", "s", "a", "c"]
          }
        },
        systemInstruction: "You are a senior news aggregator. Provide diverse, factual, non-clickbait news in strictly valid JSON format."
      }
    });

    const rawData = JSON.parse(response.text || "[]");
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

    // 2. Deduplication & Transformation
    const existingTitles = new Set(currentDb.map(n => n.title.toLowerCase().trim()));
    const newItems: Byte[] = [];

    rawData.forEach((item: any, i: number) => {
      const title = item.t;
      if (!existingTitles.has(title.toLowerCase().trim())) {
        // Find best source URL from grounding
        let sourceUrl = `https://www.google.com/search?q=${encodeURIComponent(title)}&tbm=nws`;
        const words = title.toLowerCase().split(/\s+/).slice(0, 3);
        const match = groundingChunks.find(c => c.web?.title?.toLowerCase().includes(words[0]));
        if (match?.web?.uri) sourceUrl = match.web.uri;

        newItems.push({
          id: `live-${Date.now()}-${i}`,
          title,
          publisher: item.s,
          authors: ["Bytes Digest"],
          abstract: item.a,
          category: item.c,
          readTime: "1 min",
          fileUrl: getCategoryImageUrl(item.c),
          likes: Math.floor(Math.random() * 500) + 100,
          comments: Math.floor(Math.random() * 15),
          publicationDate: today,
          sourceUrl,
          syncTimestamp: Date.now()
        });
      }
    });

    // 3. Persistent Save (Keep top 60 items)
    const updatedFeed = [...newItems, ...currentDb].slice(0, 60);
    updateDatabase(updatedFeed, 'IDLE');
    return { success: true, status: 'IDLE' };

  } catch (error: any) {
    console.error("Sync Engine Error:", error);

    // Handle Quota Specifically
    if (error?.status === 429 || error?.message?.includes('quota')) {
      updateDatabase(currentDb, 'QUOTA_EXCEEDED');
      return { success: false, status: 'QUOTA_EXCEEDED' };
    }

    updateDatabase(currentDb, 'FAILED');
    return { success: false, status: 'FAILED' };
  }
};

