  if (!data) return PAPERS; 
  return JSON.parse(data);
};

export const getSyncMetadata = (): SyncMetadata => {
  const data = localStorage.getItem(META_KEY);
  return data ? JSON.parse(data) : { lastSyncTimestamp: 0, status: 'IDLE', version: '1.0' };
};

const updateDatabase = (news: Byte[], status: SyncMetadata['status']) => {
  localStorage.setItem(DB_KEY, JSON.stringify(news));
  localStorage.setItem(META_KEY, JSON.stringify({
    lastSyncTimestamp: Date.now(),
    status,
    version: '1.0'
  }));
};

/**
 * PRODUCTION SYNC ENGINE
 * Optimized for Gemini Free Tier Quota Management.
 */
export const syncWithBackend = async (topics: string[]): Promise<{ success: boolean; status: SyncMetadata['status'] }> => {
  const meta = getSyncMetadata();
  const now = Date.now();

  // 1. Cooldown Check: If we hit quota recently, don't even try.
  if (meta.status === 'QUOTA_EXCEEDED' && (now - meta.lastSyncTimestamp < QUOTA_COOLDOWN_MS)) {
    console.warn("Sync Engine: In Quota Cooldown. Skipping request.");
    return { success: false, status: 'QUOTA_EXCEEDED' };
  }

  if (!process.env.API_KEY) return { success: false, status: 'FAILED' };

  const currentDb = getDatabaseFeed();
  const topicQuery = topics.length > 0 ? topics.join(', ') : 'Latest global headlines across tech, business, and science';
  const todayDate = new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });

  // High-Density Prompt: 20 stories at once to maximize request value.
  const prompt = `
    TASK: Research and aggregate exactly 20 distinct, verified news stories published on or after ${todayDate}.
    TOPICS: ${topicQuery}.
    DIRECTIONS: Focus on major announcements, market shifts, and scientific breakthroughs. Avoid clickbait.
  `;

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              t: { type: Type.STRING, description: "Punchy, informative headline" },
              s: { type: Type.STRING, description: "Official news source" },
              a: { type: Type.STRING, description: "3-sentence technical summary explaining what happened and why it matters." },
              c: { type: Type.STRING, description: "Category: Tech, World, Science, Business, or Finance" }
            },
            required: ["t", "s", "a", "c"]
          }
        },
        systemInstruction: "You are a professional news wire editor. Your output must be strictly valid JSON. Always use Google Search to ensure the news is real and from today."
      }
    });

    const rawData = JSON.parse(response.text || "[]");
    if (!Array.isArray(rawData) || rawData.length === 0) {
      throw new Error("Empty response from model");
    }

    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const existingTitles = new Set(currentDb.map(n => n.title.toLowerCase().trim()));
    const newItems: Byte[] = [];

    rawData.forEach((item: any, i: number) => {
      const title = item.t;
      if (!existingTitles.has(title.toLowerCase().trim())) {
        let sourceUrl = `https://www.google.com/search?q=${encodeURIComponent(title)}&tbm=nws`;

        // Match grounding URLs
        const match = groundingChunks.find(c => 
          c.web?.title?.toLowerCase().includes(title.split(' ')[0].toLowerCase()) ||
          title.toLowerCase().includes(c.web?.title?.toLowerCase() || '---')
        );
        if (match?.web?.uri) sourceUrl = match.web.uri;

        newItems.push({
          id: `live-${Date.now()}-${i}`,
          title,
          publisher: item.s,
          authors: ["Bytes Global"],
          abstract: item.a,
          category: item.c,
          readTime: "1 min",
          fileUrl: getCategoryImageUrl(item.c),
          likes: Math.floor(Math.random() * 900) + 100,
          comments: Math.floor(Math.random() * 25),
          publicationDate: "LATEST",
          sourceUrl,
          syncTimestamp: Date.now()
        });
      }
    });

    // Merge and persist (Keep last 100 items for robust fallback)
    const updatedFeed = [...newItems, ...currentDb].slice(0, 100);
    updateDatabase(updatedFeed, 'IDLE');
    return { success: true, status: 'IDLE' };

  } catch (error: any) {
    console.error("Sync Engine Error:", error);

    // Explicit 429 / Quota Handling
    if (error?.status === 429 || error?.message?.includes('quota') || error?.message?.includes('429')) {
      console.warn("Gemini Quota Exceeded. Entering cooldown.");
      updateDatabase(currentDb, 'QUOTA_EXCEEDED');
      return { success: false, status: 'QUOTA_EXCEEDED' };
    }

    updateDatabase(currentDb, 'FAILED');
    return { success: false, status: 'FAILED' };
  }
};

import React, { useState, useEffect, useMemo, useRef, useCallback } from 'react';
import Navbar from './components/Navbar';
import NewsSlide from './components/NewsSlide';
import CurateDrawer from './components/CurateDrawer';
import Onboarding from './components/Onboarding';
import InteractiveBackground from './components/InteractiveBackground';
import { getDatabaseFeed, getSyncMetadata, syncWithBackend } from './services/geminiService';
import { Byte, UserPreferences, SyncMetadata } from './types';

const SYNC_INTERVAL_MS = 30 * 60 * 1000; // 30 minutes

const App: React.FC = () => {
  const [news, setNews] = useState<Byte[]>([]);
  const [syncMeta, setSyncMeta] = useState<SyncMetadata>({ lastSyncTimestamp: 0, status: 'IDLE', version: '1.0' });
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [showOnboarding, setShowOnboarding] = useState<boolean>(true);
  const [storedPrefs, setStoredPrefs] = useState<UserPreferences | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const initialized = useRef(false);

  const refreshUI = useCallback(() => {
    const feed = getDatabaseFeed();
    const meta = getSyncMetadata();
    setNews(feed);
    setSyncMeta(meta);
  }, []);

  const runBackgroundSync = useCallback(async (force = false) => {
    if (syncMeta.status === 'SYNCING') return;

    const prefsStr = localStorage.getItem('bytes_prefs');
    if (!prefsStr) return;
    const topics = JSON.parse(prefsStr).topics;

    const now = Date.now();
    const isStale = now - syncMeta.lastSyncTimestamp > SYNC_INTERVAL_MS;

    // Strict throttle unless forced
    if (!force && !isStale && syncMeta.status !== 'FAILED') {
      return;
    }

    setSyncMeta(prev => ({ ...prev, status: 'SYNCING' }));
    await syncWithBackend(topics);
    refreshUI();
  }, [syncMeta.status, syncMeta.lastSyncTimestamp, refreshUI]);

  useEffect(() => {
    if (initialized.current) return;
    initialized.current = true;

    const prefsStr = localStorage.getItem('bytes_prefs');
    if (prefsStr) {
      setStoredPrefs(JSON.parse(prefsStr));
      setShowOnboarding(false);
    }

    refreshUI();

    if (prefsStr) {
      runBackgroundSync();
    }
  }, [refreshUI, runBackgroundSync]);

  const handleOnboardingComplete = (prefs: UserPreferences) => {
    localStorage.setItem('bytes_prefs', JSON.stringify(prefs));
    setStoredPrefs(prefs);
    setShowOnboarding(false);
    refreshUI();
    runBackgroundSync(true); 
  };

  const handleLike = (id: string) => {
    setNews(prev => prev.map(n => n.id === id ? {...n, isLiked: !n.isLiked, likes: n.isLiked ? n.likes - 1 : n.likes + 1} : n));
  };

  const handleSave = (id: string) => {
    setNews(prev => prev.map(n => n.id === id ? {...n, isSaved: !n.isSaved} : n));
  };

  const filteredNews = useMemo(() => {
    if (!searchTerm) return news;
    return news.filter(byte => byte.title.toLowerCase().includes(searchTerm.toLowerCase()));
  }, [news, searchTerm]);

  // Calculate cooldown remaining
  const cooldownRemaining = useMemo(() => {
    if (syncMeta.status !== 'QUOTA_EXCEEDED') return 0;
    const elapsed = Date.now() - syncMeta.lastSyncTimestamp;
    const remaining = 30 * 60 * 1000 - elapsed;
    return Math.max(0, Math.ceil(remaining / 60000));
  }, [syncMeta.status, syncMeta.lastSyncTimestamp]);

  return (
    <div className="relative h-[100dvh] w-full overflow-hidden text-[#4a044e] bg-[#fff1f2]">
      <InteractiveBackground />

      {showOnboarding ? (
        <Onboarding onComplete={handleOnboardingComplete} existingPrefs={storedPrefs} />
      ) : (
        <div className="relative z-10 w-full h-full animate-fade-in">
          <Navbar 
            onProfileClick={() => setIsDrawerOpen(true)} 
            onSearchClick={() => setIsDrawerOpen(true)} 
            onNotifyClick={() => {}} 
            onLiveClick={() => runBackgroundSync(true)} 
            isLiveLoading={syncMeta.status === 'SYNCING'} 
            userName={storedPrefs?.userName} 
          />

          {/* Persistent Sync Status Alerts */}
          <div className="fixed top-20 left-1/2 -translate-x-1/2 z-[60] flex flex-col items-center gap-2 pointer-events-none w-full px-4">
              {syncMeta.status === 'QUOTA_EXCEEDED' && (
                <div className="bg-rose-600 text-white px-5 py-2 rounded-full shadow-2xl animate-fade-in border border-rose-400 flex items-center gap-3">
                    <div className="w-2 h-2 bg-white rounded-full animate-pulse"></div>
                    <span className="text-[10px] font-bold uppercase tracking-widest">
                      {cooldownRemaining > 0 ? `API Cool-down: ${cooldownRemaining}m remaining` : 'Quota Exceeded: Using Archive'}
                    </span>
                </div>
              )}
              {syncMeta.status === 'SYNCING' && (
                <div className="bg-white/60 backdrop-blur-md px-5 py-2 rounded-full border border-white/60 shadow-lg">
                   <span className="text-[10px] font-bold uppercase tracking-[0.2em] text-[#831843] animate-pulse">Syncing Global Sources...</span>
                </div>
              )}
          </div>

          <div className="h-[100dvh] w-full overflow-y-scroll snap-y snap-mandatory no-scrollbar">
            {filteredNews.length > 0 ? (
                <>
                  {filteredNews.map((byte, idx) => (
                    <NewsSlide key={`${byte.id}-${idx}`} byte={byte} onLike={handleLike} onSave={handleSave} />
                  ))}

                  {/* End of Feed / Refresh Trigger */}
                  <div className="h-[100dvh] w-full flex flex-col items-center justify-center snap-center p-12 text-center bg-white/20 backdrop-blur-sm">
                      <div className="glass-card p-10 rounded-[48px] shadow-2xl border border-white/60 max-w-xs">
                          <h3 className="text-xl font-serif-display font-bold text-[#4a044e] mb-4">You're caught up.</h3>
                          <p className="text-xs text-[#831843]/60 mb-8 leading-relaxed">
                            {syncMeta.status === 'QUOTA_EXCEEDED' 
                              ? `Gemini is currently cooling down. Fresh news will be available in about ${cooldownRemaining} minutes.` 
                              : "We refresh our intelligence every 30 minutes to ensure high-signal content."}
                          </p>
                          <button 
                            onClick={() => runBackgroundSync(true)}
                            disabled={syncMeta.status === 'SYNCING' || (syncMeta.status === 'QUOTA_EXCEEDED' && cooldownRemaining > 0)}
                            className="w-full py-4 bg-[#831843] text-white rounded-full font-bold text-[10px] uppercase tracking-widest shadow-xl active:scale-95 transition-all disabled:opacity-30 disabled:grayscale"
                          >
                            {syncMeta.status === 'SYNCING' ? 'Syncing...' : 'Refresh Feed'}
                          </button>
                      </div>
                  </div>
                </>
            ) : (
                <div className="h-full flex items-center justify-center p-8 text-center snap-center">
                    <div className="glass-panel p-10 rounded-[48px] shadow-2xl max-w-sm w-full border border-white/60">
                        <div className="w-12 h-12 bg-rose-100 rounded-full mx-auto mb-6 flex items-center justify-center">
                            <svg className="w-6 h-6 text-[#831843] animate-spin" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                        </div>
                        <h3 className="text-xl font-serif-display font-bold text-[#831843] mb-2">Syncing Data</h3>
                        <p className="text-[10px] font-bold uppercase tracking-widest text-[#831843]/40">Aggregating global vectors</p>
                    </div>
                </div>
            )}
          </div>
        </div>
      )}

      <CurateDrawer 
        isOpen={isDrawerOpen} 
        onClose={() => setIsDrawerOpen(false)} 
        selectedTopics={storedPrefs?.topics || []} 
        onTopicToggle={(t) => {
            const nextTopics = (storedPrefs?.topics || []).includes(t) 
              ? storedPrefs!.topics.filter(x => x !== t) 
              : [...(storedPrefs?.topics || []), t];
            const nextPrefs = { ...storedPrefs!, topics: nextTopics };
            localStorage.setItem('bytes_prefs', JSON.stringify(nextPrefs));
            setStoredPrefs(nextPrefs);
            runBackgroundSync(true); 
        }} 
        onSearch={setSearchTerm} 
      />

      <style>{`
        .animate-fade-in { animation: fade-in 0.6s ease-out forwards; }
        @keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
      `}</style>
    </div>
  );
};

