import { GoogleGenAI, Type } from "@google/genai";
import { Byte, SyncMetadata } from '../types';

const DB_KEY = 'bytes_news_database';
const META_KEY = 'bytes_sync_metadata';
const SYNC_COOLDOWN_MS = 15 * 60 * 1000; // 15 mins

const getCategoryImageUrl = (category: string): string => {
  const map: Record<string, string> = {
    'Business': 'photo-1611974765270-ca12586343bb',
    'Tech': 'photo-1518770660439-4636190af475',
    'Science': 'photo-1507413245164-6160d8298b31',
    'World': 'photo-1521737604893-d14cc237f11d',
    'Finance': 'photo-1611974765270-ca12586343bb',
    'Health': 'photo-1576091160399-112ba8d25d1d',
    'Culture': 'photo-1499750310107-5fef28a66643',
    'Politics': 'photo-1529101091760-61df6be5d187',
  };
  const key = Object.keys(map).find(k => category.includes(k)) || 'World';
  const imgId = map[key] || 'photo-1504711434969-e33886168f5c';
  return `https://images.unsplash.com/${imgId}?auto=format&fit=crop&q=80&w=1200`;
};

export const getDatabaseFeed = (): Byte[] => {
  const data = localStorage.getItem(DB_KEY);
  return data ? JSON.parse(data) : [];
};

export const getSyncMetadata = (): SyncMetadata => {
  const data = localStorage.getItem(META_KEY);
  return data ? JSON.parse(data) : { lastSyncTimestamp: 0, status: 'IDLE', version: '1.1' };
};

const updateStore = (news: Byte[], status: SyncMetadata['status']) => {
  localStorage.setItem(DB_KEY, JSON.stringify(news));
  localStorage.setItem(META_KEY, JSON.stringify({
    lastSyncTimestamp: Date.now(),
    status,
    version: '1.1'
  }));
};

/**
 * DYNAMIC NEWS ENGINE
 * Strictly fetches actual news from the internet. No hardcoded data.
 */
export const syncWithBackend = async (topics: string[]): Promise<{ success: boolean; status: SyncMetadata['status'] }> => {
  const meta = getSyncMetadata();
  const now = Date.now();

  // Quota Protection
  if (meta.status === 'QUOTA_EXCEEDED' && (now - meta.lastSyncTimestamp < SYNC_COOLDOWN_MS)) {
    return { success: false, status: 'QUOTA_EXCEEDED' };
  }

  if (!process.env.API_KEY) return { success: false, status: 'FAILED' };

  const currentDb = getDatabaseFeed();
  const topicQuery = topics.length > 0 ? topics.join(', ') : 'Global top headlines and breaking news';
  const today = new Date().toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });

  const prompt = `
    Find and aggregate exactly 15 verified, significant news stories published globally on ${today}.
    Focus on: ${topicQuery}.
    Rules: 
    1. Only include real events verified by major news outlets.
    2. Ensure summaries are objective and data-rich.
    3. Categorize into: Tech, World, Science, Business, or Finance.
  `;

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              t: { type: Type.STRING, description: "Headline" },
              p: { type: Type.STRING, description: "Primary Source" },
              a: { type: Type.STRING, description: "30-word detailed summary" },
              c: { type: Type.STRING, description: "Category" }
            },
            required: ["t", "p", "a", "c"]
          }
        },
        systemInstruction: "You are a real-time news intelligence officer. Only provide verified news from today. Output valid JSON."
      }
    });

    const rawData = JSON.parse(response.text || "[]");
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

    const existingTitles = new Set(currentDb.map(n => n.title.toLowerCase().trim()));
    const newItems: Byte[] = [];

    rawData.forEach((item: any, i: number) => {
      const title = item.t;
      if (!existingTitles.has(title.toLowerCase().trim())) {
        let sourceUrl = `https://www.google.com/search?q=${encodeURIComponent(title)}&tbm=nws`;

        // Link resolution from Google Search Grounding
        const match = groundingChunks.find(c => 
          c.web?.title?.toLowerCase().includes(title.split(' ')[0].toLowerCase())
        );
        if (match?.web?.uri) sourceUrl = match.web.uri;

        newItems.push({
          id: `live-${Date.now()}-${i}`,
          title,
          publisher: item.p,
          authors: ["Verified Source"],
          abstract: item.a,
          category: item.c,
          readTime: "1 min",
          fileUrl: getCategoryImageUrl(item.c),
          likes: Math.floor(Math.random() * 400) + 100,
          comments: Math.floor(Math.random() * 15),
          publicationDate: "LATEST",
          sourceUrl,
          syncTimestamp: Date.now()
        });
      }
    });

    const updatedFeed = [...newItems, ...currentDb].slice(0, 100);
    updateStore(updatedFeed, 'IDLE');
    return { success: true, status: 'IDLE' };

  } catch (error: any) {
    console.error("News Sync Failed:", error);
    if (error?.status === 429) {
      updateStore(currentDb, 'QUOTA_EXCEEDED');
      return { success: false, status: 'QUOTA_EXCEEDED' };
    }
    updateStore(currentDb, 'FAILED');
    return { success: false, status: 'FAILED' };
  }
};

